  Instrument(
    id: 'separador-balfour',
    isNew: true,
    name: LocalizedText(ca: 'Separador de Balfour', es: 'Separador de Balfour', en: 'Balfour retractor'),
    category: InstrumentCategory.separacion,
    aliases: ['Balfour retractor', 'Balfour abdominal retractor'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador autoestàtic amb un marc metàl·lic i dues (o tres) fulles laterals que es bloquegen amb una cremallera central.',
      es: 'Separador autoestático con un marco metálico y dos (o tres) hojas laterales que se bloquean con una cremallera central.',
      en: 'Self-retaining retractor with a metal frame and two (or three) lateral blades locked in place by a central ratchet.',
    ),
    use: LocalizedText(
      ca: 'Exposició de la cavitat abdominal en laparotomies (histerectomia, cesària, cirurgia gàstrica i intestinal), sense necessitat d\'ajudant.',
      es: 'Exposición de la cavidad abdominal en laparotomías (histerectomía, cesárea, cirugía gástrica e intestinal), sin necesidad de ayudante.',
      en: 'Exposing the abdominal cavity in laparotomies (hysterectomy, cesarean section, gastric and bowel surgery), without needing an assistant to hold retraction.',
    ),
    tip: LocalizedText(
      ca: 'A diferència del separador de Bookwalter, no es fixa a la taula d\'operacions, cosa que el fa més ràpid de col·locar però amb menys exposició en pacients obesos.',
      es: 'A diferencia del separador de Bookwalter, no se fija a la mesa de operaciones, lo que lo hace más rápido de colocar pero con menos exposición en pacientes obesos.',
      en: 'Unlike the Bookwalter retractor, it does not attach to the operating table, making it quicker to set up but giving less exposure in obese patients.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/a/a9/Surgical_retractor.jpg',
      license: 'CC0 1.0',
      attribution: 'Saltanat ebli, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Surgical_retractor.jpg',
    ),
  ),
  Instrument(
    id: 'separador-deaver',
    isNew: true,
    name: LocalizedText(ca: 'Separador de Deaver', es: 'Separador de Deaver', en: 'Deaver retractor'),
    category: InstrumentCategory.separacion,
    aliases: ['Deaver retractor'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador manual amb una fulla llarga i corba, en forma d\'interrogant, de superfície llisa.',
      es: 'Separador manual con una hoja larga y curva, en forma de interrogante, de superficie lisa.',
      en: 'Handheld retractor with a long, smoothly curved, question-mark-shaped blade.',
    ),
    use: LocalizedText(
      ca: 'Retracció profunda de vísceres i paret abdominal (fetge, estómac, intestí) en cirurgia oberta abdominal i toràcica; per exemple en colecistectomia o colectomia obertes.',
      es: 'Retracción profunda de vísceras y pared abdominal (hígado, estómago, intestino) en cirugía abierta abdominal y torácica; por ejemplo en colecistectomía o colectomía abiertas.',
      en: 'Deep retraction of viscera and the abdominal wall (liver, stomach, bowel) in open abdominal and thoracic surgery; for example, in open cholecystectomy or colectomy.',
    ),
    tip: LocalizedText(
      ca: 'El mànec pla acaba en un ganxo on l\'ajudant pot recolzar un dit per reduir la fatiga durant estones llargues de retracció.',
      es: 'El mango plano termina en un gancho donde el ayudante puede apoyar un dedo para reducir la fatiga durante tramos largos de retracción.',
      en: 'The flat handle ends in a hook where the assistant can rest a finger to reduce fatigue during long periods of retraction.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/86/Deaver_retractor_01.JPG',
      license: 'CC0 1.0',
      attribution: 'Saltanat ebli, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Deaver_retractor_01.JPG',
    ),
  ),
  Instrument(
    id: 'separador-maleable',
    isNew: true,
    name: LocalizedText(ca: 'Separador maleable', es: 'Separador maleable', en: 'Malleable retractor'),
    category: InstrumentCategory.separacion,
    aliases: ['Ribbon retractor', 'Malleable ribbon retractor'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Fulla metàl·lica llarga, prima i plana, sense forma fixa: es doblega manualment a la forma que calgui durant la intervenció.',
      es: 'Hoja metálica larga, fina y plana, sin forma fija: se dobla manualmente según la forma que se necesite durante la intervención.',
      en: 'Long, thin, flat metal blade with no fixed shape: it is manually bent into whatever shape is needed during the operation.',
    ),
    use: LocalizedText(
      ca: 'Protecció i retracció suau d\'òrgans i intestí en cirurgia abdominal oberta, quan cap separador prefabricat s\'adapta a l\'angle necessari.',
      es: 'Protección y retracción suave de órganos e intestino en cirugía abdominal abierta, cuando ningún separador prefabricado se adapta al ángulo necesario.',
      en: 'Gentle protection and retraction of organs and bowel in open abdominal surgery, when no preformed retractor fits the angle needed.',
    ),
    tip: LocalizedText(
      ca: 'Com que és prim i flexible, cal un recompte acurat en tancar: la literatura ha descrit casos de separadors maleables oblidats a la cavitat abdominal.',
      es: 'Al ser fino y flexible, requiere un recuento cuidadoso al cerrar: la literatura ha descrito casos de separadores maleables olvidados en la cavidad abdominal.',
      en: 'Being thin and flexible, it requires a careful instrument count at closure: the literature has reported cases of malleable retractors left behind in the abdominal cavity.',
    ),
  ),
  Instrument(
    id: 'aguja-veress',
    isNew: true,
    name: LocalizedText(ca: 'Agulla de Veress', es: 'Aguja de Veress', en: 'Veress needle'),
    category: InstrumentCategory.especiales,
    aliases: ['Veress needle', 'Verres needle'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Agulla llarga amb una cànula externa de punta esbiaixada i un fiador intern retràctil, amb molla, que sobresurt en entrar en una cavitat sense resistència.',
      es: 'Aguja larga con una cánula externa de punta biselada y un fiador interno retráctil, con resorte, que sobresale al entrar en una cavidad sin resistencia.',
      en: 'Long needle with a beveled-tip outer cannula and a spring-loaded, retractable inner stylet that springs forward on entering a cavity with no resistance.',
    ),
    use: LocalizedText(
      ca: 'Creació del pneumoperitoneu insuflant CO2 a la cavitat abdominal abans de l\'entrada amb tròcar, en la tècnica laparoscòpica tancada.',
      es: 'Creación del neumoperitoneo insuflando CO2 en la cavidad abdominal antes de la entrada con trocar, en la técnica laparoscópica cerrada.',
      en: 'Creating the pneumoperitoneum by insufflating CO2 into the abdominal cavity before trocar entry, in the closed laparoscopic technique.',
    ),
    tip: LocalizedText(
      ca: 'El clic de la molla en travessar el peritoneu i una prova d\'aspiració negativa (test de la gota de sèrum) ajuden a confirmar la posició correcta abans d\'insuflar.',
      es: 'El clic del resorte al atravesar el peritoneo y una prueba de aspiración negativa (test de la gota de suero) ayudan a confirmar la posición correcta antes de insuflar.',
      en: 'The click of the spring as it crosses the peritoneum, together with a negative-aspiration check (the saline drop test), helps confirm correct placement before insufflating.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/5/55/Verres_Needle.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Lx zander, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Verres_Needle.jpg',
    ),
  ),
  Instrument(
    id: 'pinza-intestinal-doyen',
    isNew: true,
    name: LocalizedText(ca: 'Pinça intestinal de Doyen', es: 'Pinza intestinal de Doyen', en: 'Doyen intestinal forceps'),
    category: InstrumentCategory.diseccion,
    aliases: ['Doyen intestinal clamp', 'Doyen bowel clamp'],
    icon: 'pinch',
    description: LocalizedText(
      ca: 'Pinça llarga, recta o corba, de branques flexibles amb estries longitudinals i sense dents; instrument diferent de la valva de Doyen (que és un separador), tot i compartir el mateix epònim.',
      es: 'Pinza larga, recta o curva, de ramas flexibles con estrías longitudinales y sin dientes; instrumento distinto de la valva de Doyen (que es un separador), aunque comparta el mismo epónimo.',
      en: 'Long, straight or curved forceps with flexible, longitudinally serrated, toothless jaws; a different instrument from the Doyen retractor (valve), despite sharing the same eponym.',
    ),
    use: LocalizedText(
      ca: 'Oclusió atraumàtica i temporal de la llum intestinal per evitar vessament de contingut durant una resecció o anastomosi.',
      es: 'Oclusión atraumática y temporal de la luz intestinal para evitar el derrame de contenido durante una resección o anastomosis.',
      en: 'Atraumatic, temporary occlusion of the bowel lumen to prevent spillage of contents during resection or anastomosis.',
    ),
    tip: LocalizedText(
      ca: 'Les branques flexibles reparteixen la pressió de manera uniforme sobre la paret intestinal, evitant aixafar-la fins i tot en clampar amb fermesa.',
      es: 'Las ramas flexibles reparten la presión de forma uniforme sobre la pared intestinal, evitando aplastarla incluso al clampar con firmeza.',
      en: 'The flexible jaws distribute pressure evenly across the bowel wall, avoiding crushing it even when clamped firmly.',
    ),
  ),
  Instrument(
    id: 'grapadora-lineal-corte',
    isNew: true,
    name: LocalizedText(ca: 'Grapadora lineal de tall', es: 'Grapadora lineal de corte', en: 'Linear cutting stapler'),
    category: InstrumentCategory.sutura,
    aliases: ['GIA stapler', 'Linear cutter', 'Endo GIA (Medtronic)'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Dispositiu mecànic que aplica dues o més files paral·leles de grapes de titani o acer i talla el teixit entre elles en un sol tret; existeix en versió oberta i laparoscòpica, reutilitzable (amb càrregues) o d\'un sol ús.',
      es: 'Dispositivo mecánico que aplica dos o más filas paralelas de grapas de titanio o acero y corta el tejido entre ellas en un solo disparo; existe en versión abierta y laparoscópica, reutilizable (con cargas) o de un solo uso.',
      en: 'Mechanical device that fires two or more parallel rows of titanium or steel staples and cuts the tissue between them in a single stroke; available in open and laparoscopic versions, either reloadable or single-use.',
    ),
    use: LocalizedText(
      ca: 'Secció i tancament simultani d\'intestí, estómac o pulmó en reseccions (per exemple, gastrectomia en mànega, resecció intestinal, resecció pulmonar) i en la confecció d\'anastomosis latero-laterals.',
      es: 'Sección y cierre simultáneo de intestino, estómago o pulmón en resecciones (por ejemplo, gastrectomía en manga, resección intestinal, resección pulmonar) y en la confección de anastomosis latero-laterales.',
      en: 'Simultaneous transection and closure of bowel, stomach or lung during resections (for example, sleeve gastrectomy, bowel resection, lung resection) and when constructing side-to-side anastomoses.',
    ),
    tip: LocalizedText(
      ca: 'A diferència de plataformes motoritzades com la Signia, la majoria de grapadores lineals són d\'accionament manual i d\'un sol ús, i són les més habituals a la majoria de quiròfans.',
      es: 'A diferencia de plataformas motorizadas como la Signia, la mayoría de grapadoras lineales son de accionamiento manual y de un solo uso, y son las más habituales en la mayoría de quirófanos.',
      en: 'Unlike motorized platforms such as Signia, most linear staplers are manually fired and single-use, and are the type most commonly found in everyday operating rooms.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Surgical_stapler_%26_cutter_linear.JPG',
      license: 'CC BY-SA 3.0',
      attribution: 'Ignis, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Surgical_stapler_%26_cutter_linear.JPG',
    ),
  ),
  Instrument(
    id: 'drenaje-penrose',
    isNew: true,
    name: LocalizedText(ca: 'Dren de Penrose', es: 'Drenaje de Penrose', en: 'Penrose drain'),
    category: InstrumentCategory.especiales,
    aliases: ['Penrose drain'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tub de cautxú tou, pla i flexible, obert pels dos extrems, sense cap sistema de succió.',
      es: 'Tubo de caucho blando, plano y flexible, abierto por los dos extremos, sin ningún sistema de succión.',
      en: 'Soft, flat, flexible rubber tube, open at both ends, with no suction system.',
    ),
    use: LocalizedText(
      ca: 'Drenatge passiu per capil·laritat i gravetat de líquid o pus d\'una ferida o cavitat, evitant-ne l\'acumulació sota la pell.',
      es: 'Drenaje pasivo por capilaridad y gravedad de líquido o pus de una herida o cavidad, evitando su acumulación bajo la piel.',
      en: 'Passive drainage of fluid or pus from a wound or cavity by capillary action and gravity, preventing its build-up under the skin.',
    ),
    tip: LocalizedText(
      ca: 'Sovint es fixa amb un imperdible o un punt a la pell perquè no s\'introdueixi cap a l\'interior de la ferida.',
      es: 'A menudo se fija con un imperdible o un punto en la piel para que no se introduzca hacia el interior de la herida.',
      en: 'It is often secured with a safety pin or a skin stitch so it does not slip back inside the wound.',
    ),
  ),
  Instrument(
    id: 'drenaje-jackson-pratt',
    isNew: true,
    name: LocalizedText(ca: 'Dren de Jackson-Pratt (JP)', es: 'Drenaje de Jackson-Pratt (JP)', en: 'Jackson-Pratt drain (JP)'),
    category: InstrumentCategory.especiales,
    aliases: ['JP drain', 'Jackson-Pratt drain'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Sistema de drenatge tancat format per un tub intern multiperforat connectat, mitjançant un tub de plàstic, a una ampolla o bulb flexible en forma de granada.',
      es: 'Sistema de drenaje cerrado formado por un tubo interno multiperforado conectado, mediante un tubo de plástico, a una ampolla o bulbo flexible en forma de granada.',
      en: 'Closed-suction drainage system made of a perforated internal tube connected by plastic tubing to a flexible, grenade-shaped bulb.',
    ),
    use: LocalizedText(
      ca: 'Evacuació activa de líquid d\'un espai mort postquirúrgic (per exemple, després d\'una mastectomia, tiroïdectomia o cirurgia abdominal), evitant seromes o hematomes.',
      es: 'Evacuación activa de líquido de un espacio muerto postquirúrgico (por ejemplo, tras una mastectomía, tiroidectomía o cirugía abdominal), evitando seromas o hematomas.',
      en: 'Active evacuation of fluid from a postoperative dead space (for example, after mastectomy, thyroidectomy or abdominal surgery), preventing seromas or hematomas.',
    ),
    tip: LocalizedText(
      ca: 'El buit es crea comprimint el bulb abans de tancar el tap: convé buidar-lo abans que s\'ompli més de la meitat perquè mantingui una succió eficaç.',
      es: 'El vacío se crea comprimiendo el bulbo antes de cerrar el tapón: conviene vaciarlo antes de que se llene más de la mitad para que mantenga una succión eficaz.',
      en: 'The vacuum is created by compressing the bulb before closing its plug: it should be emptied before it is more than half full so it keeps suctioning effectively.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/e/e8/Jackson-Pratt_Drain.jpg',
      license: 'Dual-licensed: GNU Free Documentation License 1.2+ / CC BY-SA 3.0',
      attribution: 'Infiniti125, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Jackson-Pratt_Drain.jpg',
    ),
  ),
  Instrument(
    id: 'drenaje-kehr',
    isNew: true,
    name: LocalizedText(ca: 'Tub en T (de Kehr)', es: 'Tubo en T (de Kehr)', en: 'T-tube (Kehr tube)'),
    category: InstrumentCategory.especiales,
    aliases: ['Kehr T-tube', 'Biliary T-tube'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tub de goma o silicona amb forma de T: el braç curt transversal queda dins el conducte biliar i el braç llarg surt a través de la pell.',
      es: 'Tubo de goma o silicona con forma de T: el brazo corto transversal queda dentro del conducto biliar y el brazo largo sale a través de la piel.',
      en: 'Rubber or silicone tube shaped like the letter T: the short crossbar sits inside the bile duct while the long limb exits through the skin.',
    ),
    use: LocalizedText(
      ca: 'Drenatge temporal de la via biliar principal després d\'una coledocotomia (extracció de càlculs del colèdoc), deixant una via d\'accés per fer una colangiografia postoperatòria.',
      es: 'Drenaje temporal de la vía biliar principal tras una coledocotomía (extracción de cálculos del colédoco), dejando una vía de acceso para realizar una colangiografía postoperatoria.',
      en: 'Temporary drainage of the common bile duct after choledochotomy (removal of common bile duct stones), leaving an access route for postoperative cholangiography.',
    ),
    tip: LocalizedText(
      ca: 'Abans de retirar-lo es pot fer una colangiografia de control a través seu, injectant contrast per comprovar que la via biliar és permeable.',
      es: 'Antes de retirarlo se puede realizar una colangiografía de control a través de él, inyectando contraste para comprobar que la vía biliar es permeable.',
      en: 'Before removal, a check cholangiogram can be performed through it, injecting contrast to confirm the bile duct is patent.',
    ),
  ),
  Instrument(
    id: 'fijador-malla',
    isNew: true,
    name: LocalizedText(ca: 'Fixador de malla herniària (grapadora helicoidal)', es: 'Fijador de malla herniaria (grapadora helicoidal)', en: 'Hernia mesh fixation device (tacker)'),
    category: InstrumentCategory.especiales,
    aliases: ['Hernia tacker', 'ProTack (Medtronic)', 'AbsorbaTack (Medtronic)'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu llarg i tubular, d\'ús laparoscòpic o obert, que dispara grapes helicoïdals (de titani o reabsorbibles) des de la punta.',
      es: 'Dispositivo largo y tubular, de uso laparoscópico o abierto, que dispara grapas helicoidales (de titanio o reabsorbibles) desde la punta.',
      en: 'Long, tubular device, used laparoscopically or in open surgery, that fires helical tacks (titanium or absorbable) from its tip.',
    ),
    use: LocalizedText(
      ca: 'Fixació d\'una malla protèsica a la paret abdominal en la reparació d\'hèrnies (inguinal, ventral, incisional), evitant-ne el desplaçament.',
      es: 'Fijación de una malla protésica a la pared abdominal en la reparación de hernias (inguinal, ventral, incisional), evitando su desplazamiento.',
      en: 'Securing a prosthetic mesh to the abdominal wall during hernia repair (inguinal, ventral, incisional), preventing it from shifting.',
    ),
    tip: LocalizedText(
      ca: 'Les grapes es col·loquen a la perifèria de la malla, evitant zones properes a nervis o vasos per no causar dolor crònic.',
      es: 'Las grapas se colocan en la periferia de la malla, evitando zonas próximas a nervios o vasos para no causar dolor crónico.',
      en: 'Tacks are placed around the periphery of the mesh, avoiding areas near nerves or vessels to prevent chronic pain.',
    ),
  ),
  Instrument(
    id: 'gasa-quirurgica-radiopaca',
    name: LocalizedText(ca: 'Gasa quirúrgica radiopaca (compresa 4x4)', es: 'Gasa quirúrgica radiopaca (compresa 4x4)', en: 'Radiopaque surgical gauze swab (4x4 sponge)'),
    category: InstrumentCategory.especiales,
    aliases: ['compresa de gasa', 'gasa 4x4', 'esponja de gasa quirúrgica', 'X-ray detectable sponge'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Apòsit de gasa de cotó teixit, estèril i d\'un sol ús (es distingeix així de la gasa de cotó no estèril que s\'utilitza fora del camp quirúrgic, per a cures o neteja generals), plegat en múltiples capes (habitualment 4 o 8 capes, mida aproximada 10x10 cm o 4x4), amb un fil radiopac cosit a l\'interior perquè sigui detectable per raigs X.',
      es: 'Apósito de gasa de algodón tejido, estéril y de un solo uso (se distingue así de la gasa de algodón no estéril que se utiliza fuera del campo quirúrgico, para curas o limpieza generales), plegado en varias capas (habitualmente 4 u 8 capas, tamaño aproximado 10x10 cm o 4x4), con un hilo radiopaco cosido en su interior para que sea detectable mediante rayos X.',
      en: 'A sterile, single-use woven cotton gauze dressing (distinct from non-sterile cotton gauze used outside the surgical field for general wound care or cleaning), folded into multiple plies (typically 4- or 8-ply, roughly 10x10 cm / 4x4), with a radiopaque thread woven through it so it is detectable on X-ray.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per eixugar i absorbir sang o fluids del camp quirúrgic, per netejar o tamponar teixits i per a la preparació cutània, tant en cirurgia oberta com en petites intervencions.',
      es: 'Se utiliza para secar y absorber sangre o fluidos del campo quirúrgico, para limpiar o tamponar tejidos y para la preparación cutánea, tanto en cirugía abierta como en intervenciones menores.',
      en: 'Used to blot and absorb blood or fluid in the surgical field, to swab or dab tissue clean, and for skin preparation, in both open surgery and minor procedures.',
    ),
    tip: LocalizedText(
      ca: 'Ha de comptar-se abans i després de la intervenció segons el protocol de recompte de gases i instruments per prevenir cossos estranys retinguts; el fil radiopac permet detectar-la en una radiografia si el recompte no quadra.',
      es: 'Debe contarse antes y después de la intervención según el protocolo de recuento de gasas e instrumentos para prevenir cuerpos extraños retenidos; el hilo radiopaco permite detectarla en una radiografía si el recuento no cuadra.',
      en: 'Must be counted before and after the procedure as part of the sponge/instrument count protocol to prevent retained foreign bodies; the radiopaque thread allows it to be detected on X-ray if the count does not reconcile.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'compresa-laparotomia',
    name: LocalizedText(ca: 'Compresa de laparotomia (lap sponge)', es: 'Compresa de laparotomía (lap sponge)', en: 'Laparotomy pad (lap sponge)'),
    category: InstrumentCategory.especiales,
    aliases: ['lap pad', 'compresa abdominal', 'gasa de laparotomía'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Compresa gran de gasa de cotó, estèril i d\'un sol ús, de múltiples capes (desplegada, d\'uns 45x45 cm aproximadament), amb una cinta o llengüeta radiopaca cosida en una cantonada per facilitar-ne la localització i recuperació.',
      es: 'Compresa grande de gasa de algodón, estéril y de un solo uso, de varias capas (desplegada, de unos 45x45 cm aproximadamente), con una cinta o lengüeta radiopaca cosida en una esquina para facilitar su localización y recuperación.',
      en: 'A sterile, single-use, large multi-ply cotton gauze pad (roughly 45x45 cm when unfolded) with a radiopaque tape tag sewn into one corner to aid location and retrieval.',
    ),
    use: LocalizedText(
      ca: 'S\'empra per taponar i protegir vísceres, retreure òrgans i absorbir grans quantitats de sang o líquid durant la cirurgia oberta de l\'abdomen, la pelvis o altres grans cavitats.',
      es: 'Se emplea para taponar y proteger vísceras, retraer órganos y absorber grandes cantidades de sangre o líquido durante la cirugía abierta del abdomen, la pelvis u otras grandes cavidades.',
      en: 'Used to pack off and protect viscera, retract organs, and absorb large volumes of blood or fluid during open abdominal, pelvic, or other major cavity surgery.',
    ),
    tip: LocalizedText(
      ca: 'Manté sempre la llengüeta visible fora de la cavitat o fixada amb una pinça quan es tapona en profunditat; forma part obligatòria del recompte de gases, ja que és un dels objectes més freqüentment retinguts si no es controla.',
      es: 'Mantén siempre la lengüeta visible fuera de la cavidad o fijada con una pinza cuando se tapona en profundidad; forma parte obligatoria del recuento de gasas, ya que es uno de los objetos más frecuentemente retenidos si no se controla.',
      en: 'Always keep the tag visible outside the cavity or secured with a clamp when packing deep; it is a mandatory part of the sponge count, as it is one of the items most often left behind if not tracked.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'torunda-gasa',
    name: LocalizedText(ca: 'Torunda de gasa (pledget)', es: 'Torunda de gasa (pledget)', en: 'Gauze pledget (torunda ball)'),
    category: InstrumentCategory.especiales,
    aliases: ['bolita de gasa', 'pledget', 'gasa muntada en pinça'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Petita bola o tros plegat de gasa estèril, normalment muntat a les mordaces d\'una pinça (p. ex. una pinça portaesponges o un mosquito) en lloc de subjectar-se directament amb la mà.',
      es: 'Pequeña bola o trozo plegado de gasa estéril, normalmente montado en las mordazas de una pinza (p. ej. una pinza portaesponjas o un mosquito) en lugar de sujetarse directamente con la mano.',
      en: 'A small ball or folded wad of sterile gauze, typically mounted in the jaws of a clamp (such as a sponge-holding forceps or mosquito clamp) rather than held directly by hand.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per tamponar o netejar petites zones del camp quirúrgic, aplicar antisèptic dins d\'una cavitat o ferida, o absorbir petites quantitats de sang en espais reduïts on una gasa gran no és pràctica.',
      es: 'Se utiliza para tamponar o limpiar pequeñas zonas del campo quirúrgico, aplicar antiséptico dentro de una cavidad o herida, o absorber pequeñas cantidades de sangre en espacios reducidos donde una gasa grande no resulta práctica.',
      en: 'Used to dab or clean small areas of the surgical field, apply antiseptic inside a cavity or wound, or absorb small amounts of blood in confined spaces where a full-size sponge is impractical.',
    ),
    tip: LocalizedText(
      ca: 'No s\'ha de deixar mai solta dins d\'una ferida o cavitat sense estar muntada en una pinça; per la seva mida petita és un risc reconegut de cos estrany retingut, de manera que s\'inclou sempre en el recompte formal de gases.',
      es: 'No debe dejarse nunca suelta dentro de una herida o cavidad sin estar montada en una pinza; por su pequeño tamaño es un riesgo reconocido de cuerpo extraño retenido, por lo que se incluye siempre en el recuento formal de gasas.',
      en: 'Never leave it loose in a wound or cavity unmounted in a clamp; due to its small size it is a recognized retained-foreign-body risk and is therefore always included in the formal sponge count.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'gasa-celulosa-oxidada-regenerada',
    name: LocalizedText(ca: 'Gasa de cel·lulosa oxidada regenerada (Surgicel)', es: 'Gasa de celulosa oxidada regenerada (Surgicel)', en: 'Oxidized regenerated cellulose hemostatic gauze (Surgicel)'),
    category: InstrumentCategory.especiales,
    aliases: ['Surgicel', 'ORC', 'celulosa oxidada regenerada'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Teixit no tramat de cel·lulosa oxidada regenerada, de color groguenc o blanquinós, subministrat en fulls o tires estèrils que es poden retallar a mida; en contacte amb la sang es torna fosc, gairebé negre.',
      es: 'Tejido no tejido de celulosa oxidada regenerada, de color amarillento o blanquecino, suministrado en hojas o tiras estériles que pueden recortarse a medida; en contacto con la sangre se oscurece, tornándose casi negro.',
      en: 'A non-woven fabric of oxidized regenerated cellulose, pale yellow to off-white in color, supplied as sterile sheets or strips that can be trimmed to size; it darkens to almost black on contact with blood.',
    ),
    use: LocalizedText(
      ca: 'S\'aplica directament sobre una superfície sagnant (p. ex. parènquima hepàtic o esplènic, línia de sutura) com a agent hemostàtic tòpic absorbible que afavoreix la formació del coàgul.',
      es: 'Se aplica directamente sobre una superficie sangrante (p. ej. parénquima hepático o esplénico, línea de sutura) como agente hemostático tópico absorbible que favorece la formación del coágulo.',
      en: 'Applied directly onto a bleeding surface (e.g., hepatic or splenic parenchyma, a suture line) as a topical absorbable hemostatic agent that promotes clot formation.',
    ),
    tip: LocalizedText(
      ca: 'Fes servir només la quantitat mínima necessària i retira l\'excés un cop aconseguida l\'hemostàsia, ja que deixar-ne massa quantitat pot afavorir la formació de granulomes o actuar com a focus d\'infecció; evita embolicar-lo de manera constrictiva al voltant d\'una anastomosi vascular.',
      es: 'Utiliza solo la cantidad mínima necesaria y retira el exceso una vez conseguida la hemostasia, ya que dejar demasiada cantidad puede favorecer la formación de granulomas o actuar como foco de infección; evita envolverlo de forma constrictiva alrededor de una anastomosis vascular.',
      en: 'Use only the minimum amount needed and remove any excess once hemostasis is achieved, since leaving too much in place can promote granuloma formation or act as a nidus for infection; avoid wrapping it constrictively around a vascular anastomosis.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/d/d3/Oxidized_Regenerated_Cellulose_-_Gallbladder_(52027616615).jpg',
      license: 'CC BY-SA 2.0',
      attribution: 'Dr. Mark Ong, Atlas of Medical Foreign Bodies (Y Rosen, MD & P Meseguer, MD), Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Oxidized_Regenerated_Cellulose_-_Gallbladder_(52027616615).jpg',
    ),
  ),
  Instrument(
    id: 'cottonoid-neuroquirurgico',
    name: LocalizedText(ca: 'Cottonoid neuroquirúrgic (patty)', es: 'Cottonoid neuroquirúrgico (patty)', en: 'Neurosurgical cottonoid (patty)'),
    category: InstrumentCategory.especiales,
    aliases: ['patty', 'neuro-patty', 'tireta neuroquirúrgica'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Petit apòsit estèril, pla i prim, de feltre de ràion o cotó comprimit, de forma rectangular o en tira, amb un fil o banda radiopaca incorporada; es presenta en diverses mides graduades.',
      es: 'Pequeño apósito estéril, plano y fino, de fieltro de rayón o algodón comprimido, de forma rectangular o en tira, con un hilo o banda radiopaca incorporada; se presenta en varios tamaños graduados.',
      en: 'A small, sterile, thin, flat pad of compressed rayon or cotton felt, rectangular or strip-shaped, with an incorporated radiopaque thread or band; supplied in several graduated sizes.',
    ),
    use: LocalizedText(
      ca: 'Es col·loca sobre teixit cerebral, medul·lar o nerviós exposat en neurocirurgia i microcirurgia per protegir-lo i retreure\'l suaument, mantenir-lo humit i absorbir petites quantitats de sang o líquid d\'irrigació sense adherir-s\'hi.',
      es: 'Se coloca sobre tejido cerebral, medular o nervioso expuesto en neurocirugía y microcirugía para protegerlo y retraerlo suavemente, mantenerlo húmedo y absorber pequeñas cantidades de sangre o líquido de irrigación sin adherirse a él.',
      en: 'Placed over exposed brain, spinal cord, or nerve tissue in neurosurgery and microsurgery to protect and gently retract it, keep it moist, and absorb small amounts of blood or irrigation fluid without adhering to it.',
    ),
    tip: LocalizedText(
      ca: 'Humiteja\'l abans de col·locar-lo i mantén-ne sempre un control visual i de recompte estricte, ja que per la seva mida petita pot desplaçar-se en corredors quirúrgics profunds i estrets, i és un risc específicament reconegut de cos estrany retingut en neurocirurgia.',
      es: 'Humedécelo antes de colocarlo y mantén siempre un control visual y de recuento estricto, ya que por su pequeño tamaño puede desplazarse en corredores quirúrgicos profundos y estrechos, y es un riesgo específicamente reconocido de cuerpo extraño retenido en neurocirugía.',
      en: 'Moisten it before placement and keep strict visual tracking and counting at all times, since its small size allows it to migrate within deep, narrow surgical corridors, making it a specifically recognized retained-foreign-body risk in neurosurgery.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'gasa-yodoformada',
    name: LocalizedText(ca: 'Gasa iodofòrmica (gasa en cinta)', es: 'Gasa yodoformada (gasa en cinta)', en: 'Iodoform packing gauze (ribbon gauze)'),
    category: InstrumentCategory.especiales,
    aliases: ['ribbon gauze', 'mecha iodofòrmica', 'gasa de taponament'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tira llarga i estreta, en forma de cinta, de gasa de teixit pla impregnada amb iodoform (un compost antisèptic iodat), subministrada enrotllada en envasos estèrils de diferents amplades i longituds.',
      es: 'Tira larga y estrecha, en forma de cinta, de gasa de tejido plano impregnada con yodoformo (un compuesto antiséptico yodado), suministrada enrollada en envases estériles de diferentes anchuras y longitudes.',
      en: 'A long, narrow, ribbon-shaped strip of plain-weave gauze impregnated with iodoform (an iodine-containing antiseptic compound), supplied rolled in sterile packaging in various widths and lengths.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per taponar cavitats de ferides obertes o d\'abscessos drenats, o les fosses nasals (p. ex. després de cirurgia nasal o en episodis d\'epistaxi), per afavorir l\'hemostàsia, mantenir la cavitat permeable i aportar un lleuger efecte antisèptic mentre el teixit granula.',
      es: 'Se utiliza para taponar cavidades de heridas abiertas o de abscesos drenados, o las fosas nasales (p. ej. tras cirugía nasal o en episodios de epistaxis), para favorecer la hemostasia, mantener la cavidad permeable y aportar un leve efecto antiséptico mientras el tejido granula.',
      en: 'Used to pack open wound cavities or drained abscess cavities, or the nasal passages (e.g., after nasal surgery or for epistaxis), to promote hemostasis, keep the cavity patent, and provide a mild antiseptic effect while the tissue granulates.',
    ),
    tip: LocalizedText(
      ca: 'Registra sempre el nombre de peces o la longitud col·locada i planifica la pauta de retirada o recanvi, ja que un taponament oblidat és font d\'infecció; comprova prèviament que el pacient no tingui al·lèrgia al iode.',
      es: 'Registra siempre el número de piezas o la longitud colocada y planifica la pauta de retirada o recambio, ya que un taponamiento olvidado es fuente de infección; comprueba previamente que el paciente no tenga alergia al yodo.',
      en: 'Always document the number of pieces or length packed and plan a removal/repacking schedule, since forgotten packing is a source of infection; check beforehand that the patient has no iodine sensitivity.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'gasa-vaselinada',
    name: LocalizedText(ca: 'Gasa vaselinada (tul gras)', es: 'Gasa vaselinada (tul graso)', en: 'Paraffin (Vaseline) gauze dressing'),
    category: InstrumentCategory.especiales,
    aliases: ['tulle gras', 'Jelonet', 'gasa parafinada'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Gasa de cotó de teixit obert impregnada amb parafina tova (o una altra emulsió a base de vaselina), subministrada en fulls estèrils envasats individualment.',
      es: 'Gasa de algodón de tejido abierto impregnada con parafina blanda (u otra emulsión a base de vaselina), suministrada en hojas estériles envasadas individualmente.',
      en: 'An open-weave cotton gauze impregnated with soft paraffin (or another petrolatum-based emulsion), supplied as individually wrapped sterile sheets.',
    ),
    use: LocalizedText(
      ca: 'S\'aplica directament sobre una ferida oberta, una zona donant o receptora d\'empelt cutani, o una cremada, com a capa primària no adherent que permet el pas de l\'exsudat cap a l\'apòsit absorbent exterior sense enganxar-se ni lesionar el teixit en cicatrització en retirar-la.',
      es: 'Se aplica directamente sobre una herida abierta, una zona donante o receptora de injerto cutáneo, o una quemadura, como capa primaria no adherente que permite el paso del exudado hacia el apósito absorbente exterior sin pegarse ni lesionar el tejido en cicatrización al retirarla.',
      en: 'Applied directly over an open wound, skin-graft donor or recipient site, or a burn, as a non-adherent primary contact layer that lets exudate pass through to an outer absorbent dressing without sticking to or damaging the healing tissue on removal.',
    ),
    tip: LocalizedText(
      ca: 'Col·loca-la en una sola capa, sense amuntegar-la, perquè l\'exsudat pugui continuar drenant a través de la malla, i retira-la amb suavitat (humitejant-la prèviament si s\'ha enganxat) per no danyar l\'epiteli nou.',
      es: 'Colócala en una sola capa, sin amontonarla, para que el exudado pueda seguir drenando a través de la malla, y retírala con suavidad (humedeciéndola previamente si se ha pegado) para no dañar el epitelio nuevo.',
      en: 'Apply it in a single layer, not bunched up, so exudate can still drain through the mesh, and remove it gently (soaking first if it has stuck) to avoid damaging new epithelium.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Jelonet.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Whispyhistory',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Jelonet.jpg',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'paquete-mikulicz',
    name: LocalizedText(ca: 'Paquet de Mikulicz (drenatge de Mikulicz)', es: 'Paquete de Mikulicz (drenaje de Mikulicz)', en: 'Mikulicz pack (Mikulicz drain)'),
    category: InstrumentCategory.especiales,
    aliases: ['gasa de Mikulicz', 'Mikulicz\'s drain', 'taponament de Mikulicz'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Sac o bossa gran de gasa estèril (format clàssicament amb una peça única de gasa amb un cordó central) que es farceix amb rotllos o compreses de gasa estèril més petits, i que deixa una cinta o sutura de referència sortint de la ferida.',
      es: 'Saco o bolsa grande de gasa estéril (formado clásicamente con una pieza única de gasa con un cordón central) que se rellena con rollos o compresas de gasa estéril más pequeños, dejando una cinta o sutura de referencia que sale de la herida.',
      en: 'A large sterile gauze sac or bag (classically fashioned from a single piece of gauze with a central drawstring) packed with smaller sterile gauze rolls or sponges, left with a tape or suture tag exiting the wound.',
    ),
    use: LocalizedText(
      ca: 'Es col·loca fluixament dins d\'una cavitat gran, contaminada o infectada (p. ex. després del drenatge d\'un abscés o en situacions d\'abdomen obert) per afavorir l\'hemostàsia, absorbir l\'exsudat i mantenir la cavitat oberta; el farciment intern es va retirant per etapes en dies successius, i la bossa exterior es retira en últim lloc per minimitzar el traumatisme sobre el teixit de granulació.',
      es: 'Se coloca de forma laxa dentro de una cavidad grande, contaminada o infectada (p. ej. tras el drenaje de un absceso o en situaciones de abdomen abierto) para favorecer la hemostasia, absorber el exudado y mantener la cavidad abierta; el relleno interno se retira por etapas en días sucesivos, y la bolsa exterior se retira en último lugar para minimizar el traumatismo sobre el tejido de granulación.',
      en: 'Packed loosely into a large, contaminated, or infected cavity (e.g., after drainage of an abscess or in an open-abdomen situation) to promote hemostasis, absorb exudate, and keep the cavity open; the inner filling is removed in stages over subsequent days, with the outer bag withdrawn last to minimize trauma to granulating tissue.',
    ),
    tip: LocalizedText(
      ca: 'Documenta\'l com una unitat única amb una etiqueta externa ben visible i planifica una retirada esglaonada (habitualment a partir de les 48-72 hores), per evitar tant el col·lapse prematur de la cavitat com la retenció de gasa.',
      es: 'Documéntalo como una unidad única con una etiqueta externa bien visible y planifica una retirada escalonada (habitualmente a partir de las 48-72 horas), para evitar tanto el colapso prematuro de la cavidad como la retención de gasa.',
      en: 'Document it as a single counted unit with a clearly visible external tag, and plan a staged removal (typically starting at 48-72 hours) to avoid both premature cavity collapse and retained gauze.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'esponja-peanut-kittner',
    name: LocalizedText(ca: 'Esponja peanut (dissector de Kittner)', es: 'Esponja peanut (disector de Kittner)', en: 'Peanut sponge (Kittner dissector)'),
    category: InstrumentCategory.especiales,
    aliases: ['peanut', 'Kittner', 'dissector de gasa muntat'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Petit rotllo de gasa estèril ferm, de forma ovalada tipus cacauet, de vegades amb un nucli de cotó, muntat a la punta d\'una pinça (p. ex. una pinça portaesponges o una pinça d\'amígdales) en lloc de subjectar-se amb la mà.',
      es: 'Pequeño rollo de gasa estéril firme, de forma ovalada tipo cacahuete, a veces con un núcleo de algodón, montado en la punta de una pinza (p. ej. una pinza portaesponjas o una pinza de amígdalas) en lugar de sujetarse con la mano.',
      en: 'A small, firm, sterile, oval, peanut-shaped roll of gauze, sometimes with a cotton core, mounted in the tip of a clamp (such as a sponge-holding forceps or tonsil clamp) rather than held by hand.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per a la dissecció roma, per separar suaument plans de teixit, netejar restes de teixit connectiu laxa, o eixugar petites quantitats de sang en un camp quirúrgic reduït, aprofitant la seva forma ferma i arrodonida i el control que proporciona la pinça.',
      es: 'Se utiliza para la disección roma, para separar suavemente planos de tejido, limpiar restos de tejido conectivo laxo, o secar pequeñas cantidades de sangre en un campo quirúrgico reducido, aprovechando su forma firme y redondeada y el control que proporciona la pinza.',
      en: 'Used for blunt dissection, to gently separate tissue planes, clear away loose connective tissue, or blot small amounts of blood in a confined surgical field, taking advantage of its firm, rounded shape and the control afforded by the clamp.',
    ),
    tip: LocalizedText(
      ca: 'Manté-la sempre muntada a la pinça i no permetis mai que s\'utilitzi solta dins la ferida; com qualsevol altre element petit de gasa, s\'ha d\'incloure en el recompte formal per evitar que quedi retinguda inadvertidament.',
      es: 'Mantenla siempre montada en la pinza y no permitas nunca que se utilice suelta dentro de la herida; como cualquier otro elemento pequeño de gasa, debe incluirse en el recuento formal para evitar que quede retenida de forma inadvertida.',
      en: 'Always keep it mounted on the clamp and never allow it to be used loose in the wound; like any other small gauze item, it must be included in the formal count to prevent it from being inadvertently left behind.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'esponja-gelatina-hemostatica',
    name: LocalizedText(ca: 'Esponja de gelatina hemostàtica absorbible (Gelfoam)', es: 'Esponja de gelatina hemostática absorbible (Gelfoam)', en: 'Absorbable gelatin hemostatic sponge (Gelfoam)'),
    category: InstrumentCategory.especiales,
    aliases: ['Gelfoam', 'Spongostan', 'esponja de gelatina absorbible'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Esponja porosa i flexible, estèril, fabricada amb gelatina porcina purificada, de color blanquinós o crema, subministrada en sec en forma de fulls comprimits, blocs o pols que es poden retallar a mida.',
      es: 'Esponja porosa y flexible, estéril, fabricada con gelatina porcina purificada, de color blanquecino o crema, suministrada en seco en forma de hojas comprimidas, bloques o polvo que pueden recortarse a medida.',
      en: 'A porous, pliable, sterile sponge made of purified porcine gelatin, off-white or tan in color, supplied dry as compressed sheets, blocks, or a powder that can be cut or shaped to size.',
    ),
    use: LocalizedText(
      ca: 'Es col·loca o es compacta sobre una superfície sagnant (p. ex. os cruent, fetge o teixit tou) com a hemostàtic tòpic absorbible; en contacte amb la sang o el líquid s\'infla i forma una bastida mecànica que afavoreix la formació del coàgul, i acaba sent completament reabsorbida per l\'organisme en unes setmanes.',
      es: 'Se coloca o se compacta sobre una superficie sangrante (p. ej. hueso cruento, hígado o tejido blando) como hemostático tópico absorbible; en contacto con la sangre o el líquido se hincha y forma un andamiaje mecánico que favorece la formación del coágulo, y acaba siendo completamente reabsorbida por el organismo en unas semanas.',
      en: 'Placed or packed onto a bleeding surface (e.g., raw bone, liver, or soft tissue) as a topical absorbable hemostat; on contact with blood or fluid it swells and forms a mechanical scaffold that supports clot formation, and is fully resorbed by the body over several weeks.',
    ),
    tip: LocalizedText(
      ca: 'Humiteja-la prèviament amb sèrum fisiològic (en sec no s\'adapta bé i pot actuar de metxa), i evita sobrefarcir un espai tancat, ja que s\'expandeix considerablement en absorbir líquid i pot comprimir estructures properes (p. ex. un nervi o el canal medul·lar).',
      es: 'Humedécela previamente con suero fisiológico (en seco no se adapta bien y puede actuar de mecha), y evita rellenar en exceso un espacio cerrado, ya que se expande considerablemente al absorber líquido y puede comprimir estructuras cercanas (p. ej. un nervio o el canal medular).',
      en: 'Pre-moisten it with sterile saline (dry, it does not conform well and can act as a wick), and avoid over-packing a closed space, since it expands considerably once it absorbs fluid and can compress nearby structures (e.g., a nerve or the spinal canal).',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/3/3e/Absorbable_gelatin_sponge.png',
      license: 'CC BY-SA 4.0',
      attribution: 'Jaydeep Ratani',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Absorbable_gelatin_sponge.png',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'delantal-plomado',
    name: LocalizedText(ca: 'Davantal plomat', es: 'Delantal plomado', en: 'Lead apron'),
    category: InstrumentCategory.especiales,
    aliases: ['Delantal de protección radiológica', 'Radiation protection apron', 'Delantal equivalente a plomo'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Davantal flexible de protecció radiològica, fabricat amb làmines de plom o materials compostos equivalents al plom (compostos de bari, tungstè o bismut) encapsulats entre capes de vinil o teixit resistent, amb tancament al coll i a la cintura.',
      es: 'Delantal flexible de protección radiológica, fabricado con láminas de plomo o materiales compuestos equivalentes al plomo (compuestos de bario, tungsteno o bismuto) encapsulados entre capas de vinilo o tejido resistente, con cierre al cuello y a la cintura.',
      en: 'A flexible radiation-protection garment made of lead sheeting or lead-composite material (barium, tungsten, or bismuth compounds) encapsulated between layers of vinyl or durable fabric, closed at the neck and waist.',
    ),
    use: LocalizedText(
      ca: 'Es porta durant procediments guiats per fluoroscòpia o arc en C (cirurgia vascular, urològica, i traumatològica/ortopèdica amb imatge intraoperatòria) per atenuar la radiació de dispersió que arriba al tronc, les gònades i la medul·la òssia activa del personal que treballa a prop de la font de raigs X.',
      es: 'Se utiliza durante procedimientos guiados por fluoroscopia o arco en C (cirugía vascular, urológica y traumatológica/ortopédica con imagen intraoperatoria) para atenuar la radiación dispersa que alcanza el tronco, las gónadas y la médula ósea activa del personal que trabaja cerca de la fuente de rayos X.',
      en: 'Worn during fluoroscopy- or C-arm-guided procedures (vascular, urologic, and orthopedic/trauma surgery using intraoperative imaging) to attenuate scattered radiation reaching the torso, gonads, and active bone marrow of staff working near the X-ray source.',
    ),
    tip: LocalizedText(
      ca: 'El davantal només protegeix la superfície que cobreix i la seva eficàcia disminueix si es plega o es guarda incorrectament (penjar-lo sempre en un suport adequat); cal inspeccionar-lo periòdicament per detectar esquerdes al blindatge intern i combinar-lo amb un collar tiroïdal quan la zona del coll quedi exposada.',
      es: 'El delantal solo protege la superficie que cubre y su eficacia disminuye si se dobla o se guarda incorrectamente (colgarlo siempre en un soporte adecuado); debe inspeccionarse periódicamente para detectar grietas en el blindaje interno y combinarse con un collar tiroideo cuando la zona del cuello quede expuesta.',
      en: 'The apron only protects the surface it covers, and its attenuation degrades if folded or stored incorrectly (always hang it on a proper rack); it should be inspected periodically for cracks in the internal shielding and paired with a thyroid collar whenever the neck remains exposed.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/7/74/Radiation_protection_apron.jpg',
      license: 'CC BY 4.0',
      attribution: 'Wellcome Collection',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Radiation_protection_apron.jpg',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'collar-tiroideo-plomado',
    name: LocalizedText(ca: 'Collar tiroïdal plomat', es: 'Collar tiroideo plomado', en: 'Thyroid shield / thyroid collar'),
    category: InstrumentCategory.especiales,
    aliases: ['Protector tiroïdal', 'Thyroid guard', 'Collarín plomado'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Peça curta i flexible, fabricada amb el mateix tipus de material plomat o equivalent que el davantal radiològic, en forma de collar que envolta el coll i es tanca normalment amb velcro.',
      es: 'Pieza corta y flexible, fabricada con el mismo tipo de material plomado o equivalente que el delantal radiológico, en forma de collar que rodea el cuello y se cierra normalmente con velcro.',
      en: 'A short, flexible collar made of the same lead or lead-equivalent material as the radiation apron, wrapped around the neck and typically closed with a hook-and-loop fastener.',
    ),
    use: LocalizedText(
      ca: 'Es porta juntament amb el davantal plomat durant procediments amb fluoroscòpia o arc en C per blindar específicament la glàndula tiroide, un dels teixits més radiosensibles del cos, que queda fora de la cobertura habitual del davantal.',
      es: 'Se utiliza junto con el delantal plomado durante procedimientos con fluoroscopia o arco en C para blindar específicamente la glándula tiroides, uno de los tejidos más radiosensibles del cuerpo, que queda fuera de la cobertura habitual del delantal.',
      en: 'Worn together with the lead apron during fluoroscopy or C-arm procedures to specifically shield the thyroid gland, one of the body\'s more radiosensitive tissues, which lies above the apron\'s usual coverage.',
    ),
    tip: LocalizedText(
      ca: 'Com que el risc per exposició acumulada és especialment rellevant en personal que fa fluoroscòpia de manera repetida, l\'ús del collar tiroïdal no és opcional encara que el procediment sembli curt; cal col·locar-lo per sobre del davantal i comprovar que no quedi cap franja de coll descoberta.',
      es: 'Dado que el riesgo por exposición acumulada es especialmente relevante en el personal que realiza fluoroscopia de forma repetida, el uso del collar tiroideo no es opcional aunque el procedimiento parezca corto; debe colocarse por encima del delantal y comprobar que no quede ninguna franja de cuello descubierta.',
      en: 'Because cumulative-exposure risk is a recognized concern for staff who perform fluoroscopy repeatedly, wearing the thyroid collar is not optional even for a seemingly short case; it should sit above the apron with no gap of exposed neck.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'gafas-proteccion-laser',
    name: LocalizedText(ca: 'Ulleres de protecció làser', es: 'Gafas de protección láser', en: 'Laser safety goggles'),
    category: InstrumentCategory.especiales,
    aliases: ['Ulleres làser', 'Laser safety eyewear', 'Gafas antilaser'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Ulleres o visors amb lents de filtre òptic (vidre o policarbonat amb recobriments absorbents o reflectants) dissenyades per bloquejar o atenuar longituds d\'ona làser específiques, etiquetades amb la densitat òptica (OD) i el rang de longituds d\'ona per als quals ofereixen protecció.',
      es: 'Gafas o visores con lentes de filtro óptico (vidrio o policarbonato con recubrimientos absorbentes o reflectantes) diseñadas para bloquear o atenuar longitudes de onda láser específicas, etiquetadas con la densidad óptica (OD) y el rango de longitudes de onda para los que ofrecen protección.',
      en: 'Eyewear with optical filter lenses (glass or polycarbonate with absorptive or reflective coatings) designed to block or attenuate specific laser wavelengths, labeled with the optical density (OD) and wavelength range for which they provide protection.',
    ),
    use: LocalizedText(
      ca: 'És d\'ús obligatori per a tot el personal present a quiròfan sempre que hi hagi un làser quirúrgic en funcionament (p. ex. làser d\'holmi, tuli, CO2 laringi, dermatològic, YAG oftàlmic o argó de retina), ja que protegeixen la retina i la còrnia d\'un feix làser reflectit o directe que podria causar lesió ocular irreversible.',
      es: 'Es de uso obligatorio para todo el personal presente en el quirófano siempre que haya un láser quirúrgico en funcionamiento (p. ej. láser de holmio, tulio, CO2 laríngeo, dermatológico, YAG oftálmico o argón de retina), ya que protegen la retina y la córnea de un haz láser reflejado o directo que podría causar una lesión ocular irreversible.',
      en: 'Mandatory for all operating-room personnel whenever a surgical laser is active (e.g., holmium, thulium, CO2 laryngeal, dermatologic, ophthalmic YAG, or retinal argon lasers), as it protects the retina and cornea from a reflected or direct laser beam that could cause irreversible eye injury.',
    ),
    tip: LocalizedText(
      ca: 'Les ulleres de protecció làser NO són universals: cada parella està calibrada per a un rang concret de longituds d\'ona i densitat òptica (estàndard EN 207 a Europa, ANSI Z136.1 als EUA), de manera que cal verificar sempre que corresponen exactament al làser que s\'utilitzarà abans d\'encendre\'l; unes ulleres equivocades poden semblar protectores sense oferir cap protecció real.',
      es: 'Las gafas de protección láser NO son universales: cada par está calibrado para un rango concreto de longitudes de onda y densidad óptica (estándar EN 207 en Europa, ANSI Z136.1 en EE. UU.), por lo que siempre debe verificarse que corresponden exactamente al láser que se va a utilizar antes de encenderlo; unas gafas equivocadas pueden parecer protectoras sin ofrecer protección real.',
      en: 'Laser safety goggles are NOT universal: each pair is rated for a specific wavelength range and optical density (EN 207 standard in Europe, ANSI Z136.1 in the US), so staff must always confirm the goggles match the exact laser in use before activation; the wrong goggles can look protective while offering none.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Laser_goggles_en207.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Hankwang (Wikipedia/Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Laser_goggles_en207.jpg',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'respirador-ffp2-ffp3',
    name: LocalizedText(ca: 'Respirador FFP2/FFP3 per a procediments generadors d\'aerosols', es: 'Respirador FFP2/FFP3 para procedimientos generadores de aerosoles', en: 'FFP2/FFP3 (N95-equivalent) respirator for aerosol-generating procedures'),
    category: InstrumentCategory.especiales,
    aliases: ['Mascareta FFP3', 'Mascarilla FFP2/FFP3', 'N95 respirator', 'Filtering facepiece respirator'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Mascareta facial autofiltrant feta de capes de teixit no teixit (sovint polipropilè fos-bufat), ajustada hermèticament al rostre amb una peça nasal moldejable i cintes elàstiques, classificada segons la norma europea EN 149 (FFP2/FFP3) o l\'equivalent nord-americà N95/N99.',
      es: 'Mascarilla facial autofiltrante hecha de capas de tejido no tejido (a menudo polipropileno fundido-soplado), ajustada herméticamente al rostro mediante una pieza nasal moldeable y cintas elásticas, clasificada según la norma europea EN 149 (FFP2/FFP3) o el equivalente norteamericano N95/N99.',
      en: 'A self-filtering facepiece made of layered nonwoven fabric (often melt-blown polypropylene), sealed tightly to the face with a moldable nose clip and elastic straps, classified under the European EN 149 standard (FFP2/FFP3) or the equivalent North American N95/N99 rating.',
    ),
    use: LocalizedText(
      ca: 'Es porta durant procediments quirúrgics que generen aerosols o partícules fines en suspensió (serrat o perforació d\'os, electrocirurgia amb producció de fum, i certs procediments d\'otorinolaringologia o de via respiratòria d\'alt risc) per filtrar partícules petites que una mascareta quirúrgica estàndard no reté eficaçment.',
      es: 'Se utiliza durante procedimientos quirúrgicos que generan aerosoles o partículas finas en suspensión (serrado o perforación de hueso, electrocirugía con producción de humo, y ciertos procedimientos de otorrinolaringología o de vía respiratoria de alto riesgo) para filtrar partículas pequeñas que una mascarilla quirúrgica estándar no retiene eficazmente.',
      en: 'Worn during surgical procedures that generate aerosols or fine airborne particles (bone sawing or drilling, smoke-generating electrocautery, and certain high-risk ENT or airway procedures) to filter small particles that a standard surgical mask does not effectively capture.',
    ),
    tip: LocalizedText(
      ca: 'La protecció depèn tant del nivell de filtració (FFP2 filtra un percentatge de partícules més baix que FFP3; l\'equivalent N95 es defineix de manera similar) com d\'un ajustament facial correcte: cal fer sempre una prova d\'estanquitat en col·locar-se\'l, ja que una barba o un ajust incorrecte de la peça nasal anul·len gran part de la seva eficàcia encara que el filtre sigui adequat.',
      es: 'La protección depende tanto del nivel de filtración (FFP2 filtra un porcentaje de partículas menor que FFP3; el equivalente N95 se define de forma similar) como de un ajuste facial correcto: debe realizarse siempre una prueba de estanqueidad al colocarlo, ya que la barba o un ajuste incorrecto de la pieza nasal anulan gran parte de su eficacia aunque el filtro sea adecuado.',
      en: 'Protection depends both on the filtration class (FFP2 filters a lower percentage of particles than FFP3; N95 is defined similarly) and on a correct facial seal: a seal check should always be performed on donning, since facial hair or a poorly fitted nose clip can defeat most of the protection even with an adequate filter.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/4/48/Atemluftfilter_Einwegmaske.jpg',
      license: 'Public domain',
      attribution: 'Rudolf Goldhammer (Ru-go)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Atemluftfilter_Einwegmaske.jpg',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'guante-indicador-perforacion-doble',
    name: LocalizedText(ca: 'Sistema de doble guant amb indicador de perforació', es: 'Sistema de doble guante con indicador de perforación', en: 'Double-glove perforation indicator system'),
    category: InstrumentCategory.especiales,
    aliases: ['Guant indicador de perforació', 'Indicator underglove', 'Puncture indication system', 'Biogel Indicator (nom comercial de referència)'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Parell de guants quirúrgics estèrils d\'un color intens i contrastat (sovint verd o blau) pensats per portar-se com a sotaguant, just sota un guant exterior quirúrgic de color clar habitual, formant un sistema de "doble guant" de dues capes de colors diferenciats.',
      es: 'Par de guantes quirúrgicos estériles de un color intenso y contrastado (a menudo verde o azul) pensados para llevarse como guante interior, justo debajo de un guante exterior quirúrgico de color claro habitual, formando un sistema de "doble guante" de dos capas de colores diferenciados.',
      en: 'A pair of sterile surgical gloves in a strongly contrasting color (often dark green or blue) designed to be worn as an underglove, directly beneath a standard lighter-colored outer surgical glove, forming a two-layer, color-contrasted "double glove" system.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en cirurgia d\'alt risc de perforació del guant (traumatologia i cirurgia ortopèdica, entre d\'altres) perquè, si el guant exterior es perfora, el líquid que s\'infiltra entre les dues capes fa visible el color intens del sotaguant exactament al punt de la punxada, alertant l\'equip quirúrgic que cal canviar el guant de seguida.',
      es: 'Se utiliza en cirugía con alto riesgo de perforación del guante (traumatología y cirugía ortopédica, entre otras) porque, si el guante exterior se perfora, el líquido que se infiltra entre las dos capas hace visible el color intenso del guante interior exactamente en el punto del pinchazo, alertando al equipo quirúrgico de que debe cambiarse el guante de inmediato.',
      en: 'Used in surgery with elevated glove-perforation risk (orthopedic/trauma surgery, among others) because, if the outer glove is breached, fluid wicking between the two layers makes the underglove\'s strong color visible right at the puncture site, alerting the surgical team that the glove needs to be changed immediately.',
    ),
    tip: LocalizedText(
      ca: 'Aquest sistema amb indicador de color NO és la pràctica més habitual: en molts hospitals es fa un doble guantatge "pla", amb dos guants del mateix color, que dona la mateixa redundància de barrera però sense l\'avís visual — els estudis mostren que, sense indicador, només es detecta a ull nu entre un 21% i un 34% de les perforacions, davant d\'un 77-83% quan hi ha contrast de color. Una complicació pràctica a banda és la fricció entre les dues capes de làtex/nitril en posar-se-les; per això alguns equips es col·loquen el guant intern sense pols de talc (per minimitzar-ne l\'entrada a la ferida si es perfora) i reserven la pols, quan s\'usa, per al guant extern.',
      es: 'Este sistema con indicador de color NO es la práctica más habitual: en muchos hospitales se hace un doble enguantado "plano", con dos guantes del mismo color, que ofrece la misma redundancia de barrera pero sin el aviso visual — los estudios muestran que, sin indicador, solo se detecta a simple vista entre un 21% y un 34% de las perforaciones, frente a un 77-83% cuando hay contraste de color. Una complicación práctica aparte es la fricción entre las dos capas de látex/nitrilo al colocarlas; por eso algunos equipos se colocan el guante interno sin polvo de talco (para minimizar su entrada en la herida si se perfora) y reservan el polvo, cuando se usa, para el guante externo.',
      en: 'This color-indicator system is NOT the most common practice: many hospitals do "plain" double-gloving with two same-colored gloves, which gives the same barrier redundancy but without the visual cue — studies show that without an indicator, only 21-34% of perforations are detected by the naked eye, versus 77-83% with color contrast. A separate practical issue is friction between the two latex/nitrile layers during donning; some teams therefore don the inner glove powder-free (to minimize powder entering the wound if it is breached) and reserve any powder, where used, for the outer glove.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-poliglactina-910',
    name: LocalizedText(ca: 'Sutura de poliglactina 910 (Vicryl)', es: 'Sutura de poliglactina 910 (Vicryl)', en: 'Polyglactin 910 suture (Vicryl)'),
    category: InstrumentCategory.sutura,
    aliases: ['Vicryl', 'Vicryl Rapide', 'Vicryl Plus'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura sintètica absorbible trenada (multifilament), composta per un copolímer de glicòlid i làctid (poliglactina 910), habitualment recoberta per facilitar-ne el lliscament pels teixits.',
      es: 'Sutura sintética absorbible trenzada (multifilamento), compuesta por un copolímero de glicólido y láctido (poliglactina 910), habitualmente recubierta para facilitar su deslizamiento por los tejidos.',
      en: 'Synthetic absorbable braided (multifilament) suture made of a copolymer of glycolide and lactide (polyglactin 910), usually coated to improve tissue passage.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per a l\'aproximació general de teixits tous, lligadures vasculars i sutures subcutànies on no cal suport perllongat, gràcies al seu bon maneig i seguretat del nus.',
      es: 'Se utiliza para la aproximación general de tejidos blandos, ligaduras vasculares y suturas subcutáneas donde no se necesita soporte prolongado, gracias a su buen manejo y seguridad del nudo.',
      en: 'Used for general soft-tissue approximation, vascular ligatures, and subcutaneous closures where prolonged support is not required, owing to its good handling and knot security.',
    ),
    tip: LocalizedText(
      ca: 'En perdre resistència de forma relativament ràpida (la major part en unes poques setmanes) i absorbir-se completament en aproximadament dos mesos, no és adequada per a teixits que necessitin suport perllongat com la fàscia; la seva estructura trenada pot afavorir la colonització bacteriana si s\'usa en camps contaminats.',
      es: 'Al perder resistencia de forma relativamente rápida (la mayor parte en pocas semanas) y absorberse por completo en aproximadamente dos meses, no es adecuada para tejidos que requieran soporte prolongado como la fascia; su estructura trenzada puede favorecer la colonización bacteriana si se usa en campos contaminados.',
      en: 'Because it loses most of its tensile strength within a few weeks and is fully absorbed in about two months, it is not suited for tissues needing prolonged support such as fascia; its braided structure can harbor bacteria if used in contaminated fields.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/2/2a/Vicryl_surgical_suture.JPG',
      license: 'CC0 1.0 Universal (Public Domain Dedication)',
      attribution: 'Saltanat ebli',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Vicryl_surgical_suture.JPG',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-poliglecaprona-25',
    name: LocalizedText(ca: 'Sutura de poliglecaprona 25 (Monocryl)', es: 'Sutura de poliglecaprona 25 (Monocryl)', en: 'Poliglecaprone 25 suture (Monocryl)'),
    category: InstrumentCategory.sutura,
    aliases: ['Monocryl', 'Monocryl Plus'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura sintètica absorbible monofilament, composta per un copolímer de glicòlid i èpsilon-caprolactona (poliglecaprona 25), amb un tacte molt flexible per ser un monofilament.',
      es: 'Sutura sintética absorbible monofilamento, compuesta por un copolímero de glicólido y épsilon-caprolactona (poliglecaprona 25), con un tacto muy flexible para ser un monofilamento.',
      en: 'Synthetic absorbable monofilament suture made of a copolymer of glycolide and epsilon-caprolactone (poliglecaprone 25), notably pliable for a monofilament material.',
    ),
    use: LocalizedText(
      ca: 'Molt emprada en el tancament subcuticular de pell i l\'aproximació de teixits tous superficials, on es busca un bon resultat estètic i una absorció relativament ràpida.',
      es: 'Muy utilizada en el cierre subcuticular de piel y la aproximación de tejidos blandos superficiales, donde se busca un buen resultado estético y una absorción relativamente rápida.',
      en: 'Widely used for subcuticular skin closure and approximation of superficial soft tissue, where a good cosmetic result and relatively fast absorption are desired.',
    ),
    tip: LocalizedText(
      ca: 'Perd la major part de la seva resistència en poques setmanes i s\'absorbeix completament en uns tres o quatre mesos; com a monofilament llis, necessita nusos amb més llançades per garantir-ne la seguretat.',
      es: 'Pierde la mayor parte de su resistencia en pocas semanas y se absorbe por completo en unos tres o cuatro meses; al ser un monofilamento liso, necesita nudos con más lanzadas para garantizar su seguridad.',
      en: 'It loses most of its tensile strength within a few weeks and is fully absorbed within about three to four months; being a smooth monofilament, it requires extra throws to secure a knot reliably.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-polidioxanona',
    name: LocalizedText(ca: 'Sutura de polidioxanona (PDS)', es: 'Sutura de polidioxanona (PDS)', en: 'Polydioxanone suture (PDS)'),
    category: InstrumentCategory.sutura,
    aliases: ['PDS', 'PDS II', 'PDS Plus'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura sintètica absorbible monofilament, feta d\'un polímer de poli(p-dioxanona), dissenyada per mantenir la resistència tènsil durant més temps que altres sutures absorbibles sintètiques.',
      es: 'Sutura sintética absorbible monofilamento, hecha de un polímero de poli(p-dioxanona), diseñada para mantener la resistencia tensil durante más tiempo que otras suturas absorbibles sintéticas.',
      en: 'Synthetic absorbable monofilament suture made from a poly(p-dioxanone) polymer, designed to retain tensile strength longer than other synthetic absorbable sutures.',
    ),
    use: LocalizedText(
      ca: 'Indicada per al tancament de fàscia, paret abdominal i altres teixits que requereixen suport perllongat durant la cicatrització, així com en cirurgia cardíaca pediàtrica.',
      es: 'Indicada para el cierre de fascia, pared abdominal y otros tejidos que requieren soporte prolongado durante la cicatrización, así como en cirugía cardíaca pediátrica.',
      en: 'Indicated for fascial and abdominal wall closure and other tissues requiring prolonged support during healing, as well as in pediatric cardiac surgery.',
    ),
    tip: LocalizedText(
      ca: 'Manté una resistència útil durant diverses setmanes i no s\'absorbeix del tot fins passats uns sis mesos, molt més que el Vicryl o el Monocryl; com a monofilament rígid amb memòria, cal fer més llançades per assegurar el nus.',
      es: 'Mantiene una resistencia útil durante varias semanas y no se absorbe del todo hasta pasados unos seis meses, mucho más que el Vicryl o el Monocryl; al ser un monofilamento rígido con memoria, hay que dar más lanzadas para asegurar el nudo.',
      en: 'It retains useful strength for several weeks and is not fully absorbed until around six months, much longer than Vicryl or Monocryl; being a stiffer monofilament with memory, it needs extra knot throws for security.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-seda-trenzada',
    name: LocalizedText(ca: 'Sutura de seda trenada', es: 'Sutura de seda trenzada', en: 'Braided silk suture'),
    category: InstrumentCategory.sutura,
    aliases: ['Silk', 'Sofsilk'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura natural no absorbible trenada (multifilament), elaborada a partir de fibres de seda crua processades i sovint recobertes de cera o silicona per millorar-ne el lliscament.',
      es: 'Sutura natural no absorbible trenzada (multifilamento), elaborada a partir de fibras de seda cruda procesadas y a menudo recubiertas de cera o silicona para mejorar su deslizamiento.',
      en: 'Natural non-absorbable braided (multifilament) suture made from processed raw silk fibers, often coated with wax or silicone to improve glide.',
    ),
    use: LocalizedText(
      ca: 'S\'ha utilitzat tradicionalment per a lligadures vasculars, fixació de drenatges i tubs, i aproximació de teixits tous on es valora especialment la facilitat de maneig i la seguretat del nus.',
      es: 'Se ha utilizado tradicionalmente para ligaduras vasculares, fijación de drenajes y tubos, y aproximación de tejidos blandos donde se valora especialmente la facilidad de manejo y la seguridad del nudo.',
      en: 'Traditionally used for vascular ligatures, fixation of drains and tubes, and soft-tissue approximation where ease of handling and knot security are particularly valued.',
    ),
    tip: LocalizedText(
      ca: 'Encara que es classifica com a no absorbible, perd resistència de forma gradual al llarg de mesos o anys per degradació proteolítica; té el millor maneig i seguretat del nus de totes les sutures habituals, però també la reactivitat tissular més alta i un efecte metxa (capil·laritat) que en desaconsella l\'ús en camps contaminats o al voltant d\'implants.',
      es: 'Aunque se clasifica como no absorbible, pierde resistencia de forma gradual a lo largo de meses o años por degradación proteolítica; tiene el mejor manejo y seguridad del nudo de todas las suturas habituales, pero también la reactividad tisular más alta y un efecto mecha (capilaridad) que desaconseja su uso en campos contaminados o alrededor de implantes.',
      en: 'Although classified as non-absorbable, it gradually loses strength over months to years through proteolytic degradation; it offers the best handling and knot security of common sutures, but also the highest tissue reactivity and a wicking (capillary) effect that makes it unsuitable for contaminated fields or around implants.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-polipropileno',
    name: LocalizedText(ca: 'Sutura de polipropilè (Prolene)', es: 'Sutura de polipropileno (Prolene)', en: 'Polypropylene suture (Prolene)'),
    category: InstrumentCategory.sutura,
    aliases: ['Prolene', 'Surgipro'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura sintètica no absorbible monofilament, feta de polipropilè, un material inert amb molt poca reactivitat tissular; sovint tenyida de blau per facilitar-ne la visualització.',
      es: 'Sutura sintética no absorbible monofilamento, hecha de polipropileno, un material inerte con muy poca reactividad tisular; a menudo teñida de azul para facilitar su visualización.',
      en: 'Synthetic non-absorbable monofilament suture made of polypropylene, an inert material with very low tissue reactivity; often dyed blue to aid visibility.',
    ),
    use: LocalizedText(
      ca: 'És la sutura de referència per a anastomosis vasculars i cardíaques, gràcies al seu lliscament suau pels teixits i a la mínima resposta inflamatòria que genera.',
      es: 'Es la sutura de referencia para anastomosis vasculares y cardíacas, gracias a su deslizamiento suave por los tejidos y a la mínima respuesta inflamatoria que genera.',
      en: 'It is the reference suture for vascular and cardiac anastomoses, owing to its smooth glide through tissue and minimal inflammatory response.',
    ),
    tip: LocalizedText(
      ca: 'Manté la resistència tènsil pràcticament indefinidament, sense degradar-se de forma significativa in vivo; com a monofilament amb memòria, necessita més llançades de nus que les trenades i pot tallar el teixit si es tensa en excés.',
      es: 'Mantiene la resistencia tensil prácticamente indefinidamente, sin degradarse de forma significativa in vivo; al ser un monofilamento con memoria, necesita más lanzadas de nudo que las trenzadas y puede cortar el tejido si se tensa en exceso.',
      en: 'It retains tensile strength essentially indefinitely, without significant in vivo degradation; being a monofilament with memory, it requires more knot throws than braided sutures and can cut through tissue if over-tightened.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-nailon',
    name: LocalizedText(ca: 'Sutura de niló (Ethilon)', es: 'Sutura de nailon (Ethilon)', en: 'Nylon suture (Ethilon)'),
    category: InstrumentCategory.sutura,
    aliases: ['Ethilon', 'Nurolon', 'Dermalon'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura sintètica no absorbible, feta de poliamida (niló), disponible sobretot en forma monofilament (Ethilon), tot i que també existeix una versió trenada (Nurolon).',
      es: 'Sutura sintética no absorbible, hecha de poliamida (nailon), disponible sobre todo en forma monofilamento (Ethilon), aunque también existe una versión trenzada (Nurolon).',
      en: 'Synthetic non-absorbable suture made of polyamide (nylon), most commonly available as a monofilament (Ethilon), though a braided version (Nurolon) also exists.',
    ),
    use: LocalizedText(
      ca: 'Molt utilitzada per al tancament cutani i sutures de retenció, també en oftalmologia i microcirurgia, pel seu baix cost i bon resultat estètic.',
      es: 'Muy utilizada para el cierre cutáneo y suturas de retención, también en oftalmología y microcirugía, por su bajo coste y buen resultado estético.',
      en: 'Widely used for skin closure and retention sutures, as well as in ophthalmology and microsurgery, due to its low cost and good cosmetic result.',
    ),
    tip: LocalizedText(
      ca: 'Es degrada molt lentament (perd part de la seva resistència any rere any) però es considera no absorbible a efectes pràctics; té molta memòria i tendeix a cargolar-se, per la qual cosa necessita nusos amb llançades addicionals i sol retirar-se de la pell en lloc de deixar-la absorbir.',
      es: 'Se degrada muy lentamente (pierde parte de su resistencia año tras año) pero se considera no absorbible a efectos prácticos; tiene mucha memoria y tiende a enrollarse, por lo que necesita nudos con lanzadas adicionales y suele retirarse de la piel en lugar de dejarla absorber.',
      en: 'It degrades very slowly (losing some strength year over year) but is considered non-absorbable for practical purposes; it has strong memory and tends to curl back, so it needs extra knot throws and is usually removed from skin rather than left to be absorbed.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-catgut-cromico',
    name: LocalizedText(ca: 'Catgut cròmic', es: 'Catgut crómico', en: 'Chromic catgut'),
    category: InstrumentCategory.sutura,
    aliases: ['Chromic gut', 'Catgut crómico'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura natural absorbible obtinguda de col·lagen purificat (habitualment de serosa intestinal bovina o submucosa intestinal ovina), tractada amb sals de crom per alentir-ne l\'absorció i reduir la reacció tissular respecte al catgut simple.',
      es: 'Sutura natural absorbible obtenida de colágeno purificado (habitualmente de serosa intestinal bovina o submucosa intestinal ovina), tratada con sales de cromo para retrasar su absorción y reducir la reacción tisular respecto al catgut simple.',
      en: 'Natural absorbable suture derived from purified collagen (typically bovine intestinal serosa or ovine intestinal submucosa), treated with chromium salts to delay absorption and reduce tissue reaction compared with plain catgut.',
    ),
    use: LocalizedText(
      ca: 'Sutura tradicional, encara emprada en alguns contextos obstètrics i ginecològics (per exemple, reparació de l\'episiotomia o de la mucosa vaginal), tot i que en molts entorns ha estat majoritàriament substituïda per sutures sintètiques absorbibles.',
      es: 'Sutura tradicional, todavía empleada en algunos contextos obstétricos y ginecológicos (por ejemplo, reparación de la episiotomía o de la mucosa vaginal), aunque en muchos entornos ha sido mayoritariamente sustituida por suturas sintéticas absorbibles.',
      en: 'A traditional suture still used in some obstetric and gynecologic contexts (for example, episiotomy or vaginal mucosa repair), though in many settings it has largely been replaced by synthetic absorbable sutures.',
    ),
    tip: LocalizedText(
      ca: 'S\'absorbeix per digestió enzimàtica (proteòlisi) en lloc d\'hidròlisi, cosa que fa que el seu perfil d\'absorció sigui més variable i imprevisible que el de les sutures sintètiques, amb més reacció inflamatòria tissular; a més, el fil s\'estova i es torna més difícil de manejar quan s\'humiteja.',
      es: 'Se absorbe por digestión enzimática (proteólisis) en lugar de hidrólisis, lo que hace que su perfil de absorción sea más variable e impredecible que el de las suturas sintéticas, con mayor reacción inflamatoria tisular; además, el hilo se reblandece y es más difícil de manejar al humedecerse.',
      en: 'It is absorbed by enzymatic digestion (proteolysis) rather than hydrolysis, making its absorption profile more variable and less predictable than synthetic sutures, with greater tissue inflammatory reaction; the strand also softens and becomes harder to handle once wet.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/7/76/CHROMIC_suture_01.JPG',
      license: 'CC0 1.0 Universal (Public Domain Dedication)',
      attribution: 'Saltanat ebli',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:CHROMIC_suture_01.JPG',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-alambre-acero',
    name: LocalizedText(ca: 'Sutura de filferro d\'acer inoxidable', es: 'Sutura de alambre de acero inoxidable', en: 'Stainless steel wire suture'),
    category: InstrumentCategory.sutura,
    aliases: ['Steel suture', 'Alambre de acero inoxidable 316L'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura metàl·lica no absorbible, feta de filferro d\'acer inoxidable (habitualment aliatge 316L), disponible en forma de monofilament o com a feix de filaments fins trenats.',
      es: 'Sutura metálica no absorbible, hecha de alambre de acero inoxidable (habitualmente aleación 316L), disponible en forma de monofilamento o como haz de filamentos finos trenzados.',
      en: 'Non-absorbable metallic suture made of stainless steel wire (typically a 316L alloy), available as a monofilament strand or as a bundle of fine twisted filaments.',
    ),
    use: LocalizedText(
      ca: 'El seu ús principal és el tancament de l\'estern després d\'una esternotomia mitjana (vegeu l\'entrada de tancament esternal d\'aquest catàleg), on s\'aplica habitualment en forma de punts en vuit o circumferencials; també s\'utilitza en algunes reparacions tendinoses i fixacions ortopèdiques.',
      es: 'Su uso principal es el cierre del esternón tras una esternotomía media (véase la entrada de cierre esternal de este catálogo), donde se aplica habitualmente en forma de puntos en ocho o circunferenciales; también se utiliza en algunas reparaciones tendinosas y fijaciones ortopédicas.',
      en: 'Its main use is sternal closure after median sternotomy (see this catalog\'s sternal closure entry), typically placed as figure-of-eight or circumferential wires; it is also used in some tendon repairs and orthopedic fixations.',
    ),
    tip: LocalizedText(
      ca: 'Ofereix la resistència i la seguretat de torsió més altes de totes les sutures i pràcticament no es degrada, però pot fracturar-se per fatiga amb el temps (una troballa relativament freqüent, sovint sense rellevància clínica, en radiografies de tòrax d\'esternotomies prèvies); cal doblegar bé o soterrar els extrems del fil tallat per evitar que irritin els teixits tous.',
      es: 'Ofrece la resistencia y seguridad de torsión más altas de todas las suturas y prácticamente no se degrada, pero puede fracturarse por fatiga con el tiempo (un hallazgo relativamente frecuente, a menudo sin relevancia clínica, en radiografías de tórax de esternotomías previas); hay que doblar bien o enterrar los extremos del alambre cortado para evitar que irriten los tejidos blandos.',
      en: 'It provides the highest strength and twist security of any suture material and is essentially non-degradable, but can fracture from metal fatigue over time (a relatively common, often clinically silent, finding on chest X-rays after prior sternotomy); cut wire ends must be well bent over or buried to avoid irritating soft tissue.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sutura-barbada-autoanclaje',
    name: LocalizedText(ca: 'Sutura amb pues autoancorant (barbada)', es: 'Sutura con púas autoanclante (barbada)', en: 'Barbed self-anchoring (knotless) suture'),
    category: InstrumentCategory.sutura,
    aliases: ['V-Loc', 'Quill', 'STRATAFIX'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Sutura monofilament amb pues tallades a la superfície del fil a intervals regulars, dissenyada perquè s\'ancori per si mateixa al teixit sense necessitat de fer nusos; existeix tant en versions absorbibles com no absorbibles, amb pues unidireccionals o bidireccionals.',
      es: 'Sutura monofilamento con púas talladas en la superficie del hilo a intervalos regulares, diseñada para anclarse por sí misma al tejido sin necesidad de hacer nudos; existe tanto en versiones absorbibles como no absorbibles, con púas unidireccionales o bidireccionales.',
      en: 'Monofilament suture with barbs cut into the strand\'s surface at regular intervals, designed to self-anchor into tissue without the need for knots; it is available in both absorbable and non-absorbable versions, with unidirectional or bidirectional barb patterns.',
    ),
    use: LocalizedText(
      ca: 'Especialment útil en cirurgia laparoscòpica i robòtica per a tancaments continus (per exemple, de fàscia, paret vaginal, miomectomia o anastomosis), ja que manté la tensió al llarg de la línia de sutura sense que calgui que un ajudant la sostingui ni fer nusos intracorporis.',
      es: 'Especialmente útil en cirugía laparoscópica y robótica para cierres continuos (por ejemplo, de fascia, pared vaginal, miomectomía o anastomosis), ya que mantiene la tensión a lo largo de la línea de sutura sin necesidad de que un ayudante la sostenga ni de hacer nudos intracorpóreos.',
      en: 'Particularly useful in laparoscopic and robotic surgery for running closures (for example, fascia, vaginal cuff, myomectomy, or anastomoses), since it maintains tension along the suture line without an assistant holding it or the need for intracorporeal knot tying.',
    ),
    tip: LocalizedText(
      ca: 'Les pues només permeten que el fil llisqui en una direcció, de manera que cal vigilar l\'orientació en inserir-lo per evitar que s\'ancori de forma prematura o invertida; en estirar-lo amb massa força es pot trencar, i el seu cost sol ser més alt que el d\'una sutura convencional equivalent.',
      es: 'Las púas solo permiten que el hilo deslice en una dirección, por lo que hay que vigilar la orientación al insertarlo para evitar que se ancle de forma prematura o invertida; al tensarlo con demasiada fuerza puede romperse, y su coste suele ser más alto que el de una sutura convencional equivalente.',
      en: 'The barbs allow the strand to slide in only one direction, so orientation must be watched during insertion to avoid premature or reversed anchoring; excessive tension can break the strand, and it typically costs more than an equivalent conventional suture.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'electrodo-dispersivo-adhesivo',
    name: LocalizedText(ca: 'Elèctrode dispersiu adhesiu d\'un sol ús', es: 'Electrodo dispersivo adhesivo de un solo uso', en: 'Disposable adhesive dispersive (return) electrode'),
    category: InstrumentCategory.especiales,
    aliases: ['electrodo de retorno del paciente', 'patient return electrode', 'electrodo neutro', 'neutral electrode', 'REM electrode (Return Electrode Monitoring)', 'placa dispersiva adhesiva'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Elèctrode d\'un sol ús format per una làmina adhesiva flexible (escuma o pel·lícula de polímer) amb una superfície conductora de gel hidrogel; moltes versions modernes tenen la superfície dividida en dos segments connectats per un cable bipartit al generador.',
      es: 'Electrodo desechable formado por una lámina adhesiva flexible (espuma o film polimérico) con una superficie conductora de gel hidrogel; muchas versiones modernas tienen la superficie dividida en dos segmentos conectados mediante un cable bipartito al generador.',
      en: 'A single-use flexible adhesive pad (foam or polymer film backing) with a conductive hydrogel surface; many modern versions have a split (dual-segment) conductive area wired through a two-pin cable to the generator.',
    ),
    use: LocalizedText(
      ca: 'S\'enganxa a una massa muscular gran del pacient (cuixa o natja) per tancar el circuit elèctric del bisturí elèctric monopolar i dispersar el corrent de retorn de manera segura cap al generador, evitant cremades per concentració de corrent.',
      es: 'Se adhiere a una masa muscular grande del paciente (muslo o glúteo) para cerrar el circuito eléctrico del electrobisturí monopolar y dispersar la corriente de retorno de forma segura hacia el generador, evitando quemaduras por concentración de corriente.',
      en: 'Applied to a large muscle mass on the patient (thigh or buttock) to complete the monopolar electrosurgery circuit, safely dispersing return current back to the generator and avoiding thermal injury from current concentration.',
    ),
    tip: LocalizedText(
      ca: 'Cal col·locar-lo sobre una massa muscular gran, ben vascularitzada, a prop del camp quirúrgic i evitar teixit cicatricial, prominències òssies o pèl; els elèctrodes de doble segment activen una alarma o aturada del generador si detecten pèrdua de contacte (monitorització de qualitat de contacte/REM), fet que prevé cremades.',
      es: 'Debe colocarse sobre una masa muscular grande y bien vascularizada, cerca del campo quirúrgico, evitando tejido cicatricial, prominencias óseas o vello; los electrodos de doble segmento activan una alarma o parada del generador si detectan pérdida de contacto (monitorización de calidad de contacto/REM), lo que previene quemaduras.',
      en: 'Place over a large, well-vascularized muscle mass close to the surgical site, avoiding scar tissue, bony prominences, or hair; dual-segment pads trigger a generator alarm or shutdown if contact quality deteriorates (contact quality/REM monitoring), which helps prevent burns.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'electrodo-dispersivo-placa-reutilizable',
    name: LocalizedText(ca: 'Elèctrode dispersiu reutilitzable de placa metàl·lica', es: 'Electrodo dispersivo reutilizable de placa metálica', en: 'Reusable metal plate return electrode'),
    category: InstrumentCategory.especiales,
    aliases: ['placa de tierra reutilizable', 'reusable grounding plate', 'metal dispersive plate electrode'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Placa rígida i plana de metall conductor (acer inoxidable o alumini) connectada mitjançant un cable reutilitzable al generador d\'electrocirurgia; requereix l\'aplicació de gel conductor entre la placa i la pell del pacient.',
      es: 'Placa rígida y plana de metal conductor (acero inoxidable o aluminio) conectada mediante un cable reutilizable al generador de electrocirugía; requiere la aplicación de gel conductor entre la placa y la piel del paciente.',
      en: 'A rigid, flat plate of conductive metal (stainless steel or aluminum) connected via a reusable cable to the electrosurgical generator; requires conductive gel applied between the plate and the patient\'s skin.',
    ),
    use: LocalizedText(
      ca: 'Es col·loca sota una zona corporal extensa del pacient (natges, cuixa o esquena) abans de cobrir-lo amb els camps quirúrgics, per tancar el circuit elèctric monopolar; ha estat en gran part substituïda pels elèctrodes adhesius d\'un sol ús.',
      es: 'Se coloca bajo una zona corporal extensa del paciente (glúteos, muslo o espalda) antes de cubrirlo con los campos quirúrgicos, para cerrar el circuito eléctrico monopolar; ha sido en gran parte sustituida por los electrodos adhesivos de un solo uso.',
      en: 'Positioned under a large body area of the patient (buttocks, thigh, or back) before draping, to complete the monopolar electrosurgery circuit; largely superseded by disposable adhesive electrodes.',
    ),
    tip: LocalizedText(
      ca: 'Cal comprovar que tota la superfície de la placa quedi en contacte uniforme amb la pell i el gel no s\'assequi, ja que la majoria de sistemes de placa reutilitzable no disposen de monitorització de qualitat de contacte, fet que històricament ha causat cremades per contacte parcial.',
      es: 'Debe verificarse que toda la superficie de la placa quede en contacto uniforme con la piel y que el gel no se seque, ya que la mayoría de los sistemas de placa reutilizable no disponen de monitorización de calidad de contacto, lo que históricamente ha causado quemaduras por contacto parcial.',
      en: 'Full, even contact between the plate and skin (with gel) must be verified before draping, since most reusable plate systems lack contact-quality monitoring, which historically has been a cause of burns from partial contact loss.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'campo-quirurgico-generico',
    name: LocalizedText(ca: 'Camp quirúrgic estèril genèric', es: 'Campo quirúrgico estéril genérico', en: 'Generic sterile surgical drape'),
    category: InstrumentCategory.especiales,
    aliases: ['sábana estéril quirúrgica', 'paño de campo', 'barrier drape', 'surgical drape sheet'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Làmina estèril de grans dimensions feta de teixit no teixit (polipropilè SMS) d\'un sol ús o de cotó/polièster reutilitzable, de vegades amb una zona reforçada resistent als fluids.',
      es: 'Lámina estéril de grandes dimensiones fabricada en tejido no tejido (polipropileno SMS) de un solo uso o en algodón/poliéster reutilizable, a veces con una zona reforzada resistente a fluidos.',
      en: 'A large sterile sheet made of single-use non-woven fabric (SMS polypropylene) or reusable cotton/polyester blend, sometimes with a reinforced fluid-resistant zone.',
    ),
    use: LocalizedText(
      ca: 'Cobreix el pacient i el mobiliari i instrumental circumdant per crear i mantenir el camp estèril, actuant com a barrera contra la migració de microorganismes cap a la zona quirúrgica.',
      es: 'Cubre al paciente y el mobiliario e instrumental circundante para crear y mantener el campo estéril, actuando como barrera frente a la migración de microorganismos hacia la zona quirúrgica.',
      en: 'Covers the patient and surrounding furniture/equipment to establish and maintain the sterile field, acting as a barrier against microbial migration into the surgical area.',
    ),
    tip: LocalizedText(
      ca: 'Els camps no teixits d\'un sol ús ofereixen una millor barrera davant la penetració de fluids (strike-through) que el cotó reutilitzable, motiu pel qual les guies AORN en recomanen l\'ús preferent segons el risc de contacte amb fluids del procediment.',
      es: 'Los campos no tejidos de un solo uso ofrecen una mejor barrera frente a la penetración de fluidos (strike-through) que el algodón reutilizable, por lo que las guías AORN recomiendan su uso preferente según el riesgo de contacto con fluidos del procedimiento.',
      en: 'Single-use non-woven drapes provide better resistance to fluid strike-through than reusable cotton, which is why AORN guidelines recommend selecting drape material based on the procedure\'s anticipated fluid exposure.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'campo-quirurgico-fenestrado',
    name: LocalizedText(ca: 'Camp quirúrgic fenestrat', es: 'Campo quirúrgico fenestrado', en: 'Fenestrated surgical drape'),
    category: InstrumentCategory.especiales,
    aliases: ['paño fenestrado', 'lap sheet', 'fenestrated laparotomy drape'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Camp estèril del mateix tipus de material que el genèric, amb una obertura retallada i reforçada (fenestració) de forma i mida adaptades a la regió anatòmica prevista per a la incisió.',
      es: 'Campo estéril del mismo tipo de material que el genérico, con una abertura recortada y reforzada (fenestración) de forma y tamaño adaptados a la región anatómica prevista para la incisión.',
      en: 'A sterile drape of similar material to the generic drape, with a pre-cut, reinforced opening (fenestration) shaped and sized for the anatomical region of the planned incision.',
    ),
    use: LocalizedText(
      ca: 'Es col·loca de manera que la fenestració emmarqui la zona d\'incisió ja preparada, mentre cobreix i aïlla la resta del cos del pacient per mantenir l\'esterilitat del camp.',
      es: 'Se coloca de modo que la fenestración enmarque la zona de incisión ya preparada, mientras cubre y aísla el resto del cuerpo del paciente para mantener la esterilidad del campo.',
      en: 'Positioned so the fenestration frames the already-prepped incision site, while covering and isolating the rest of the patient\'s body to maintain field sterility.',
    ),
    tip: LocalizedText(
      ca: 'Cal triar la forma i la mida de la fenestració adequades al procediment (p. ex., fenestració d\'extremitat davant de laparotomia); una obertura mal dimensionada pot exposar pell no preparada o limitar l\'accés quirúrgic.',
      es: 'Debe elegirse la forma y el tamaño de fenestración adecuados al procedimiento (p. ej., fenestración de extremidad frente a laparotomía); una abertura mal dimensionada puede exponer piel no preparada o limitar el acceso quirúrgico.',
      en: 'Choose a fenestration shape and size appropriate to the procedure (e.g., extremity fenestration versus laparotomy); an incorrectly sized opening can expose unprepped skin or restrict surgical access.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'campo-adhesivo-incisional-iodado',
    name: LocalizedText(ca: 'Camp adhesiu incisional iodat', es: 'Campo adhesivo incisional iodado', en: 'Iodine-impregnated adhesive incise drape'),
    category: InstrumentCategory.especiales,
    aliases: ['Ioban', 'Ioban 2', 'incise drape', 'campo incisional antimicrobiano'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Pel·lícula de plàstic prima, transparent i adhesiva, impregnada amb un adhesiu antimicrobià iodòfor (povidona iodada), subministrada sobre un paper protector que es retira abans d\'aplicar-la.',
      es: 'Película de plástico fina, transparente y adhesiva, impregnada con un adhesivo antimicrobiano iodóforo (povidona yodada), suministrada sobre un papel protector que se retira antes de aplicarla.',
      en: 'A thin, transparent, adhesive plastic film impregnated with an iodophor (povidone-iodine) antimicrobial adhesive, supplied on a release liner that is removed before application.',
    ),
    use: LocalizedText(
      ca: 'S\'aplica directament sobre la pell preparada i seca al voltant de la incisió prevista; el cirurgià talla directament a través de la pel·lícula i la pell, i l\'adhesiu ajuda a reduir la contaminació de les vores de la ferida per la flora cutània.',
      es: 'Se aplica directamente sobre la piel preparada y seca alrededor de la incisión prevista; el cirujano corta directamente a través de la película y la piel, y el adhesivo ayuda a reducir la contaminación de los bordes de la herida por la flora cutánea.',
      en: 'Applied directly onto prepped, dry skin around the planned incision; the surgeon incises directly through the film and skin together, with the adhesive helping reduce wound-edge contamination from resident skin flora.',
    ),
    tip: LocalizedText(
      ca: 'La pell ha d\'estar completament seca abans de l\'aplicació, ja que la humitat impedeix una bona adhesió i pot provocar que el camp es desenganxi durant la intervenció; està contraindicat en pacients amb al·lèrgia al iode/iodòfors.',
      es: 'La piel debe estar completamente seca antes de la aplicación, ya que la humedad impide una buena adhesión y puede provocar que el campo se despegue durante la intervención; está contraindicado en pacientes con alergia al yodo/yodóforos.',
      en: 'Skin must be completely dry before application, since moisture prevents proper adhesion and can cause the drape to lift intraoperatively; contraindicated in patients with iodine/iodophor allergy.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'funda-mesa-mayo',
    name: LocalizedText(ca: 'Funda estèril per a taula de Mayo', es: 'Funda estéril para mesa de Mayo', en: 'Mayo stand cover'),
    category: InstrumentCategory.especiales,
    aliases: ['Mayo tray cover', 'Mayo stand drape'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Funda estèril, generalment impermeable, de tela no teixida o làmines de paper/plàstic laminat, confeccionada amb la forma de la safata de la taula de Mayo i sovint amb una butxaca reforçada a l\'extrem que cobreix el suport.',
      es: 'Funda estéril, generalmente impermeable, de tela no tejida o láminas de papel/plástico laminado, confeccionada con la forma de la bandeja de la mesa de Mayo y a menudo con un bolsillo reforzado en el extremo que cubre el soporte.',
      en: 'A sterile, typically waterproof cover made of non-woven fabric or laminated paper/plastic, shaped to fit the Mayo stand tray, often with a reinforced pocket at one end that covers the support post.',
    ),
    use: LocalizedText(
      ca: 'Cobreix la safata de la taula de Mayo per crear una superfície estèril on la instrumentista hi col·loca els instruments d\'ús immediat durant la fase activa de la intervenció.',
      es: 'Cubre la bandeja de la mesa de Mayo para crear una superficie estéril donde la instrumentista coloca los instrumentos de uso inmediato durante la fase activa de la intervención.',
      en: 'Covers the Mayo stand tray to create a sterile surface on which the scrub person places the instruments immediately needed during the active phase of the operation.',
    ),
    tip: LocalizedText(
      ca: 'S\'ha de col·locar introduint les mans dins la butxaca/màniga protegida de la funda per evitar contaminar la superfície externa estèril; l\'extrem reforçat ha de cobrir sempre el suport o tija de la taula per evitar la penetració de fluids.',
      es: 'Debe colocarse introduciendo las manos dentro del bolsillo/manga protegida de la funda para evitar contaminar la superficie externa estéril; el extremo reforzado debe cubrir siempre el soporte o vástago de la mesa para evitar la penetración de fluidos.',
      en: 'Apply by sliding hands inside the protective pocket/sleeve of the cover to avoid contaminating the outer sterile surface; the reinforced end should always cover the stand\'s support post to prevent fluid strike-through.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'campo-bolsa-recoleccion-fluidos',
    name: LocalizedText(ca: 'Camp amb bossa de recollida de fluids', es: 'Campo con bolsa de recolección de fluidos', en: 'Fluid collection pouch drape'),
    category: InstrumentCategory.especiales,
    aliases: ['arthroscopy fluid collection drape', 'hysteroscopy fluid pouch', 'fluid control drape'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Camp estèril que incorpora una bossa o butxaca de plàstic integrada amb un orifici o tub de drenatge, dissenyada per col·locar-se per sota de la zona quirúrgica.',
      es: 'Campo estéril que incorpora una bolsa o bolsillo de plástico integrado con un orificio o tubo de drenaje, diseñado para colocarse por debajo de la zona quirúrgica.',
      en: 'A sterile drape incorporating an integrated plastic pouch with a drainage outlet or tubing port, designed to be positioned below the surgical site.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en procediments amb irrigació contínua de fluids (artroscòpia, histeroscòpia, resecció transuretral) per recollir el líquid d\'irrigació sobrant i dirigir-lo, mitjançant tub, cap a un sistema d\'aspiració o un recipient de recollida, evitant que s\'acumuli al terra o als camps.',
      es: 'Se utiliza en procedimientos con irrigación continua de fluidos (artroscopia, histeroscopia, resección transuretral) para recoger el líquido de irrigación sobrante y dirigirlo, mediante tubo, hacia un sistema de aspiración o un recipiente de recolección, evitando que se acumule en el suelo o en los campos.',
      en: 'Used in procedures involving continuous fluid irrigation (arthroscopy, hysteroscopy, transurethral resection) to capture excess irrigation fluid runoff and direct it via tubing to a suction system or collection container, preventing pooling on the floor or drapes.',
    ),
    tip: LocalizedText(
      ca: 'Connectar la sortida de la bossa a l\'aspiració i registrar el volum recollit és important per calcular el dèficit de fluids, especialment crític en histeroscòpia per evitar la sobrecàrrega de fluids (síndrome d\'absorció de líquid d\'irrigació).',
      es: 'Conectar la salida de la bolsa a la aspiración y registrar el volumen recolectado es importante para calcular el déficit de fluidos, especialmente crítico en histeroscopia para evitar la sobrecarga de fluidos (síndrome de absorción de líquido de irrigación).',
      en: 'Connecting the pouch outlet to suction and tracking collected volume is important for calculating fluid deficit, which is especially critical in hysteroscopy to avoid fluid overload (irrigation fluid absorption syndrome).',
    ),
    isNew: true,
  ),

