  Instrument(
    id: 'pinza-maryland',
    isNew: true,
    name: LocalizedText(ca: 'Pinça de Maryland', es: 'Pinza de Maryland', en: 'Maryland dissector'),
    category: InstrumentCategory.diseccion,
    specialty: Specialty.laparoscopiaEnergia,
    aliases: ['Maryland dissector', 'Maryland grasper', 'pinza de Maryland'],
    icon: 'pinch',
    description: LocalizedText(
      ca: 'Pinça laparoscòpica de mànec llarg (habitualment 5 mm) amb unes puntes fines, corbades i en punta que s\'obren en un pla estret per lliscar entre plans tissulars.',
      es: 'Pinza laparoscópica de mango largo (habitualmente 5 mm) con unas puntas finas, curvadas y en punta que se abren en un plano estrecho para deslizarse entre planos tisulares.',
      en: 'A long-shafted (typically 5 mm) laparoscopic forceps with fine, curved, tapered jaws that open in a narrow plane to slide between tissue planes.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per a la dissecció roma i la subjecció precisa de teixit i estructures vasculars fines durant procediments laparoscòpics com la colecistectomia, l\'apendicectomia o la histerectomia; sovint disponible en versió bipolar per coagular mentre es dissecciona.',
      es: 'Se utiliza para la disección roma y la sujeción precisa de tejido y estructuras vasculares finas durante procedimientos laparoscópicos como la colecistectomía, la apendicectomía o la histerectomía; a menudo disponible en versión bipolar para coagular mientras se disecciona.',
      en: 'Used for blunt dissection and precise grasping of tissue and fine vascular structures during laparoscopic procedures such as cholecystectomy, appendectomy or hysterectomy; often available in a bipolar version to coagulate while dissecting.',
    ),
  ),
  Instrument(
    id: 'gancho-monopolar',
    isNew: true,
    name: LocalizedText(ca: 'Ganxo monopolar', es: 'Gancho monopolar', en: 'Monopolar hook electrode'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.laparoscopiaEnergia,
    aliases: ['L-hook electrode', 'monopolar hook', 'diathermy hook', 'J-hook'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Elèctrode laparoscòpic prim, aïllat excepte a la punta activa en forma de ganxo (L o J), connectat a un generador d\'electrocirurgia monopolar.',
      es: 'Electrodo laparoscópico fino, aislado excepto en la punta activa en forma de gancho (L o J), conectado a un generador de electrocirugía monopolar.',
      en: 'A thin laparoscopic electrode, insulated except at its active hook-shaped (L- or J-shaped) tip, connected to a monopolar electrosurgical generator.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per enganxar, aixecar i dividir teixit amb energia monopolar (tall i coagulació simultanis), especialment en la dissecció del triangle de Calot durant la colecistectomia laparoscòpica.',
      es: 'Se utiliza para enganchar, elevar y dividir tejido con energía monopolar (corte y coagulación simultáneos), especialmente en la disección del triángulo de Calot durante la colecistectomía laparoscópica.',
      en: 'Used to hook, lift and divide tissue with monopolar energy (simultaneous cutting and coagulation), particularly for dissecting Calot\'s triangle during laparoscopic cholecystectomy.',
    ),
    tip: LocalizedText(
      ca: 'Una fallada d\'aïllament o l\'acoblament capacitiu poden causar una lesió tèrmica no intencionada lluny de la punta visible: cal inspeccionar l\'aïllament i fer servir la potència eficaç més baixa possible.',
      es: 'Un fallo de aislamiento o el acoplamiento capacitivo pueden causar una lesión térmica inadvertida lejos de la punta visible: inspeccionar el aislamiento y usar la potencia eficaz más baja posible.',
      en: 'Insulation defects or capacitive coupling can cause unintended thermal injury away from the visible tip; inspect the insulation and use the lowest effective power setting.',
    ),
  ),
  Instrument(
    id: 'aplicador-clips-laparoscopico',
    isNew: true,
    name: LocalizedText(ca: 'Aplicador de clips laparoscòpic', es: 'Aplicador de clips laparoscópico', en: 'Laparoscopic clip applier'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.laparoscopiaEnergia,
    aliases: ['Hem-o-lok', 'Ligaclip', 'clip applier', 'aplicador de clips'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Instrument laparoscòpic de mànec llarg que carrega i allibera clips metàl·lics o de polímer autoblocants a través de les seves mandíbules.',
      es: 'Instrumento laparoscópico de mango largo que carga y libera clips metálicos o de polímero autobloqueantes a través de sus mandíbulas.',
      en: 'A long-shafted laparoscopic instrument that loads and deploys metal or self-locking polymer clips through its jaws.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per ocloure el conducte cístic i l\'artèria cística en la colecistectomia laparoscòpica, o altres vasos i estructures tubulars petites, abans de seccionar-les.',
      es: 'Se utiliza para ocluir el conducto cístico y la arteria cística en la colecistectomía laparoscópica, u otros vasos y estructuras tubulares pequeñas, antes de seccionarlas.',
      en: 'Used to occlude the cystic duct and cystic artery in laparoscopic cholecystectomy, or other small vessels and tubular structures, before they are divided.',
    ),
    tip: LocalizedText(
      ca: 'Cal assegurar que tota l\'amplada del conducte o vas quedi visible dins les mandíbules del clip abans de tancar-lo, ja que la migració o el despreniment del clip és una complicació reconeguda, encara que poc freqüent.',
      es: 'Asegurar que todo el ancho del conducto o vaso quede visible dentro de las mandíbulas del clip antes de cerrarlo, ya que la migración o el desprendimiento del clip es una complicación reconocida, aunque poco frecuente.',
      en: 'Ensure the full width of the duct or vessel is visible within the clip jaws before closing it, since clip migration or dislodgement is a recognized, if uncommon, complication.',
    ),
  ),
  Instrument(
    id: 'separador-higado-nathanson',
    isNew: true,
    name: LocalizedText(ca: 'Separador hepàtic de Nathanson', es: 'Separador hepático de Nathanson', en: 'Nathanson liver retractor'),
    category: InstrumentCategory.separacion,
    specialty: Specialty.laparoscopiaEnergia,
    aliases: ['Nathanson retractor', 'Nathanson liver retractor', 'separador de Nathanson'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador laparoscòpic rígid amb una pala atraumàtica corbada (en ganxo o cullera) a l\'extrem distal i un extrem proximal hexagonal que s\'acobla a un braç de suport fix a la taula quirúrgica.',
      es: 'Separador laparoscópico rígido con una pala atraumática curva (en gancho o cuchara) en el extremo distal y un extremo proximal hexagonal que se acopla a un brazo de soporte fijo a la mesa quirúrgica.',
      en: 'A rigid laparoscopic retractor with an atraumatic curved (hook- or spoon-shaped) blade at the distal end and a hexagonal proximal end that locks into a table-mounted holding arm.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per aixecar i mantenir retret el lòbul hepàtic esquerre durant la cirurgia laparoscòpica de l\'estómac, l\'esòfag i la part alta de l\'abdomen (per exemple, bypass gàstric, sleeve gàstric o Nissen), alliberant les mans de l\'ajudant.',
      es: 'Se utiliza para elevar y mantener retraído el lóbulo hepático izquierdo durante la cirugía laparoscópica del estómago, el esófago y la parte alta del abdomen (por ejemplo, bypass gástrico, sleeve gástrico o Nissen), liberando las manos del ayudante.',
      en: 'Used to elevate and hold back the left hepatic lobe during laparoscopic upper gastrointestinal surgery (such as gastric bypass, sleeve gastrectomy or Nissen fundoplication), since it is held by a fixed table-mounted arm rather than an assistant\'s hand.',
    ),
    tip: LocalizedText(
      ca: 'La compressió mantinguda del fetge pot causar disfunció hepàtica transitòria postoperatòria (elevació d\'enzims hepàtics), per la qual cosa es recomana alliberar la pressió periòdicament en procediments llargs.',
      es: 'La compresión mantenida del hígado puede causar disfunción hepática transitoria postoperatoria (elevación de enzimas hepáticas), por lo que se aconseja liberar la presión periódicamente en procedimientos largos.',
      en: 'Sustained compression of the liver can cause transient postoperative liver dysfunction (elevated liver enzymes), so periodically releasing pressure during long procedures is advisable.',
    ),
  ),
  Instrument(
    id: 'laparoscopio',
    isNew: true,
    name: LocalizedText(ca: 'Laparoscopi', es: 'Laparoscopio', en: 'Laparoscope'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.laparoscopiaEnergia,
    aliases: ['rigid telescope', 'Hopkins telescope', 'òptica laparoscòpica', 'laparoscope'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tub rígid metàl·lic que conté un sistema òptic de lents de vidre en bastó (sistema Hopkins) connectat a una font de llum i a una càmera de vídeo, disponible habitualment en angles de visió de 0° o 30°.',
      es: 'Tubo rígido metálico que contiene un sistema óptico de lentes de vidrio en forma de bastón (sistema Hopkins) conectado a una fuente de luz y a una cámara de vídeo, disponible habitualmente en ángulos de visión de 0° o 30°.',
      en: 'A rigid metal tube containing a rod-lens optical system (Hopkins system) connected to a light source and video camera, commonly available with 0° or 30° viewing angles.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per visualitzar la cavitat abdominal o pèlvica a la pantalla durant qualsevol procediment laparoscòpic, transmetent la imatge captada per la càmera acoblada al seu extrem proximal.',
      es: 'Se utiliza para visualizar la cavidad abdominal o pélvica en la pantalla durante cualquier procedimiento laparoscópico, transmitiendo la imagen captada por la cámara acoplada a su extremo proximal.',
      en: 'Used to visualize the abdominal or pelvic cavity on screen during any laparoscopic procedure, relaying the image captured through the camera head attached to its proximal end.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/5/59/Karl_Storz_Laparaskopie_Optik.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Ibrahim Husain Meraj, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Karl_Storz_Laparaskopie_Optik.jpg',
    ),
  ),
  Instrument(
    id: 'insuflador-co2',
    isNew: true,
    name: LocalizedText(ca: 'Insuflador de CO2', es: 'Insuflador de CO2', en: 'CO2 insufflator'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.laparoscopiaEnergia,
    aliases: ['Laparoflator', 'Endoflator', 'insuflador de neumoperitoneo', 'high-flow insufflator'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Aparell electrònic connectat a una font de diòxid de carboni que regula i subministra el gas a través d\'un tub fins al trocar, controlant la pressió i el flux d\'insuflació.',
      es: 'Aparato electrónico conectado a una fuente de dióxido de carbono que regula y suministra el gas a través de un tubo hasta el trocar, controlando la presión y el flujo de insuflación.',
      en: 'An electronic device connected to a carbon dioxide source that regulates and delivers gas through tubing to the trocar, controlling insufflation pressure and flow.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per crear i mantenir el pneumoperitoneu durant tota la cirurgia laparoscòpica, mantenint una pressió intraabdominal preestablerta i reposant automàticament el gas perdut per fuites.',
      es: 'Se utiliza para crear y mantener el neumoperitoneo durante toda la cirugía laparoscópica, manteniendo una presión intraabdominal preestablecida y reponiendo automáticamente el gas perdido por fugas.',
      en: 'Used to establish and maintain pneumoperitoneum throughout laparoscopic surgery, holding a preset intra-abdominal pressure and automatically replacing gas lost through leaks.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/a/a9/200417-N-DA693-1420_%2849798499313%29.jpg',
      license: 'Public domain (U.S. federal government work)',
