      ca: 'S\'utilitza, normalment colpejat amb un martell quirúrgic, per tallar o remodelar l\'os durant osteotomies, artroplàsties i cirurgia de fractures.',
      es: 'Se utiliza, normalmente golpeado con un martillo quirúrgico, para cortar o remodelar el hueso durante osteotomías, artroplastias y cirugía de fracturas.',
      en: 'Struck with a surgical mallet, it is used to cut or reshape bone during osteotomies, joint replacement surgery and fracture surgery.',
    ),
    tip: LocalizedText(
      ca: 'A diferència d\'un cisell ossi d\'un sol bisell, l\'osteòtom té bisell a ambdós costats, cosa que ajuda a que el tall segueixi una línia més recta.',
      es: 'A diferencia de un escoplo óseo de un solo bisel, el osteótomo está biselado por ambos lados, lo que ayuda a que el corte siga una línea más recta.',
      en: 'Unlike a single-beveled bone chisel, an osteotome is beveled on both sides, which helps it cut in a straighter line.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/0/08/Osteotome.1ger.jpg',
      license: 'Public Domain',
      attribution: 'Gerhard Iglhaut (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Osteotome.1ger.jpg',
    ),
  ),
  Instrument(
    id: 'gubia-osea',
    isNew: true,
    name: LocalizedText(ca: 'Gúbia òssia (pinça gúbia)', es: 'Gubia ósea (pinza gubia)', en: 'Bone rongeur'),
    category: InstrumentCategory.corte,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Rongeur', 'Stille-Luer rongeur', 'Bone nibbler'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Pinça robusta de doble acció amb mordasses tallants i còncaves, dissenyada per rosegar i retallar petits fragments d\'os.',
      es: 'Pinza robusta de doble acción con mordazas cortantes y cóncavas, diseñada para morder y recortar pequeños fragmentos de hueso.',
      en: 'A sturdy double-action forceps with sharp, cup-shaped jaws designed to bite away and trim small fragments of bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per retirar vores òssies, osteòfits o fragments petits en cirurgia ortopèdica, de columna i neuroquirúrgica, per exemple en laminectomies o en la preparació de vores per a empelts.',
      es: 'Se utiliza para retirar bordes óseos, osteofitos o fragmentos pequeños en cirugía ortopédica, de columna y neuroquirúrgica, por ejemplo en laminectomías o en la preparación de bordes para injertos.',
      en: 'Used to remove bone edges, osteophytes or small fragments in orthopedic, spine and neurosurgical procedures, such as laminectomy or preparing bone edges for grafting.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/8e/Kerrison_rounger_.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'RobozTech, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Kerrison_rounger_.jpg',
    ),
  ),
  Instrument(
    id: 'sierra-gigli',
    isNew: true,
    name: LocalizedText(ca: 'Serra de Gigli', es: 'Sierra de Gigli', en: 'Gigli saw'),
    category: InstrumentCategory.corte,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Gigli wire saw'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Serra manual flexible formada per un filferro trenat amb vores tallants, que s\'acciona estirant-la endavant i endarrere amb un mànec a cada extrem.',
      es: 'Sierra manual flexible formada por un alambre trenzado con bordes cortantes, que se acciona tirando de ella hacia delante y atrás con un mango en cada extremo.',
      en: 'A flexible manual saw made of twisted wire with cutting edges, operated by pulling it back and forth using a handle at each end.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per seccionar os de manera controlada en amputacions, osteotomies i reseccions òssies, especialment en espais reduïts on no hi cap una serra rígida.',
      es: 'Se utiliza para seccionar hueso de forma controlada en amputaciones, osteotomías y resecciones óseas, especialmente en espacios reducidos donde no cabe una sierra rígida.',
      en: 'Used to cut bone in a controlled way during amputations, osteotomies and bone resections, especially in confined spaces where a rigid saw cannot reach.',
    ),
    tip: LocalizedText(
      ca: 'Com que no necessita cap font d\'energia i talla en una franja molt estreta, continua sent útil quan una serra rígida no es pot angular en un espai reduït.',
      es: 'Como no necesita ninguna fuente de energía y corta en una franja muy estrecha, sigue siendo útil cuando una sierra rígida no puede angularse en un espacio reducido.',
      en: 'Because it needs no power source and cuts in a narrow track, it remains useful when a rigid saw cannot be angled into a confined space.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Gigli_Saw.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Z22 (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Gigli_Saw.jpg',
    ),
  ),
  Instrument(
    id: 'separador-hohmann',
    isNew: true,
    name: LocalizedText(ca: 'Separador de Hohmann', es: 'Separador de Hohmann', en: 'Hohmann retractor'),
    category: InstrumentCategory.separacion,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Hohmann elevator'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador de mà amb un mànec llarg i una pala corba o angulada, la punta de la qual s\'encaixa contra l\'os.',
      es: 'Separador de mano con un mango largo y una pala curva o angulada, cuya punta se encaja contra el hueso.',
      en: 'A handheld retractor with a long handle and a curved or angled blade whose tip hooks against bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per separar músculs i parts toves de l\'os i exposar el camp quirúrgic en cirurgia de maluc, genoll, pelvis i fractures d\'ossos llargs.',
      es: 'Se utiliza para separar músculos y partes blandas del hueso y exponer el campo quirúrgico en cirugía de cadera, rodilla, pelvis y fracturas de huesos largos.',
      en: 'Used to retract muscle and soft tissue away from bone to expose the surgical field in hip, knee, pelvic and long-bone fracture surgery.',
    ),
    tip: LocalizedText(
      ca: 'Es fabrica en moltes amplades i corbatures de pala; triar la que s\'adapta millor al contorn de l\'os redueix el risc de lesionar les parts toves amb la punta.',
      es: 'Se fabrica en muchos anchos y curvaturas de pala; elegir la que mejor se adapta al contorno del hueso reduce el riesgo de lesionar las partes blandas con la punta.',
      en: 'It comes in many blade widths and curvatures; choosing one that matches the bone\'s contour reduces the risk of soft-tissue injury from the tip.',
    ),
  ),
  Instrument(
    id: 'separador-gelpi',
    isNew: true,
    name: LocalizedText(ca: 'Separador de Gelpi', es: 'Separador de Gelpi', en: 'Gelpi retractor'),
    category: InstrumentCategory.separacion,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Gelpi self-retaining retractor'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador autoretenidor amb dues puntes corbes i afilades i un mecanisme de cremallera que en manté la distància un cop col·locat.',
      es: 'Separador autorretenido con dos puntas curvas y afiladas y un mecanismo de cremallera que mantiene la distancia entre ellas una vez colocado.',
      en: 'A self-retaining retractor with two sharp, curved prongs and a ratchet mechanism that holds them apart once set.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per mantenir oberta una incisió sense necessitat que un ajudant la subjecti, freqüent en cirurgia ortopèdica, de columna i ginecològica.',
      es: 'Se utiliza para mantener abierta una incisión sin necesidad de que un ayudante la sujete, frecuente en cirugía ortopédica, de columna y ginecológica.',
      en: 'Used to hold an incision open without an assistant having to hold it, commonly used in orthopedic, spine and gynecologic surgery.',
    ),
  ),
  Instrument(
    id: 'aguja-kirschner',
    isNew: true,
    name: LocalizedText(ca: 'Agulla de Kirschner (filferro de Kirschner)', es: 'Aguja de Kirschner (alambre de Kirschner)', en: 'Kirschner wire (K-wire)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['K-wire'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Filferro d\'acer inoxidable llis, amb la punta esmolada i de diàmetre petit (normalment per sota dels 2-3 mm).',
      es: 'Alambre de acero inoxidable liso, con la punta afilada y de diámetro pequeño (normalmente por debajo de los 2-3 mm).',
      en: 'A smooth, sharpened stainless-steel pin of small diameter (typically under about 2-3 mm).',
    ),
    use: LocalizedText(
      ca: 'S\'introdueix a través de l\'os, amb trepant manual o elèctric, per a la fixació percutània temporal de fractures petites (mà, canell, peu) o com a ancoratge per a tracció esquelètica.',
      es: 'Se introduce a través del hueso, con taladro manual o eléctrico, para la fijación percutánea temporal de fracturas pequeñas (mano, muñeca, pie) o como anclaje para tracción esquelética.',
      en: 'Driven through bone with a hand or power drill, it provides temporary percutaneous fixation of small fractures (hand, wrist, foot) or serves as an anchor for skeletal traction.',
    ),
    tip: LocalizedText(
      ca: 'Quan s\'utilitza per a fixació temporal, les agulles de Kirschner es solen retirar al cap d\'unes quatre setmanes, un cop ha avançat prou la consolidació.',
      es: 'Cuando se usan para fijación temporal, las agujas de Kirschner suelen retirarse al cabo de unas cuatro semanas, una vez ha avanzado suficientemente la consolidación.',
      en: 'When used for temporary fixation, K-wires are typically removed around four weeks later, once healing has progressed enough.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/a/a6/K-wire%2C_Kirschner_wire.png',
      license: 'CC BY-SA 4.0',
      attribution: 'Medin a.s., Czech Republic (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:K-wire,_Kirschner_wire.png',
    ),
  ),
  Instrument(
    id: 'clavo-steinmann',
    isNew: true,
    name: LocalizedText(ca: 'Clau de Steinmann', es: 'Clavo de Steinmann', en: 'Steinmann pin'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Steinmann nail'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Clau d\'acer rígid, de diàmetre més gran que una agulla de Kirschner (aproximadament 4-6 mm), amb la punta esmolada.',
      es: 'Clavo de acero rígido, de mayor diámetro que una aguja de Kirschner (aproximadamente 4-6 mm), con la punta afilada.',
      en: 'A rigid steel pin of larger diameter than a Kirschner wire (roughly 4-6 mm), with a sharpened tip.',
    ),
    use: LocalizedText(
      ca: 'S\'insereix a través de l\'os (p. ex. tíbia o fèmur) per aplicar tracció esquelètica o com a element temporal de fixació en fractures d\'ossos llargs.',
      es: 'Se inserta a través del hueso (p. ej. tibia o fémur) para aplicar tracción esquelética o como elemento temporal de fijación en fracturas de huesos largos.',
      en: 'Inserted through bone (e.g. tibia or femur) to apply skeletal traction or as a temporary fixation element in long-bone fractures.',
    ),
    tip: LocalizedText(
      ca: 'Un clau col·locat a la tíbia proximal és una manera habitual d\'aplicar tracció esquelètica en fractures de la diàfisi femoral.',
      es: 'Un clavo colocado en la tibia proximal es una forma habitual de aplicar tracción esquelética en fracturas de la diáfisis femoral.',
      en: 'A pin placed in the proximal tibia is a common way to apply skeletal traction for femoral shaft fractures.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/0/07/Steinman_pins.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Netha Hussain (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Steinman_pins.jpg',
    ),
  ),
  Instrument(
    id: 'estribo-traccion',
    isNew: true,
    name: LocalizedText(ca: 'Estrep de tracció (arc de Kirschner)', es: 'Estribo de tracción (arco de Kirschner)', en: 'Traction bow (Kirschner bow)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Kirschner bow', 'K-bow', 'Böhler stirrup'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Estructura metàl·lica en forma d\'U amb un mecanisme de tensió als extrems, que es fixa a un clau de Steinmann o una agulla de Kirschner.',
      es: 'Estructura metálica en forma de U con un mecanismo de tensión en los extremos, que se fija a un clavo de Steinmann o una aguja de Kirschner.',
      en: 'A U-shaped metal frame with a tensioning mechanism at each end that attaches to a Steinmann pin or Kirschner wire.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per tensar l\'agulla o el clau que travessa l\'os i penjar-hi els pesos de la tracció esquelètica, evitant que es doblegui.',
      es: 'Se utiliza para tensar la aguja o el clavo que atraviesa el hueso y colgar de él los pesos de la tracción esquelética, evitando que se doble.',
      en: 'Used to tension the wire or pin passing through the bone and attach the weights of skeletal traction, keeping it from bending.',
    ),
  ),
  Instrument(
    id: 'tornillo-oseo',
    isNew: true,
    name: LocalizedText(ca: 'Cargol ossi (cortical / esponjós)', es: 'Tornillo óseo (cortical / esponjoso)', en: 'Bone screw (cortical / cancellous)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Cortical screw', 'Cancellous screw', 'AO screw'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Implant metàl·lic roscat; el cortical té una rosca fina i poc profunda, i l\'esponjós una rosca més ampla i profunda per agafar-se a l\'os trabecular.',
      es: 'Implante metálico roscado; el cortical tiene una rosca fina y poco profunda, y el esponjoso una rosca más ancha y profunda para agarrarse al hueso trabecular.',
      en: 'A threaded metal implant; the cortical type has a fine, shallow thread, while the cancellous type has a wider, deeper thread to grip trabecular (spongy) bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per fixar fragments ossis entre si o per subjectar plaques d\'osteosíntesi sobre l\'os en cirurgia de fractures i ortopèdica.',
      es: 'Se utiliza para fijar fragmentos óseos entre sí o para sujetar placas de osteosíntesis sobre el hueso en cirugía de fracturas y ortopédica.',
      en: 'Used to fix bone fragments to each other or to secure osteosynthesis plates onto bone in fracture and orthopedic surgery.',
    ),
    tip: LocalizedText(
      ca: 'Els cargols esponjosos solen tenir rosca parcial, de manera que en estrènyer-los comprimeixen els fragments entre si en comptes de només fixar-los al lloc.',
      es: 'Los tornillos esponjosos suelen ser de rosca parcial, de modo que al apretarlos comprimen los fragmentos entre sí en lugar de solo fijarlos en su sitio.',
      en: 'Cancellous screws are often partially threaded, so tightening them compresses the fragments together instead of just anchoring in place.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/b/b8/Cancellous_screw.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Netha Hussain (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Cancellous_screw.jpg',
    ),
  ),
  Instrument(
    id: 'calibrador-profundidad',
    isNew: true,
    name: LocalizedText(ca: 'Calibrador de profunditat', es: 'Calibrador de profundidad', en: 'Depth gauge'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Depth gauge probe'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Instrument en forma de vareta amb un ganxo a la punta i una escala mil·limetrada, que s\'introdueix dins un forat perforat a l\'os.',
      es: 'Instrumento en forma de varilla con un gancho en la punta y una escala milimetrada, que se introduce dentro de un orificio perforado en el hueso.',
      en: 'A rod-shaped instrument with a hooked tip and a millimeter scale, inserted into a drilled hole in the bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per mesurar la profunditat d\'un forat perforat a l\'os i determinar la longitud correcta del cargol que s\'hi col·locarà.',
      es: 'Se utiliza para medir la profundidad de un orificio perforado en el hueso y determinar la longitud correcta del tornillo que se colocará.',
      en: 'Used to measure the depth of a drilled bone hole and determine the correct length of screw to be inserted.',
    ),
    tip: LocalizedText(
      ca: 'La precisió de la mesura millora amb l\'experiència, per això sovint es torna a comprovar la lectura abans de triar un cargol llarg.',
      es: 'La precisión de la medida mejora con la experiencia, por eso a menudo se vuelve a comprobar la lectura antes de elegir un tornillo largo.',
      en: 'Measurement accuracy improves with experience, so the reading is often double-checked before picking a long screw.',
    ),
  ),
  Instrument(
    id: 'torniquete-neumatico',
    isNew: true,
    name: LocalizedText(ca: 'Torniquet pneumàtic quirúrgic', es: 'Torniquete neumático quirúrgico', en: 'Pneumatic surgical tourniquet'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Pneumatic tourniquet system', 'Automated tourniquet'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Equip format per un maniguet inflable que envolta l\'extremitat, connectat a una unitat de control que l\'infla i en regula electrònicament la pressió.',
      es: 'Equipo formado por un manguito inflable que rodea la extremidad, conectado a una unidad de control que lo infla y regula electrónicamente la presión.',
      en: 'A device consisting of an inflatable cuff wrapped around the limb, connected to a control unit that inflates it and electronically regulates the pressure.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per ocloure temporalment la circulació d\'una extremitat i obtenir un camp quirúrgic pràcticament exsangüe durant cirurgia ortopèdica, de mà o de peu.',
      es: 'Se utiliza para ocluir temporalmente la circulación de una extremidad y obtener un campo quirúrgico prácticamente exangüe durante cirugía ortopédica, de mano o de pie.',
      en: 'Used to temporarily occlude blood flow to a limb, producing a largely bloodless surgical field during orthopedic, hand or foot surgery.',
    ),
    tip: LocalizedText(
      ca: 'Les unitats modernes amb control per microprocessador regulen la pressió del maniguet en temps real i en vigilen el temps d\'inflat per ajudar a limitar el risc de lesió nerviosa o tissular.',
      es: 'Las unidades modernas con control por microprocesador regulan la presión del manguito en tiempo real y vigilan el tiempo de inflado para ayudar a limitar el riesgo de lesión nerviosa o tisular.',
      en: 'Modern microprocessor-controlled units regulate cuff pressure in real time and track inflation time to help limit the risk of nerve or tissue injury.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/5/5c/Modern_tourniquet_system_attached_to_a_modern_wide_contour_cuff.jpg',
      license: 'CC BY-SA 3.0 / GFDL 1.2+',
      attribution: 'Mgebert (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Modern_tourniquet_system_attached_to_a_modern_wide_contour_cuff.jpg',
    ),
  ),
  Instrument(
    id: 'artroscopio',
    isNew: true,
    name: LocalizedText(ca: 'Artroscopi', es: 'Artroscopio', en: 'Arthroscope'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Arthroscopy scope'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tub prim i rígid amb un sistema òptic i de llum (sovint acoblat a una microcàmera), que es connecta a un monitor de vídeo.',
      es: 'Tubo fino y rígido con un sistema óptico y de luz (a menudo acoplado a una microcámara), que se conecta a un monitor de vídeo.',
      en: 'A thin, rigid tube with an optical and light system (usually coupled to a small camera) that connects to a video monitor.',
    ),
    use: LocalizedText(
      ca: 'S\'introdueix a través d\'una petita incisió per visualitzar l\'interior d\'una articulació (genoll, espatlla, maluc, turmell) i guiar procediments mínimament invasius.',
      es: 'Se introduce a través de una pequeña incisión para visualizar el interior de una articulación (rodilla, hombro, cadera, tobillo) y guiar procedimientos mínimamente invasivos.',
      en: 'Inserted through a small incision to visualize the inside of a joint (knee, shoulder, hip, ankle) and guide minimally invasive procedures.',
    ),
  ),
  Instrument(
    id: 'mesa-traccion-ortopedica',
    isNew: true,
    name: LocalizedText(ca: 'Taula de tracció ortopèdica (taula de fractures)', es: 'Mesa de tracción ortopédica (mesa de fracturas)', en: 'Orthopedic traction table (fracture table)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Fracture table', 'Hana table'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Taula quirúrgica especialitzada amb suports per a les cames que permeten aplicar i mantenir tracció longitudinal de manera controlada durant la intervenció.',
      es: 'Mesa quirúrgica especializada con soportes para las piernas que permiten aplicar y mantener tracción longitudinal de forma controlada durante la intervención.',
      en: 'A specialized operating table with leg supports that allow controlled longitudinal traction to be applied and maintained throughout the procedure.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en cirurgia de fractures de fèmur i maluc (p. ex. enclavat endomedul·lar, artroplàstia per via anterior) per facilitar la reducció indirecta i mantenir-la durant el procediment.',
      es: 'Se utiliza en cirugía de fracturas de fémur y cadera (p. ej. enclavado endomedular, artroplastia por vía anterior) para facilitar la reducción indirecta y mantenerla durante el procedimiento.',
      en: 'Used in femur and hip fracture surgery (e.g. intramedullary nailing, anterior-approach arthroplasty) to facilitate indirect fracture reduction and maintain it throughout the procedure.',
    ),
    tip: LocalizedText(
      ca: 'Les taules de tracció poden provocar lesió per pressió al perineu o lesió nerviosa per estirament si no es vigila amb cura la posició i la força de tracció.',
      es: 'Las mesas de tracción pueden provocar lesión por presión en el periné o lesión nerviosa por estiramiento si no se vigila con cuidado la posición y la fuerza de tracción.',
      en: 'Traction tables can cause pressure injury to the perineum or nerve stretch injury if positioning and traction force are not checked carefully.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/2/23/US_Navy_090508-N-5234F-068_Dr._K.K._Singh%2C_center%2C_an_orthopedic_surgeon_consultant_at_Mount_St._Johns_Hospital%2C_examines_a_fracture_table_donated_through_Continuing_Promise_2009.jpg',
      license: 'Public domain (U.S. federal government work)',
      attribution: 'Chief Mass Communication Specialist Teresa J. Frith, U.S. Navy, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:US_Navy_090508-N-5234F-068_Dr._K.K._Singh,_center,_an_orthopedic_surgeon_consultant_at_Mount_St._Johns_Hospital,_examines_a_fracture_table_donated_through_Continuing_Promise_2009.jpg',
    ),
  ),
  Instrument(
    id: 'arco-c',
    isNew: true,
    name: LocalizedText(ca: 'Arc en C (fluoroscòpia intraoperatòria)', es: 'Arco en C (fluoroscopia intraoperatoria)', en: 'C-arm (intraoperative fluoroscopy)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['C-arm fluoroscope', 'Mobile fluoroscopy unit'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Equip de raigs X mòbil amb un braç en forma de C que allotja l\'emissor i el detector d\'imatge en extrems oposats, i que permet obtenir imatges en temps real.',
      es: 'Equipo de rayos X móvil con un brazo en forma de C que aloja el emisor y el detector de imagen en extremos opuestos, y que permite obtener imágenes en tiempo real.',
      en: 'A mobile X-ray unit with a C-shaped arm holding the emitter and image detector at opposite ends, providing real-time imaging.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza durant la cirurgia per comprovar en temps real la reducció de la fractura, la posició dels implants (claus, plaques, cargols) i l\'alineació òssia.',
      es: 'Se utiliza durante la cirugía para comprobar en tiempo real la reducción de la fractura, la posición de los implantes (clavos, placas, tornillos) y la alineación ósea.',
      en: 'Used during surgery to check fracture reduction, implant position (nails, plates, screws) and bone alignment in real time.',
    ),
    tip: LocalizedText(
      ca: 'Com que utilitza radiació ionitzant, l\'equip quirúrgic aplica mesures de temps, distància i protecció (davantals i protectors tiroidals de plom) per minimitzar l\'exposició quan calen diverses exposicions seguides.',
      es: 'Como utiliza radiación ionizante, el equipo quirúrgico aplica medidas de tiempo, distancia y protección (delantales y protectores tiroideos de plomo) para minimizar la exposición cuando hacen falta varias exposiciones seguidas.',
      en: 'Because it uses ionizing radiation, staff follow time, distance and shielding practices (lead aprons, thyroid shields) to minimize exposure when several exposures are needed in a row.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/82/New_Alma_Hospital_Mannarkkad_orthopaedic_OT_laminar_flow_C-arm.jpg',
      license: 'CC0 1.0 Universal (Public Domain Dedication)',
      attribution: 'Drnabeelmohdkk1, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:New_Alma_Hospital_Mannarkkad_orthopaedic_OT_laminar_flow_C-arm.jpg',
    ),
  ),

