  Instrument(
    id: 'pinza-kerrison',
    isNew: true,
    name: LocalizedText(ca: 'Pinça de Kerrison', es: 'Pinza de Kerrison', en: 'Kerrison rongeur'),
    category: InstrumentCategory.corte,
    specialty: Specialty.neurocirugia,
    aliases: ['Kerrison punch', 'Kerrison laminectomy rongeur', 'pinza sacabocados', 'pinza gubia de Kerrison'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Pinça de tall amb una placa fixa a la punta i una fulla que llisca i secciona l\'os en prémer el mànec; existeix en diverses amplades i angulacions (recta, cap amunt o cap avall).',
      es: 'Pinza de corte con una placa fija en la punta y una cuchilla deslizante que secciona el hueso al apretar el mango; existe en distintas anchuras y angulaciones (recta, hacia arriba o hacia abajo).',
      en: 'A punch-type rongeur with a fixed distal footplate and a sliding blade that bites through bone as the handle is squeezed; available in multiple widths and angulations (straight, up-biting, down-biting).',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per retirar làmina vertebral i marges ossis en laminectomies, laminotomies i foraminotomies, i per ampliar craniectomies; és un dels instruments més emprats en cirurgia d\'estenosi espinal i hèrnies discals.',
      es: 'Se usa para retirar lámina vertebral y bordes óseos en laminectomías, laminotomías y foraminotomías, y para ampliar craniectomías; es uno de los instrumentos más empleados en cirugía de estenosis espinal y hernias discales.',
      en: 'Used to remove vertebral lamina and bone edges during laminectomy, laminotomy and foraminotomy, and to enlarge craniectomy margins; one of the most frequently used instruments in spinal stenosis and disc herniation surgery.',
    ),
    tip: LocalizedText(
      ca: 'Cal avançar la fulla amb control i sense tensionar la duramare subjacent, ja que la durotomia és una complicació ben descrita amb aquest instrument.',
      es: 'Conviene avanzar la cuchilla con control y sin tensionar la duramadre subyacente, ya que la durotomía es una complicación bien descrita con este instrumento.',
      en: 'Advance the blade under control and without tenting the underlying dura, since durotomy is a well-described complication of this instrument.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Kerrison%20Rongeur%20of%20Dr.%20John%20Hersel%20Gladney%20-%20DPLA%20-%20880c89e828ed41c889cd4c6feec6c446%20%28page%201%29.jpg',
      license: 'Public domain (US) - no known copyright restrictions (Missouri Historical Society determination)',
      attribution: 'Missouri Historical Society, St. Louis, via Digital Public Library of America (DPLA)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Kerrison_Rongeur_of_Dr._John_Hersel_Gladney_-_DPLA_-_880c89e828ed41c889cd4c6feec6c446_(page_1).jpg',
    ),
  ),
  Instrument(
    id: 'pinza-hipofisaria',
    isNew: true,
    name: LocalizedText(ca: 'Pinça hipofisària (pinça de disc)', es: 'Pinza hipofisaria (pinza de disco)', en: 'Pituitary rongeur (disc rongeur)'),
    category: InstrumentCategory.corte,
    specialty: Specialty.neurocirugia,
    aliases: ['Spurling pituitary rongeur', 'pinza de Spurling', 'disc forceps', 'cup rongeur'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Pinça tipus "pistol-grip" amb dues mandíbules còncaves (en forma de cullereta) que tallen i arrenquen petits fragments de teixit en tancar-se; disponible en versions recta, cap amunt i cap avall i diverses mides de mandíbula.',
      es: 'Pinza tipo "pistol-grip" con dos mandíbulas cóncavas (en forma de cuchara) que cortan y arrancan pequeños fragmentos de tejido al cerrarse; disponible en versiones recta, hacia arriba y hacia abajo y distintos tamaños de mandíbula.',
      en: 'A pistol-grip instrument with two cup-shaped hinged jaws that shear and pull away small fragments of tissue as they close; available in straight, up-biting and down-biting configurations and several jaw sizes.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per extreure fragments de disc intervertebral (nucli pulpós) en microdiscectomies lumbars i per a dissecció de teixit tou en cirurgia transesfenoïdal hipofisària, d\'on prové el seu nom.',
      es: 'Se usa para extraer fragmentos de disco intervertebral (núcleo pulposo) en microdiscectomías lumbares y para disección de tejido blando en cirugía transesfenoidal hipofisaria, de donde proviene su nombre.',
      en: 'Used to remove intervertebral disc fragments (nucleus pulposus) during lumbar microdiscectomy and for soft-tissue dissection in transsphenoidal pituitary surgery, the origin of its name.',
    ),
  ),
  Instrument(
    id: 'disector-penfield',
    isNew: true,
    name: LocalizedText(ca: 'Disector de Penfield', es: 'Disector de Penfield', en: 'Penfield dissector'),
    category: InstrumentCategory.diseccion,
    specialty: Specialty.neurocirugia,
    aliases: ['Penfield elevator', 'Penfield dura dissector', 'Penfield No. 1-5'],
    icon: 'pinch',
    description: LocalizedText(
      ca: 'Instrument manual sense frontissa, amb puntes intercanviables numerades (típicament de l\'1 al 5) de formes diferents -planes, corbades o en espàtula- a cada extrem de la tija.',
      es: 'Instrumento manual sin bisagra, con puntas intercambiables numeradas (típicamente del 1 al 5) de formas distintas -planas, curvas o en espátula- en cada extremo del vástago.',
      en: 'A simple, hingeless hand instrument with numbered interchangeable tips (typically No. 1 through 5) of different shapes -flat, curved or spatulate- at each end of the shaft.',
    ),
    use: LocalizedText(
      ca: 'S\'empra per dissecar i elevar la duramare, separar teixit nerviós o vascular de l\'os i desenganxar plans tissulars sense tallar, tant en craniotomies com en cirurgia de columna.',
      es: 'Se emplea para disecar y elevar la duramadre, separar tejido nervioso o vascular del hueso y despegar planos tisulares sin cortar, tanto en craneotomías como en cirugía de columna.',
      en: 'Used to dissect and elevate the dura mater, free nerve or vascular tissue from bone, and develop tissue planes bluntly without cutting, in both cranial and spinal procedures.',
    ),
  ),
  Instrument(
    id: 'separador-cerebral-autoestatico',
    isNew: true,
    name: LocalizedText(ca: 'Separador cerebral autoestàtic (sistema Leyla/Greenberg)', es: 'Separador cerebral autoestático (sistema Leyla/Greenberg)', en: 'Self-retaining brain retractor system (Leyla/Greenberg)'),
    category: InstrumentCategory.separacion,
    specialty: Specialty.neurocirugia,
    aliases: ['Leyla retractor', 'Greenberg retractor', 'brain spatula holder', 'retractor cerebral flexible'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Sistema format per una base de fixació ancorada al cap del pacient o al capçal craneal, braços articulats o flexibles i una o diverses pales (espàtules) mal·leables que sostenen el teixit cerebral un cop col·locades.',
      es: 'Sistema compuesto por una base de fijación anclada a la cabeza del paciente o al cabezal craneal, brazos articulados o flexibles y una o varias palas (espátulas) maleables que sostienen el tejido cerebral una vez colocadas.',
      en: 'A system made of a fixation base anchored either to the patient\'s own head or to a separate cranial frame, articulated or flexible arms, and one or more malleable blades (spatulas) that hold back brain tissue once positioned.',
    ),
    use: LocalizedText(
      ca: 'Proporciona una retracció cerebral estable i "sense mans" durant la resecció de tumors, el clipatge d\'aneurismes, la descompressió microvascular i altres abordatges intracranials i de base de crani perllongats.',
      es: 'Proporciona una retracción cerebral estable y "sin manos" durante la resección de tumores, el clipaje de aneurismas, la descompresión microvascular y otros abordajes intracraneales y de base de cráneo prolongados.',
      en: 'Provides stable, hands-free brain retraction during tumor resection, aneurysm clipping, microvascular decompression and other prolonged intracranial and skull-base approaches.',
    ),
  ),
  Instrument(
    id: 'aplicador-clip-aneurisma',
    isNew: true,
    name: LocalizedText(ca: 'Aplicador de clips d\'aneurisma', es: 'Aplicador de clips de aneurisma', en: 'Aneurysm clip applier'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.neurocirugia,
    aliases: ['Yasargil clip applier', 'Sugita clip applier', 'pinza aplicadora de clip'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Pinça de precisió dissenyada per acoblar-se a un model específic de clip d\'aneurisma (p. ex. Yasargil o Sugita), obrir-lo i tancar-lo de manera controlada sobre el coll de l\'aneurisma sense bloquejar la visió del cirurgià.',
      es: 'Pinza de precisión diseñada para acoplarse a un modelo específico de clip de aneurisma (p. ej. Yasargil o Sugita), abrirlo y cerrarlo de forma controlada sobre el cuello del aneurisma sin bloquear la visión del cirujano.',
      en: 'A precision forceps-like instrument built to engage a specific aneurysm clip design (e.g., Yasargil or Sugita), open it, and close it in a controlled way across the aneurysm neck without blocking the surgeon\'s view.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en el clipatge microquirúrgic d\'aneurismes cerebrals per col·locar, reposicionar i, si cal, retirar el clip permanent que oclou el coll aneurismàtic.',
      es: 'Se utiliza en el clipaje microquirúrgico de aneurismas cerebrales para colocar, reposicionar y, si es necesario, retirar el clip permanente que ocluye el cuello aneurismático.',
      en: 'Used in microsurgical clipping of cerebral aneurysms to place, reposition and, if needed, remove the permanent clip occluding the aneurysm neck.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Compression%20forceps%20for%20Yasargil%20clips%2C%20Tuttlingen%2C%20Germany%2C%20Wellcome%20L0058096.jpg',
