  Instrument(
    id: 'cateter-drenaje-ventricular-externo',
    isNew: true,
    name: LocalizedText(ca: 'Catèter de drenatge ventricular extern', es: 'Catéter de drenaje ventricular externo', en: 'External ventricular drain (EVD) catheter'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.neurocirugia,
    aliases: ['EVD', 'ventriculostomy catheter', 'catéter de ventriculostomía'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Catèter de plàstic tou i flexible, amb múltiples orificis laterals a la punta, que es col·loca a través d\'un orifici de trepà fins al ventricle lateral i es connecta a un sistema estèril tancat extern.',
      es: 'Catéter de plástico blando y flexible, con múltiples orificios laterales en la punta, que se coloca a través de un orificio de trépano hasta el ventrículo lateral y se conecta a un sistema estéril cerrado externo.',
      en: 'A soft, flexible plastic catheter with multiple side holes near its tip, inserted through a burr hole into the lateral ventricle and connected to a closed external sterile collection system.',
    ),
    use: LocalizedText(
      ca: 'Permet drenar temporalment el líquid cefalorraquidi i monitoritzar la pressió intracranial en hidrocefàlia aguda, hemorràgia intraventricular o traumatisme cranioencefàlic.',
      es: 'Permite drenar temporalmente el líquido cefalorraquídeo y monitorizar la presión intracraneal en hidrocefalia aguda, hemorragia intraventricular o traumatismo craneoencefálico.',
      en: 'Allows temporary drainage of cerebrospinal fluid and monitoring of intracranial pressure in acute hydrocephalus, intraventricular hemorrhage or traumatic brain injury.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/EVD-ICH.jpg',
      license: 'CC BY-SA 3.0 (also dual-licensed GFDL 1.2+)',
      attribution: 'Rmosler2100, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:EVD-ICH.jpg',
    ),
  ),
  Instrument(
    id: 'valvula-derivacion-ventriculoperitoneal',
    isNew: true,
    name: LocalizedText(ca: 'Vàlvula de derivació ventriculoperitoneal', es: 'Válvula de derivación ventriculoperitoneal', en: 'Ventriculoperitoneal (VP) shunt valve'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.neurocirugia,
    aliases: ['VP shunt', 'derivación VP', 'shunt valve system'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Sistema implantable format per un catèter ventricular amb múltiples orificis, una vàlvula unidireccional (fixa, ajustable o gravitacional) que regula el flux segons la pressió, i un catèter peritoneal distal.',
      es: 'Sistema implantable formado por un catéter ventricular con múltiples orificios, una válvula unidireccional (fija, ajustable o gravitacional) que regula el flujo según la presión, y un catéter peritoneal distal.',
      en: 'An implantable system made of a multi-perforated ventricular catheter, a one-way valve (fixed, adjustable or gravitational) that regulates flow according to pressure, and a distal peritoneal catheter.',
    ),
    use: LocalizedText(
      ca: 'Tracta la hidrocefàlia de forma permanent derivant el líquid cefalorraquidi en excés des dels ventricles cerebrals fins a la cavitat peritoneal, on es reabsorbeix.',
      es: 'Trata la hidrocefalia de forma permanente derivando el líquido cefalorraquídeo en exceso desde los ventrículos cerebrales hasta la cavidad peritoneal, donde se reabsorbe.',
      en: 'Permanently treats hydrocephalus by diverting excess cerebrospinal fluid from the cerebral ventricles into the peritoneal cavity, where it is reabsorbed.',
    ),
  ),
  Instrument(
    id: 'sensor-presion-intracraneal',
    isNew: true,
    name: LocalizedText(ca: 'Sensor/pern de pressió intracranial (PIC)', es: 'Sensor/perno de presión intracraneal (PIC)', en: 'Intracranial pressure (ICP) monitor/bolt'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.neurocirugia,
    aliases: ['ICP bolt', 'Camino bolt', 'Codman MicroSensor', 'subarachnoid bolt', 'Richmond bolt'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Dispositiu petit -un cargol buit intracranial o un catèter amb un microtransductor a la punta- que es col·loca a través d\'un orifici de trepà fins a l\'espai subdural, parenquimatós o intraventricular.',
      es: 'Dispositivo pequeño -un tornillo hueco intracraneal o un catéter con un microtransductor en la punta- que se coloca a través de un orificio de trépano hasta el espacio subdural, parenquimatoso o intraventricular.',
      en: 'A small device -either a hollow intracranial bolt or a catheter with a tip-mounted microtransducer- placed through a burr hole into the subdural, parenchymal or intraventricular space.',
    ),
    use: LocalizedText(
      ca: 'Mesura contínuament la pressió intracranial en traumatisme cranioencefàlic greu, hemorràgia o altres causes d\'hipertensió endocranial, per guiar el tractament a la unitat de cures intensives.',
      es: 'Mide continuamente la presión intracraneal en traumatismo craneoencefálico grave, hemorragia u otras causas de hipertensión endocraneal, para guiar el tratamiento en la unidad de cuidados intensivos.',
      en: 'Continuously measures intracranial pressure in severe traumatic brain injury, hemorrhage or other causes of raised intracranial pressure, to guide treatment in the intensive care unit.',
    ),
  ),
  Instrument(
    id: 'marco-estereotactico',
    isNew: true,
    name: LocalizedText(ca: 'Marc estereotàctic (p. ex. Leksell)', es: 'Marco estereotáctico (p. ej. Leksell)', en: 'Stereotactic frame (e.g., Leksell frame)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.neurocirugia,
    aliases: ['Leksell frame', 'stereotactic head frame', 'arco estereotáctico'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Marc metàl·lic o de compòsit que es fixa rígidament al crani amb cargols sota anestèsia local, combinat amb un arc que permet calcular coordenades cartesianes (x, y, z) sobre imatges de TC o RM.',
      es: 'Marco metálico o de composite que se fija rígidamente al cráneo con tornillos bajo anestesia local, combinado con un arco que permite calcular coordenadas cartesianas (x, y, z) sobre imágenes de TC o RM.',
      en: 'A metal or composite frame rigidly fixed to the skull with screws under local anesthesia, combined with an arc that allows Cartesian (x, y, z) coordinates to be calculated from CT or MRI images.',
    ),
    use: LocalizedText(
      ca: 'Permet localitzar amb precisió mil·limètrica un punt intracranial per a biòpsies cerebrals, implantació d\'elèctrodes d\'estimulació cerebral profunda, elèctrodes d\'estereoelectroencefalografia o planificació de radiocirurgia.',
      es: 'Permite localizar con precisión milimétrica un punto intracraneal para biopsias cerebrales, implantación de electrodos de estimulación cerebral profunda, electrodos de estereoelectroencefalografía o planificación de radiocirugía.',
      en: 'Allows millimeter-precise localization of an intracranial target for brain biopsies, deep brain stimulation electrode implantation, stereoelectroencephalography electrodes or radiosurgery planning.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Stereotactic%20Frame%20TM03B%20Micromar.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Renata Serpejante, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Stereotactic_Frame_TM03B_Micromar.jpg',
    ),
  ),
  Instrument(
    id: 'electrodo-estimulacion-cerebral-profunda',
    isNew: true,
    name: LocalizedText(ca: 'Elèctrode d\'estimulació cerebral profunda (DBS)', es: 'Electrodo de estimulación cerebral profunda (DBS)', en: 'Deep brain stimulation (DBS) electrode'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.neurocirugia,
    aliases: ['DBS lead', 'electrodo DBS', 'brain pacemaker lead'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Fil aïllat prim amb diversos contactes metàl·lics a la punta, que s\'implanta a través d\'un orifici de trepà fins a un nucli cerebral profund diana i es connecta, mitjançant una extensió subcutània, a un generador d\'impulsos implantat al tòrax.',
      es: 'Hilo aislado fino con varios contactos metálicos en la punta, que se implanta a través de un orificio de trépano hasta un núcleo cerebral profundo diana y se conecta, mediante una extensión subcutánea, a un generador de impulsos implantado en el tórax.',
      en: 'A thin insulated wire with several metal contacts at its tip, implanted through a burr hole into a deep target brain nucleus and connected, via a subcutaneous extension, to an implantable pulse generator placed in the chest.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en cirurgia funcional per tractar la malaltia de Parkinson, el tremolor essencial, la distonia i altres trastorns del moviment o neuropsiquiàtrics mitjançant estimulació elèctrica contínua d\'un nucli diana.',
      es: 'Se utiliza en cirugía funcional para tratar la enfermedad de Parkinson, el temblor esencial, la distonía y otros trastornos del movimiento o neuropsiquiátricos mediante estimulación eléctrica continua de un núcleo diana.',
      en: 'Used in functional neurosurgery to treat Parkinson\'s disease, essential tremor, dystonia and other movement or neuropsychiatric disorders through continuous electrical stimulation of a target nucleus.',
    ),
  ),
  Instrument(
    id: 'sistema-neuromonitorizacion-intraoperatoria',
    isNew: true,
    name: LocalizedText(ca: 'Sistema de neuromonitorització intraoperatòria (IONM)', es: 'Sistema de neuromonitorización intraoperatoria (IONM)', en: 'Intraoperative neurophysiological monitoring (IONM) system'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.neurocirugia,
    aliases: ['IONM', 'neuromonitoring', 'MEP/SSEP monitor'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Equip amb amplificadors, programari d\'estimulació/registre i elèctrodes de superfície o agulla connectats al pacient, operat per un neurofisiòleg des del mateix quiròfan.',
      es: 'Equipo con amplificadores, software de estimulación/registro y electrodos de superficie o aguja conectados al paciente, operado por un neurofisiólogo desde el propio quirófano.',
      en: 'Equipment combining amplifiers, stimulation/recording software and surface or needle electrodes attached to the patient, operated by a neurophysiologist from within the operating room.',
    ),
    use: LocalizedText(
      ca: 'Registra en temps real potencials evocats somatosensorials (SSEP), motors (MEP) i altres senyals per detectar un risc de lesió neurològica durant cirurgia de columna, tumors cerebrals o medul·lars i cirurgia vascular cerebral.',
      es: 'Registra en tiempo real potenciales evocados somatosensoriales (SSEP), motores (MEP) y otras señales para detectar un riesgo de lesión neurológica durante cirugía de columna, tumores cerebrales o medulares y cirugía vascular cerebral.',
      en: 'Records real-time somatosensory evoked potentials (SSEP), motor evoked potentials (MEP) and other signals to flag the risk of neurological injury during spine surgery, brain or spinal cord tumor resection, and cerebrovascular surgery.',
    ),
  ),
  Instrument(
    id: 'estimulador-cortical-manual',
    isNew: true,
    name: LocalizedText(ca: 'Estimulador cortical manual (tipus Ojemann)', es: 'Estimulador cortical manual (tipo Ojemann)', en: 'Handheld cortical stimulator (Ojemann-type)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.neurocirugia,
    aliases: ['Ojemann stimulator', 'bipolar cortical stimulator', 'estimulador bipolar de corteza'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Dispositiu portàtil alimentat per bateria, amb una sonda bipolar de dues puntes separades uns mil·límetres, que aplica un corrent constant ajustable directament sobre la superfície cortical.',
      es: 'Dispositivo portátil alimentado por batería, con una sonda bipolar de dos puntas separadas unos milímetros, que aplica una corriente constante ajustable directamente sobre la superficie cortical.',
      en: 'A portable, battery-powered device with a bipolar probe whose two tips sit a few millimeters apart, delivering an adjustable constant current directly onto the cortical surface.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per mapar intraoperatòriament àrees corticals eloqüents (motores, sensitives o del llenguatge) durant craniotomies despertes o sota anestèsia, per maximitzar la resecció tumoral preservant la funció.',
      es: 'Se utiliza para mapear intraoperatoriamente áreas corticales elocuentes (motoras, sensitivas o del lenguaje) durante craneotomías despiertas o bajo anestesia, para maximizar la resección tumoral preservando la función.',
      en: 'Used to intraoperatively map eloquent cortical areas (motor, sensory or language) during awake or anesthetized craniotomy, maximizing tumor resection while preserving function.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Cortical%20Stimulator.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Bahcecim, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Cortical_Stimulator.jpg',
    ),
  ),
  Instrument(
    id: 'cabezal-fijacion-mayfield',
    isNew: true,
    name: LocalizedText(ca: 'Capçal de fixació de Mayfield', es: 'Cabezal de fijación de Mayfield', en: 'Mayfield skull clamp (head holder)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.neurocirugia,
    aliases: ['Mayfield clamp', 'Mayfield head holder', 'three-pin skull clamp'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Sistema format per una pinça amb tres pues (dues a un costat, una a l\'altre amb cargol dinamomètric) i un braç articulat que s\'ancora a la taula quirúrgica.',
      es: 'Sistema formado por una pinza con tres puntas (dos a un lado, una al otro con tornillo dinamométrico) y un brazo articulado que se ancla a la mesa quirúrgica.',
      en: 'A system made of a three-pin clamp (two pins on one side, one on the other fitted with a torque screw) and an articulated arm that anchors to the operating table.',
    ),
    use: LocalizedText(
      ca: 'Immobilitza rígidament el crani del pacient respecte a la taula d\'operacions durant craniotomies i certs abordatges cervicals posteriors, permetent precisió amb microscopi o neuronavegació.',
      es: 'Inmoviliza rígidamente el cráneo del paciente respecto a la mesa de operaciones durante craneotomías y ciertos abordajes cervicales posteriores, permitiendo precisión con microscopio o neuronavegación.',
      en: 'Rigidly immobilizes the patient\'s skull relative to the operating table during craniotomies and certain posterior cervical approaches, enabling precision work with the microscope or neuronavigation.',
    ),
    tip: LocalizedText(
      ca: 'En infants petits o pacients amb calota molt prima cal valorar alternatives de fixació, ja que s\'han descrit fractures cranials amb les pues del Mayfield.',
      es: 'En niños pequeños o pacientes con calota muy fina conviene valorar alternativas de fijación, ya que se han descrito fracturas craneales con las puntas del Mayfield.',
      en: 'In young children or patients with very thin calvaria, alternative fixation should be considered, as skull fractures from the Mayfield pins have been reported.',
    ),
  ),
  Instrument(
    id: 'neuroendoscopio-rigido',
    isNew: true,
    name: LocalizedText(ca: 'Neuroendoscopi rígid', es: 'Neuroendoscopio rígido', en: 'Rigid neuroendoscope'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.neurocirugia,
    aliases: ['rigid ventriculoscope', 'neuroendoscopio', 'endoscopio intraventricular'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Endoscopi de tija rígida (habitualment d\'uns 4 mm de diàmetre) amb canal de treball, òptica d\'angle variable i connexió a font de llum i càmera, introduït a través d\'una cànula peel-away o tròcar.',
      es: 'Endoscopio de vástago rígido (habitualmente de unos 4 mm de diámetro) con canal de trabajo, óptica de ángulo variable y conexión a fuente de luz y cámara, introducido a través de una cánula peel-away o trocar.',
      en: 'A rigid-shaft endoscope (typically about 4 mm in diameter) with a working channel, variable-angle optics and connections to a light source and camera, introduced through a peel-away sheath or trocar.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en neuroendoscòpia per realitzar una tercera ventriculostomia endoscòpica en la hidrocefàlia obstructiva, biòpsies o exèresis de lesions intraventriculars i fenestracions de quists.',
      es: 'Se utiliza en neuroendoscopia para realizar una tercera ventriculostomía endoscópica en la hidrocefalia obstructiva, biopsias o exéresis de lesiones intraventriculares y fenestraciones de quistes.',
      en: 'Used in neuroendoscopy to perform endoscopic third ventriculostomy for obstructive hydrocephalus, biopsy or removal of intraventricular lesions, and cyst fenestration.',
    ),
  ),

