    description: LocalizedText(
      ca: 'Tub rígid o semirígid que es col·loca a l\'aurícula dreta o a les venes caves per drenar la sang venosa del pacient cap al circuit de circulació extracorpòria.',
      es: 'Tubo rígido o semirrígido que se coloca en la aurícula derecha o en las venas cavas para drenar la sangre venosa del paciente hacia el circuito de circulación extracorpórea.',
      en: 'A rigid or semi-rigid tube placed in the right atrium or the venae cavae to drain the patient\'s venous blood into the cardiopulmonary bypass circuit.',
    ),
