      es: 'Se utiliza, junto con la cánula aórtica, para establecer la circulación extracorpórea: recoge la sangre venosa antes de que pase por el oxigenador.',
      en: 'Used together with the aortic cannula to establish cardiopulmonary bypass, collecting venous blood before it passes through the oxygenator.',
    ),
