      es: 'Cánula fina, a veces con un balón oclusivo en la punta, que se coloca en la raíz aórtica (vía anterógrada) o en el seno coronario (vía retrógrada).',
      en: 'A thin cannula, sometimes with an occluding balloon tip, placed in the aortic root (antegrade route) or the coronary sinus (retrograde route).',
