  Instrument(
    id: 'balon-contrapulsacion-intraaortico',
    isNew: true,
    name: LocalizedText(ca: 'Baló de contrapulsació intraaòrtic', es: 'Balón de contrapulsación intraaórtico', en: 'Intra-aortic balloon pump'),
    category: InstrumentCategory.equipos,
