      es: 'Catéter con un balón cilíndrico de poliuretano en la punta, inflado con helio de forma sincronizada con el ciclo cardíaco, conectado a una consola externa.',
      en: 'A catheter with a cylindrical polyurethane balloon at its tip, inflated with helium in synchrony with the cardiac cycle and connected to an external console.',
    ),
    use: LocalizedText(
      ca: 'Es col·loca a l\'aorta descendent per augmentar la perfusió coronària i reduir la postcàrrega del ventricle esquerre, com a suport circulatori mecànic en xoc cardiogènic o en cirurgia cardíaca d\'alt risc.',
      es: 'Se coloca en la aorta descendente para aumentar la perfusión coronaria y reducir la poscarga del ventrículo izquierdo, como soporte circulatorio mecánico en shock cardiogénico o en cirugía cardíaca de alto riesgo.',
      en: 'It is placed in the descending aorta to increase coronary perfusion and reduce left ventricular afterload, providing mechanical circulatory support in cardiogenic shock or high-risk cardiac surgery.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/8b/Intra-aortic_balloon_pump.jpg',
