      es: 'Separador de cremallera con dos ramas que se abren gradualmente y mantienen separadas las dos mitades del esternón tras la esternotomía media.',
      en: 'A ratcheted retractor with two blades that open gradually and hold the two halves of the sternum apart after a median sternotomy.',
