      en: 'It provides exposure of the mediastinum and the heart during coronary revascularization, valve surgery, and other procedures performed through a median sternotomy.',
    ),
    tip: LocalizedText(
      ca: 'No s\'ha de confondre amb el separador de Finochietto: aquest obre l\'espai intercostal en toracotomies laterals, no l\'estèrnum.',
      es: 'No debe confundirse con el separador de Finochietto: este abre el espacio intercostal en toracotomías laterales, no el esternón.',
      en: 'Not to be confused with the Finochietto retractor, which spreads the intercostal space in lateral thoracotomies rather than the sternum.',
    ),
  ),
