  Instrument(
    id: 'cistoscopio-rigido',
    isNew: true,
    name: LocalizedText(ca: 'Cistoscopi rígid', es: 'Cistoscopio rígido', en: 'Rigid cystoscope'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.urologia,
    aliases: ['Cystoscope', 'Rigid cystoscope'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Endoscopi rígid format per una beina metàl·lica amb obturador i un telescopi òptic amb lents, que s\'introdueix per la uretra fins a la bufeta.',
      es: 'Endoscopio rígido formado por una vaina metálica con obturador y un telescopio óptico con lentes, que se introduce por la uretra hasta la vejiga.',
      en: 'A rigid endoscope consisting of a metal sheath with an obturator and a lens telescope, passed through the urethra into the bladder.',
    ),
    use: LocalizedText(
      ca: 'Permet explorar visualment la uretra i la bufeta (hematúria, tumors, litiasi, estenosis) i, a través del seu canal de treball, fer biòpsies, fulguracions o col·locar catèters/stents.',
      es: 'Permite explorar visualmente la uretra y la vejiga (hematuria, tumores, litiasis, estenosis) y, a través de su canal de trabajo, realizar biopsias, fulguraciones o colocar catéteres/stents.',
      en: 'Used to visually examine the urethra and bladder (haematuria, tumours, stones, strictures) and, through its working channel, to take biopsies, fulgurate lesions or place catheters/stents.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/3/33/Cystoscope-med-20050425.jpg',
      license: 'CC BY-SA 3.0 / GFDL 1.2+',
      attribution: 'Michael Reeve (MykReeve), Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Cystoscope-med-20050425.jpg',
    ),
  ),
  Instrument(
    id: 'sonda-foley',
    isNew: true,
    name: LocalizedText(ca: 'Sonda de Foley', es: 'Sonda de Foley', en: 'Foley catheter'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Foley catheter', 'Indwelling urinary catheter', 'Bard catheter'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Catèter flexible de làtex o silicona amb dos o tres llums: un per drenar l\'orina i un altre per inflar un globus de retenció a la punta un cop dins la bufeta.',
      es: 'Catéter flexible de látex o silicona con dos o tres luces: una para drenar la orina y otra para inflar un balón de retención en la punta una vez dentro de la vejiga.',
      en: 'A flexible latex or silicone catheter with two or three lumens: one drains urine and another inflates a retention balloon at the tip once inside the bladder.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per drenar la bufeta de forma contínua (retenció urinària, control de diüresi, incontinència, postoperatori); la versió de tres vies permet també fer rentats vesicals continus.',
      es: 'Se utiliza para drenar la vejiga de forma continua (retención urinaria, control de diuresis, incontinencia, postoperatorio); la versión de tres vías permite también realizar lavados vesicales continuos.',
      en: 'Used for continuous bladder drainage (urinary retention, urine-output monitoring, incontinence, postoperative care); the three-way version also allows continuous bladder irrigation.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Foley_catheter_CH_20_-_02.JPG',
      license: 'CC BY-SA 4.0',
      attribution: 'Mireksplay, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Foley_catheter_CH_20_-_02.JPG',
    ),
  ),
  Instrument(
    id: 'cateter-doble-j',
    isNew: true,
    name: LocalizedText(ca: 'Catèter doble J (stent ureteral)', es: 'Catéter doble J (stent ureteral)', en: 'Double-J (JJ) ureteral stent'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Double-J stent', 'JJ stent', 'Pigtail ureteral stent'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Tub prim de plàstic flexible amb els dos extrems enrotllats en espiral ("pigtail"), un que s\'allotja a la pelvis renal i l\'altre a la bufeta.',
      es: 'Tubo delgado de plástico flexible con los dos extremos enrollados en espiral ("pigtail"), uno que se aloja en la pelvis renal y el otro en la vejiga.',
      en: 'A thin flexible plastic tube with both ends curled into a coil ("pigtail"), one sitting in the renal pelvis and the other in the bladder.',
    ),
    use: LocalizedText(
      ca: 'Manté l\'urèter permeable i drena l\'orina del ronyó a la bufeta salvant una obstrucció (litiasi, tumor, estenosi) o protegint una sutura ureteral; se sol col·locar per cistoscòpia sobre una guia.',
      es: 'Mantiene el uréter permeable y drena la orina del riñón a la vejiga salvando una obstrucción (litiasis, tumor, estenosis) o protegiendo una sutura ureteral; suele colocarse por cistoscopia sobre una guía.',
      en: 'Keeps the ureter open and drains urine from the kidney to the bladder around an obstruction (stones, tumour, stricture) or protects a ureteral repair; typically placed cystoscopically over a guidewire.',
    ),
    tip: LocalizedText(
      ca: 'Cal un sistema de recordatori per retirar-lo o recanviar-lo (normalment en 4-6 setmanes): un stent oblidat es pot incrustar greument.',
      es: 'Es necesario un sistema de recordatorio para retirarlo o recambiarlo (normalmente en 4-6 semanas): un stent olvidado puede incrustarse gravemente.',
      en: 'A reminder/tracking system for removal or exchange (typically at 4-6 weeks) is essential: a forgotten stent can become severely encrusted.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/DJ-Harnleiterschiene.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'ErwinMeier, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:DJ-Harnleiterschiene.jpg',
    ),
  ),
  Instrument(
    id: 'nefroscopio',
    isNew: true,
    name: LocalizedText(ca: 'Nefroscopi', es: 'Nefroscopio', en: 'Nephroscope'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.urologia,
    aliases: ['Nephroscope', 'Percutaneous nephroscope'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Endoscopi rígid (o híbrid rígid-flexible), amb beina i canal de treball, dissenyat per introduir-se per un tracte percutani fins al sistema col·lector renal.',
      es: 'Endoscopio rígido (o híbrido rígido-flexible), con vaina y canal de trabajo, diseñado para introducirse por un tracto percutáneo hasta el sistema colector renal.',
      en: 'A rigid (or hybrid rigid-flexible) endoscope with a sheath and working channel, designed to be introduced through a percutaneous tract into the renal collecting system.',
    ),
    use: LocalizedText(
      ca: 'Permet visualitzar directament els calzes i la pelvis renal, i el pas d\'instruments (litotritors, pinces, cistelles) per fragmentar i extreure càlculs durant una nefrolitotomia percutània (NLP).',
      es: 'Permite visualizar directamente los cálices y la pelvis renal, y el paso de instrumentos (litotritores, pinzas, cestas) para fragmentar y extraer cálculos durante una nefrolitotomía percutánea (NLP).',
      en: 'Allows direct visualization of the renal calyces and pelvis and passage of instruments (lithotripters, forceps, baskets) to fragment and extract stones during percutaneous nephrolithotomy (PCNL).',
    ),
  ),
  Instrument(
    id: 'vaina-amplatz',
    isNew: true,
    name: LocalizedText(ca: 'Beina d\'Amplatz (dilatador renal)', es: 'Vaina de Amplatz (dilatador renal)', en: 'Amplatz renal dilator/sheath'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Amplatz sheath', 'Amplatz renal dilator', 'Amplatz access sheath'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Joc de dilatadors plàstics semirígids de calibre creixent més una beina externa radiopaca a joc, que es passen sobre una guia metàl·lica.',
      es: 'Juego de dilatadores plásticos semirrígidos de calibre creciente más una vaina externa radiopaca a juego, que se pasan sobre una guía metálica.',
      en: 'A set of semi-rigid plastic dilators of progressively increasing calibre plus a matching radiopaque outer sheath, advanced over a guidewire.',
    ),
    use: LocalizedText(
      ca: 'Dilata de forma seqüencial el tracte percutani fins al ronyó i, amb la beina, el manté obert perquè el nefroscopi i els instruments puguin entrar i sortir amb seguretat durant la NLP.',
      es: 'Dilata de forma secuencial el tracto percutáneo hasta el riñón y, con la vaina, lo mantiene abierto para que el nefroscopio y los instrumentos puedan entrar y salir con seguridad durante la NLP.',
      en: 'Sequentially dilates the percutaneous tract to the kidney and, with the sheath left in place, keeps it open so the nephroscope and instruments can pass in and out safely during PCNL.',
    ),
  ),
  Instrument(
    id: 'litotriptor-neumatico',
    isNew: true,
    name: LocalizedText(ca: 'Litotritor pneumàtic (balístic) intracorpori', es: 'Litotritor neumático (balístico) intracorpóreo', en: 'Pneumatic (ballistic) intracorporeal lithotripter'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Swiss LithoClast', 'Pneumatic lithotripter', 'Ballistic lithotripsy probe'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Peça de mà accionada per aire comprimit que transmet una sèrie ràpida de polsos mecànics de xoc a través d\'una sonda rígida prima en contacte directe amb el càlcul.',
      es: 'Pieza de mano accionada por aire comprimido que transmite una serie rápida de pulsos mecánicos de choque a través de una sonda rígida fina en contacto directo con el cálculo.',
      en: 'A compressed-air-driven handpiece that transmits a rapid series of mechanical shock pulses through a thin rigid probe held in direct contact with the stone.',
    ),
    use: LocalizedText(
      ca: 'Fragmenta càlculs urinaris (renals, ureterals o vesicals) sota visió endoscòpica directa durant una NLP, ureteroscòpia o cistolitolapaxia; sovint es combina amb una sonda ultrasònica en equips moderns.',
      es: 'Fragmenta cálculos urinarios (renales, ureterales o vesicales) bajo visión endoscópica directa durante una NLP, ureteroscopia o cistolitolapaxia; a menudo se combina con una sonda ultrasónica en equipos modernos.',
      en: 'Fragments urinary stones (renal, ureteral or bladder) under direct endoscopic vision during PCNL, ureteroscopy or cystolitholapaxy; often combined with an ultrasonic probe in modern combination devices.',
    ),
  ),
  Instrument(
    id: 'cesta-litiasis-dormia',
    isNew: true,
    name: LocalizedText(ca: 'Cistella de litiasi (cistella de Dormia)', es: 'Cesta de litiasis (cesta de Dormia)', en: 'Stone retrieval basket (Dormia basket)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Dormia basket', 'Stone retrieval basket', 'Nitinol stone basket'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Dispositiu de fils (habitualment de nitinol) que formen una gàbia helicoidal a l\'extrem d\'una vara llarga, que es pot obrir i tancar al voltant d\'un càlcul.',
      es: 'Dispositivo de hilos (habitualmente de nitinol) que forman una jaula helicoidal en el extremo de una vara larga, que puede abrirse y cerrarse alrededor de un cálculo.',
      en: 'A device of wires (typically nitinol) forming a helical cage at the end of a long shaft, which can be opened and closed around a stone.',
    ),
    use: LocalizedText(
      ca: 'Captura i extreu càlculs o fragments de la via urinària durant una ureteroscòpia rígida o flexible, sota visió directa o control fluoroscòpic.',
      es: 'Captura y extrae cálculos o fragmentos de la vía urinaria durante una ureteroscopia rígida o flexible, bajo visión directa o control fluoroscópico.',
      en: 'Captures and extracts urinary stones or fragments during rigid or flexible ureteroscopy, under direct or fluoroscopic guidance.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Dormiak%C3%B6rbchen.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Doctor roach, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Dormiak%C3%B6rbchen.jpg',
    ),
  ),
  Instrument(
    id: 'vaina-acceso-ureteral',
    isNew: true,
    name: LocalizedText(ca: 'Beina d\'accés ureteral', es: 'Vaina de acceso ureteral', en: 'Ureteral access sheath (UAS)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Ureteral access sheath', 'UAS'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Tub de plàstic amb recobriment hidròfil i resistent a l\'acodament, que es col·loca sobre una guia dins l\'urèter abans de fer passar l\'ureteroscopi flexible pel seu interior.',
      es: 'Tubo de plástico con recubrimiento hidrófilo y resistente al acodamiento, que se coloca sobre una guía dentro del uréter antes de pasar el ureteroscopio flexible por su interior.',
      en: 'A hydrophilic-coated, kink-resistant plastic tube placed over a guidewire into the ureter before the flexible ureteroscope is passed through it.',
    ),
    use: LocalizedText(
      ca: 'Facilita l\'entrada i sortida repetides de l\'ureteroscopi flexible al ronyó durant la cirurgia retrògrada intrarenal (RIRS), protegeix l\'endoscopi i redueix la pressió intrarenal.',
      es: 'Facilita la entrada y salida repetidas del ureteroscopio flexible al riñón durante la cirugía retrógrada intrarrenal (RIRS), protege el endoscopio y reduce la presión intrarrenal.',
      en: 'Facilitates repeated passage of the flexible ureteroscope into the kidney during retrograde intrarenal surgery (RIRS), protects the scope and reduces intrarenal pressure.',
    ),
    tip: LocalizedText(
      ca: 'Redueix la pressió intrarenal i permet treure i reintroduir l\'endoscopi sense perdre l\'accés, útil quan cal extreure múltiples fragments.',
      es: 'Reduce la presión intrarrenal y permite retirar y reintroducir el endoscopio sin perder el acceso, útil cuando hay que extraer múltiples fragmentos.',
      en: 'Lowers intrarenal pressure and allows the scope to be withdrawn and reinserted without losing access, useful when multiple fragments must be removed.',
    ),
  ),
  Instrument(
    id: 'uretrotomo-optico',
    isNew: true,
    name: LocalizedText(ca: 'Uretròtom òptic (de Sachse)', es: 'Uretrótomo óptico (de Sachse)', en: 'Optical urethrotome (Sachse urethrotome)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.urologia,
    aliases: ['Sachse urethrotome', 'Direct-vision internal urethrotome'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Beina rígida amb telescopi òptic incorporat i una fulla freda retràctil que es pot avançar sota visió directa.',
      es: 'Vaina rígida con telescopio óptico incorporado y una cuchilla fría retráctil que puede avanzarse bajo visión directa.',
      en: 'A rigid sheath with a built-in optical telescope and a retractable cold knife that can be advanced under direct vision.',
    ),
    use: LocalizedText(
      ca: 'Secciona una estenosi uretral sota visió directa (uretrotomia interna, DVIU), clàssicament amb un únic tall a les 12 en punt a través del teixit cicatricial.',
      es: 'Secciona una estenosis uretral bajo visión directa (uretrotomía interna, DVIU), clásicamente con un único corte a las 12 en punto a través del tejido cicatricial.',
      en: 'Incises a urethral stricture under direct vision (direct-vision internal urethrotomy, DVIU), classically with a single cut at the 12 o\'clock position through the scar tissue.',
    ),
    tip: LocalizedText(
      ca: 'Les recidives són freqüents, sobretot en estenosis llargues o ja recidivades; en aquests casos sol preferir-se la uretroplàstia abans que repetir la uretrotomia.',
      es: 'Las recidivas son frecuentes, sobre todo en estenosis largas o ya recidivadas; en estos casos suele preferirse la uretroplastia antes que repetir la uretrotomía.',
      en: 'Recurrence is common, especially with long or already-recurrent strictures; urethroplasty is generally preferred over repeat urethrotomy in that situation.',
    ),
  ),
  Instrument(
    id: 'clip-hemolok',
    isNew: true,
    name: LocalizedText(ca: 'Clip de lligadura polimèric (Hem-o-lok)', es: 'Clip de ligadura polimérico (Hem-o-lok)', en: 'Polymer locking ligation clip (Hem-o-lok)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Hem-o-lok clip', 'Weck Hem-o-lok'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Clip no metàl·lic de plàstic amb un mecanisme de bloqueig (tipus trinquet) a la punta que, un cop tancat sobre una estructura, no es pot reobrir; s\'aplica amb unes pinces aplicadores específiques.',
      es: 'Clip no metálico de plástico con un mecanismo de bloqueo (tipo trinquete) en la punta que, una vez cerrado sobre una estructura, no puede reabrirse; se aplica con unas pinzas aplicadoras específicas.',
      en: 'A non-metallic polymer clip with a ratchet-style locking tip that, once closed around a structure, cannot reopen; applied with a dedicated clip applier.',
    ),
    use: LocalizedText(
      ca: 'Lliga de forma segura vasos o estructures tubulars (vena renal, vasos gonadals, etc.) durant cirurgia urològica laparoscòpica o robòtica, com la nefrectomia.',
      es: 'Liga de forma segura vasos o estructuras tubulares (vena renal, vasos gonadales, etc.) durante cirugía urológica laparoscópica o robótica, como la nefrectomía.',
      en: 'Securely ligates vessels or tubular structures (renal vein, gonadal vessels, etc.) during laparoscopic or robotic urologic surgery such as nephrectomy.',
    ),
    tip: LocalizedText(
      ca: 'La FDA en va retirar el 2006 l\'ús aïllat per lligar l\'artèria renal en la nefrectomia laparoscòpica de donant viu, per risc de despreniment i hemorràgia greu; en aquest vas cal transfixió o un altre mètode.',
      es: 'La FDA retiró en 2006 su uso aislado para ligar la arteria renal en la nefrectomía laparoscópica de donante vivo, por riesgo de desprendimiento y hemorragia grave; en ese vaso se requiere transfixión u otro método.',
      en: 'In 2006 the FDA recalled/contraindicated its sole use to ligate the renal artery in laparoscopic living-donor nephrectomy, due to clip-dislodgement risk and severe haemorrhage; transfixion or another method is required for that vessel.',
    ),
  ),
  Instrument(
    id: 'cateter-nefrostomia-percutanea',
    isNew: true,
    name: LocalizedText(ca: 'Catèter de nefrostomia percutània', es: 'Catéter de nefrostomía percutánea', en: 'Percutaneous nephrostomy catheter'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Nephrostomy tube', 'Percutaneous nephrostomy tube', 'Pigtail nephrostomy catheter'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Catèter flexible amb la punta enrotllada en espiral ("pigtail"), que es col·loca a través de la pell i el parènquima renal fins al sistema col·lector i es connecta a una bossa de drenatge externa.',
      es: 'Catéter flexible con la punta enrollada en espiral ("pigtail"), que se coloca a través de la piel y el parénquima renal hasta el sistema colector y se conecta a una bolsa de drenaje externa.',
      en: 'A flexible catheter with a pigtail-curled tip, placed through the skin and renal parenchyma into the collecting system and connected to an external drainage bag.',
    ),
    use: LocalizedText(
      ca: 'Desvia l\'orina d\'un ronyó obstruït o infectat (litiasi, tumor, estenosi) quan el drenatge retrògrad no és possible, i dona accés percutani per a procediments endourològics posteriors.',
      es: 'Deriva la orina de un riñón obstruido o infectado (litiasis, tumor, estenosis) cuando el drenaje retrógrado no es posible, y da acceso percutáneo para procedimientos endourológicos posteriores.',
      en: 'Diverts urine from an obstructed or infected kidney (stones, tumour, stricture) when retrograde drainage is not possible, and provides percutaneous access for later endourologic procedures.',
    ),
  ),
  Instrument(
    id: 'pistola-biopsia-prostatica',
    isNew: true,
    name: LocalizedText(ca: 'Pistola de biòpsia prostàtica', es: 'Pistola de biopsia prostática', en: 'Prostate (core-needle) biopsy gun'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.urologia,
    aliases: ['Biopty gun', 'Core biopsy gun', 'Automatic biopsy device'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Dispositiu manual amb un mecanisme de molla que dispara una agulla (habitualment de calibre 18G) per tallar un cilindre prim de teixit en una fracció de segon.',
      es: 'Dispositivo manual con un mecanismo de resorte que dispara una aguja (habitualmente de calibre 18G) para cortar un cilindro fino de tejido en una fracción de segundo.',
      en: 'A handheld spring-loaded device that fires a needle (typically 18-gauge) forward to shear off a thin cylindrical core of tissue in a fraction of a second.',
    ),
    use: LocalizedText(
      ca: 'Obté múltiples cilindres de teixit prostàtic sota control ecogràfic transrectal o transperineal per al diagnòstic histològic del càncer de pròstata.',
      es: 'Obtiene múltiples cilindros de tejido prostático bajo control ecográfico transrectal o transperineal para el diagnóstico histológico del cáncer de próstata.',
      en: 'Obtains multiple prostate tissue cores under transrectal or transperineal ultrasound guidance for the histological diagnosis of prostate cancer.',
    ),
    tip: LocalizedText(
      ca: 'En l\'abordatge transrectal cal profilaxi antibiòtica periprocediment pel risc d\'infecció; la via transperineal redueix aquest risc.',
      es: 'En el abordaje transrectal es necesaria profilaxis antibiótica periprocedimiento por el riesgo de infección; la vía transperineal reduce este riesgo.',
      en: 'The transrectal approach requires periprocedural antibiotic prophylaxis because of infection risk; the transperineal route lowers this risk.',
    ),
  ),
  Instrument(
    id: 'evacuador-ellik',
    isNew: true,
    name: LocalizedText(ca: 'Evacuador d\'Ellik', es: 'Evacuador de Ellik', en: 'Ellik evacuator'),
    category: InstrumentCategory.succion,
    specialty: Specialty.urologia,
    aliases: ['Ellik bladder evacuator', 'Ellik evacuator'],
    icon: 'suction',
    description: LocalizedText(
      ca: 'Xeringa-pera de doble cambra en forma de rellotge de sorra (vidre o plàstic), amb una pera de goma, que es connecta a la beina del resectoscopi.',
      es: 'Jeringa-pera de doble cámara en forma de reloj de arena (vidrio o plástico), con una pera de goma, que se conecta a la vaina del resectoscopio.',
      en: 'A double-chamber, hourglass-shaped bulb syringe (glass or plastic) with a rubber bulb, connected to the resectoscope sheath.',
    ),
    use: LocalizedText(
      ca: 'Evacua de la bufeta els fragments de pròstata o de tumor vesical, coàguls i restes, en acabar una RTU de pròstata o de tumor vesical.',
      es: 'Evacúa de la vejiga los fragmentos de próstata o de tumor vesical, coágulos y restos, al finalizar una RTU de próstata o de tumor vesical.',
      en: 'Evacuates resected prostate or bladder-tumour chips, clots and debris from the bladder at the end of a TURP or transurethral bladder tumour resection.',
    ),
    tip: LocalizedText(
      ca: 'Els fragments se sedimenten per gravetat: els trossos petits o poc densos poden quedar surant i no recollir-se, per això cal revisar bé abans de donar la bufeta per buida.',
      es: 'Los fragmentos se sedimentan por gravedad: los trozos pequeños o poco densos pueden quedar flotando y no recogerse, por lo que hay que revisar bien antes de dar la vejiga por vacía.',
      en: 'Fragments settle by gravity, so small or low-density chips can stay afloat and go uncollected, check carefully before assuming the bladder is empty.',
    ),
  ),
  Instrument(
    id: 'pinza-biopsia-fria',
    isNew: true,
    name: LocalizedText(ca: 'Pinça de biòpsia en fred', es: 'Pinza de biopsia en frío', en: 'Cold-cup biopsy forceps'),
    category: InstrumentCategory.diseccion,
    specialty: Specialty.urologia,
    aliases: ['Cold-cup biopsy forceps', 'Cold-cup forceps', 'Piranha forceps'],
    icon: 'pinch',
    description: LocalizedText(
      ca: 'Pinça llarga i prima, rígida o flexible, amb unes petites mandíbules en forma de cullereta a la punta, que es passa pel canal de treball d\'un cistoscopi o ureteroscopi.',
      es: 'Pinza larga y fina, rígida o flexible, con unas pequeñas mandíbulas en forma de cucharilla en la punta, que se pasa por el canal de trabajo de un cistoscopio o ureteroscopio.',
      en: 'A long, thin rigid or flexible forceps with small cup-shaped jaws at the tip, passed through the working channel of a cystoscope or ureteroscope.',
    ),
    use: LocalizedText(
      ca: 'Pren mostres petites de l\'uroteli vesical o de la via urinària superior de manera mecànica (sense energia) per al diagnòstic histològic de lesions o tumors sospitosos.',
      es: 'Toma muestras pequeñas del urotelio vesical o de la vía urinaria superior de manera mecánica (sin energía) para el diagnóstico histológico de lesiones o tumores sospechosos.',
      en: 'Takes small samples of bladder or upper urinary tract urothelium mechanically (without energy) for the histological diagnosis of suspected lesions or tumours.',
    ),
    tip: LocalizedText(
      ca: 'En no utilitzar energia, evita l\'artefacte tèrmic de la mostra i permet valorar millor la infiltració del múscul detrusor que una biòpsia per resecció.',
      es: 'Al no utilizar energía, evita el artefacto térmico de la muestra y permite valorar mejor la infiltración del músculo detrusor que una biopsia por resección.',
      en: 'Because it uses no energy, it avoids thermal artefact in the specimen and allows better assessment of detrusor muscle invasion than a resection biopsy.',
    ),
  ),

