      ca: 'S\'utilitza per mantenir la via aèria permeable després d\'una traqueotomia, en pacients amb necessitat de ventilació mecànica perllongada o obstrucció de la via aèria superior.',
      es: 'Se utiliza para mantener la vía aérea permeable tras una traqueotomía, en pacientes con necesidad de ventilación mecánica prolongada u obstrucción de la vía aérea superior.',
      en: 'Used to maintain a patent airway after tracheostomy, in patients requiring prolonged mechanical ventilation or with upper airway obstruction.',
    ),
    tip: LocalizedText(
      ca: 'Els tubs fenestrats permeten la fonació i faciliten el deslletament, mentre que els no fenestrats es prefereixen quan hi ha risc d\'aspiració.',
      es: 'Los tubos fenestrados permiten la fonación y facilitan el destete, mientras que los no fenestrados se prefieren cuando existe riesgo de aspiración.',
      en: 'Fenestrated tubes allow phonation and facilitate weaning, while non-fenestrated tubes are preferred when there is aspiration risk.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/f/f6/Tracheostomy_tube.jpg',
      license: 'CC BY 3.0 DE',
      attribution: 'Klaus D. Peter, Wiehl, Germany, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Tracheostomy_tube.jpg',
    ),
  ),
  Instrument(
    id: 'tubo-timpanostomia',
    name: LocalizedText(ca: 'Tub de timpanostomia (drenatge transtimpànic)', es: 'Tubo de timpanostomía (drenaje transtimpánico)', en: 'Tympanostomy tube (ear tube)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.otorrino,
    aliases: ['Grommet', 'Ventilation tube', 'Tubo de ventilación'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Petit tub cilíndric, de plàstic o titani, amb una brida a cada extrem, dissenyat per inserir-se a través d\'una incisió a la membrana timpànica.',
      es: 'Pequeño tubo cilíndrico, de plástico o titanio, con una brida en cada extremo, diseñado para insertarse a través de una incisión en la membrana timpánica.',
      en: 'A small cylindrical tube, made of plastic or titanium, with a flange at each end, designed to be inserted through an incision in the tympanic membrane.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza després d\'una miringotomia per mantenir ventilat l\'oïda mitjana en l\'otitis mitjana serosa recurrent, evitant l\'acumulació de líquid darrere del timpà.',
      es: 'Se utiliza tras una miringotomía para mantener ventilado el oído medio en la otitis media serosa recurrente, evitando la acumulación de líquido detrás del tímpano.',
      en: 'Used after myringotomy to keep the middle ear ventilated in recurrent serous otitis media, preventing fluid buildup behind the eardrum.',
    ),
    tip: LocalizedText(
      ca: 'La majoria es desprenen de manera espontània al cap de 6-18 mesos conforme el timpà es regenera, sense necessitat d\'extracció quirúrgica.',
      es: 'La mayoría se desprenden de forma espontánea al cabo de 6-18 meses conforme el tímpano se regenera, sin necesidad de extracción quirúrgica.',
      en: 'Most extrude spontaneously within 6-18 months as the eardrum regenerates, without requiring surgical removal.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/7/78/Tympanostomy_tube.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Krokofant, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Tympanostomy_tube.jpg',
    ),
  ),
  Instrument(
    id: 'espejo-laringeo',
    name: LocalizedText(ca: 'Mirall laringi', es: 'Espejo laríngeo', en: 'Laryngeal mirror'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.otorrino,
    aliases: ['Laryngoscopy mirror', 'Espejo de garganta'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Petit mirall rodó, amb angle ajustable, muntat en un mànec llarg i prim, que s\'escalfa lleugerament abans d\'usar-lo per evitar l\'entelament.',
      es: 'Pequeño espejo redondo, con ángulo ajustable, montado en un mango largo y fino, que se calienta ligeramente antes de usarlo para evitar el empañamiento.',
      en: 'A small round mirror with an adjustable angle, mounted on a long thin handle, lightly warmed before use to prevent fogging.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per a la laringoscòpia indirecta, permetent visualitzar la base de la llengua, l\'epiglotis i les cordes vocals en l\'exploració clàssica ambulatòria.',
      es: 'Se utiliza para la laringoscopia indirecta, permitiendo visualizar la base de la lengua, la epiglotis y las cuerdas vocales en la exploración clásica ambulatoria.',
      en: 'Used for indirect laryngoscopy, allowing visualization of the tongue base, epiglottis, and vocal cords in classic office-based examination.',
    ),
    tip: LocalizedText(
      ca: 'Encara que els sistemes de fibra òptica l\'han substituït en gran part, continua sent útil com a eina ràpida i econòmica de cribratge.',
      es: 'Aunque los sistemas de fibra óptica lo han sustituido en gran parte, sigue siendo útil como herramienta rápida y económica de cribado.',
      en: 'Although fiberoptic systems have largely replaced it, it remains useful as a quick, inexpensive screening tool.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/4/47/Laryngeal_Mirror_ENT_Instrument_Medical.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Sarindam7, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Laryngeal_Mirror_ENT_Instrument_Medical.jpg',
    ),
  ),
  Instrument(
    id: 'mordaza-boyle-davis',
    name: LocalizedText(ca: 'Mordassa de Boyle-Davis', es: 'Mordaza de Boyle-Davis', en: 'Boyle-Davis mouth gag'),
    category: InstrumentCategory.separacion,
    specialty: Specialty.otorrino,
    aliases: ['Boyle-Davis gag', 'Tonsillectomy mouth gag'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador bucal autoestàtic amb una fulla central per deprimir la llengua i dues valves laterals ajustables que exposen l\'orofaringe.',
      es: 'Separador bucal autoestático con una hoja central para deprimir la lengua y dos valvas laterales ajustables que exponen la orofaringe.',
      en: 'A self-retaining mouth gag with a central tongue-depressor blade and two adjustable lateral blades that expose the oropharynx.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en l\'amigdalectomia i l\'adenoidectomia per mantenir la boca oberta i la llengua deprimida, exposant les amígdales i la rinofaringe.',
      es: 'Se utiliza en la amigdalectomía y la adenoidectomía para mantener la boca abierta y la lengua deprimida, exponiendo las amígdalas y la rinofaringe.',
      en: 'Used in tonsillectomy and adenoidectomy to hold the mouth open and the tongue depressed, exposing the tonsils and nasopharynx.',
    ),
    tip: LocalizedText(
      ca: 'La mida de la fulla s\'ha d\'ajustar a l\'edat del pacient, ja que una pressió excessiva i perllongada pot provocar macroglòssia postoperatòria transitòria.',
      es: 'El tamaño de la hoja debe ajustarse a la edad del paciente, ya que una presión excesiva y prolongada puede provocar macroglosia postoperatoria transitoria.',
      en: 'Blade size should be matched to patient age, since excessive or prolonged pressure can cause transient postoperative macroglossia.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/f/f9/Boyle_Davis_Mouth_Gag.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Netha Hussain, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Boyle_Davis_Mouth_Gag.jpg',
    ),
  ),
  Instrument(
    id: 'miringotomo',
    name: LocalizedText(ca: 'Miringòtom', es: 'Miringótomo', en: 'Myringotomy knife'),
    category: InstrumentCategory.corte,
    specialty: Specialty.otorrino,
    aliases: ['Myringotomy blade', 'Cuchillete de miringotomía'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Fulla molt petita i afilada, recta o angulada, muntada en un mànec fi, dissenyada per practicar una incisió controlada i precisa a la membrana timpànica.',
      es: 'Hoja muy pequeña y afilada, recta o angulada, montada en un mango fino, diseñada para practicar una incisión controlada y precisa en la membrana timpánica.',
      en: 'A very small, sharp blade, straight or angled, mounted on a fine handle, designed to make a controlled, precise incision in the tympanic membrane.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per practicar la miringotomia, una incisió al timpà per drenar líquid de l\'oïda mitjana i, sovint, inserir-hi posteriorment un tub de ventilació.',
      es: 'Se utiliza para practicar la miringotomía, una incisión en el tímpano para drenar líquido del oído medio y, a menudo, insertar posteriormente un tubo de ventilación.',
      en: 'Used to perform myringotomy, an incision in the eardrum to drain middle ear fluid and, often, subsequently insert a ventilation tube.',
    ),
    tip: LocalizedText(
      ca: 'La incisió es practica habitualment al quadrant anteroinferior del timpà per evitar lesionar la cadena ossicular posterior.',
      es: 'La incisión se practica habitualmente en el cuadrante anteroinferior del tímpano para evitar lesionar la cadena osicular posterior.',
      en: 'The incision is typically made in the anteroinferior quadrant of the eardrum to avoid injuring the posterior ossicular chain.',
    ),
    isNew: true,
  ),

