    aliases: ['Vessel loop', 'Vascular tape', 'Cinta vascular'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Cinta estreta, elàstica i de silicona, de colors diferenciats, que s\'utilitza per envoltar i identificar estructures vasculars o nervioses.',
      es: 'Cinta estrecha, elástica y de silicona, de colores diferenciados, que se utiliza para rodear e identificar estructuras vasculares o nerviosas.',
      en: 'A narrow, elastic silicone tape, available in distinct colors, used to encircle and identify vascular or neural structures.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per aïllar i controlar temporalment vasos sanguinis o nervis durant la dissecció, permetent-ne la tracció i identificació sense pinçar-los.',
      es: 'Se utiliza para aislar y controlar temporalmente vasos sanguíneos o nervios durante la disección, permitiendo su tracción e identificación sin pinzarlos.',
      en: 'Used to isolate and temporarily control blood vessels or nerves during dissection, allowing traction and identification without clamping them.',
    ),
    tip: LocalizedText(
      ca: 'El codi de colors (vermell per a artèries, blau per a venes, groc per a nervis) ajuda a mantenir l\'orientació anatòmica durant la dissecció.',
      es: 'El código de colores (rojo para arterias, azul para venas, amarillo para nervios) ayuda a mantener la orientación anatómica durante la disección.',
      en: 'The color code (red for arteries, blue for veins, yellow for nerves) helps maintain anatomical orientation during dissection.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'dilatador-vascular',
    name: LocalizedText(ca: 'Dilatador vascular', es: 'Dilatador vascular', en: 'Vascular dilator'),
