      es: 'Instrumento metálico cónico y curvado, de diferentes calibres, diseñado para introducirse dentro de la luz de un vaso y dilatar progresivamente su estenosis.',
      en: 'A conical, curved metal instrument, available in several calibers, designed to be introduced into a vessel lumen and progressively dilate a stenosis.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en cirurgia vascular per dilatar vasos estenosats o espasmòtics abans d\'una anastomosi, i per comprovar-ne la permeabilitat de la llum.',
      es: 'Se utiliza en cirugía vascular para dilatar vasos estenosados o espasmódicos antes de una anastomosis, y para comprobar la permeabilidad de la luz.',
      en: 'Used in vascular surgery to dilate stenotic or spastic vessels before an anastomosis, and to check lumen patency.',
    ),
    tip: LocalizedText(
      ca: 'S\'ha d\'introduir progressivament amb calibres creixents, sense forçar mai el pas per evitar una dissecció iatrogènica de la paret vascular.',
      es: 'Debe introducirse progresivamente con calibres crecientes, sin forzar nunca el paso para evitar una disección iatrogénica de la pared vascular.',
      en: 'It should be introduced progressively with increasing calibers, never forcing passage, to avoid iatrogenic dissection of the vessel wall.',
    ),
    isNew: true,
  ),
