    description: LocalizedText(
      ca: 'Filferro prim, flexible i de punta tova (recta, en J o hidrofílica), dissenyat per avançar dins del sistema vascular i servir de guia a catèters.',
      es: 'Alambre fino, flexible y de punta blanda (recta, en J o hidrofílica), diseñado para avanzar dentro del sistema vascular y servir de guía a catéteres.',
      en: 'A thin, flexible wire with a soft tip (straight, J-shaped, or hydrophilic), designed to advance within the vascular system and guide catheters.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en procediments endovasculars per navegar a través del sistema vascular i guiar la introducció segura de catèters i altres dispositius fins a la zona diana.',
      es: 'Se utiliza en procedimientos endovasculares para navegar a través del sistema vascular y guiar la introducción segura de catéteres y otros dispositivos hasta la zona diana.',
      en: 'Used in endovascular procedures to navigate through the vascular system and safely guide catheters and other devices to the target area.',
    ),
    tip: LocalizedText(
      ca: 'Sempre s\'ha d\'avançar sota control fluoroscòpic i mai forçar-la si es troba resistència, per evitar una perforació o dissecció vascular.',
      es: 'Siempre debe avanzarse bajo control fluoroscópico y nunca forzarla si se encuentra resistencia, para evitar una perforación o disección vascular.',
      en: 'It should always be advanced under fluoroscopic control and never forced against resistance, to avoid vascular perforation or dissection.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/4/40/PTFE_guide_wire.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Maryam seyfikar, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:PTFE_guide_wire.jpg',
    ),
  ),
  Instrument(
    id: 'cateter-balon-angioplastia',
    name: LocalizedText(ca: 'Catèter de baló d\'angioplàstia', es: 'Catéter de balón de angioplastia', en: 'Angioplasty balloon catheter'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.vascular,
    aliases: ['Balloon catheter', 'PTA balloon'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Catèter llarg i flexible amb un baló inflable d\'un diàmetre i longitud específics muntat a la punta, connectat a un dispositiu d\'inflat a pressió controlada.',
      es: 'Catéter largo y flexible con un balón inflable de un diámetro y longitud específicos montado en la punta, conectado a un dispositivo de inflado a presión controlada.',
      en: 'A long, flexible catheter with an inflatable balloon of specific diameter and length mounted at the tip, connected to a pressure-controlled inflation device.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en l\'angioplàstia transluminal percutània per dilatar estenosis arterials o venoses, i per desplegar stents en el mateix procediment.',
      es: 'Se utiliza en la angioplastia transluminal percutánea para dilatar estenosis arteriales o venosas, y para desplegar stents en el mismo procedimiento.',
      en: 'Used in percutaneous transluminal angioplasty to dilate arterial or venous stenoses, and to deploy stents in the same procedure.',
    ),
    tip: LocalizedText(
      ca: 'La pressió d\'inflat s\'ha de controlar amb un manòmetre específic (indeflator) per no superar la pressió nominal de ruptura del baló.',
      es: 'La presión de inflado debe controlarse con un manómetro específico (indeflator) para no superar la presión nominal de rotura del balón.',
      en: 'Inflation pressure must be monitored with a dedicated gauge (indeflator) to avoid exceeding the balloon\'s rated burst pressure.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'stent-vascular',
    name: LocalizedText(ca: 'Stent vascular', es: 'Stent vascular', en: 'Vascular stent'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.vascular,
    aliases: ['Endovascular stent', 'Malla vascular'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Dispositiu tubular de malla metàl·lica, expandible per baló o autoexpandible, dissenyat per implantar-se de manera permanent dins d\'un vas per mantenir-ne la llum oberta.',
      es: 'Dispositivo tubular de malla metálica, expandible por balón o autoexpandible, diseñado para implantarse de manera permanente dentro de un vaso para mantener su luz abierta.',
      en: 'A tubular metal-mesh device, either balloon-expandable or self-expanding, designed for permanent implantation within a vessel to keep its lumen open.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per tractar estenosis arterials significatives després de l\'angioplàstia, proporcionant suport estructural que en prevé el reestrenyiment (reestenosi).',
      es: 'Se utiliza para tratar estenosis arteriales significativas tras la angioplastia, proporcionando soporte estructural que previene el reestrechamiento (reestenosis).',
      en: 'Used to treat significant arterial stenoses after angioplasty, providing structural support that prevents re-narrowing (restenosis).',
    ),
    tip: LocalizedText(
      ca: 'L\'elecció entre un stent expandible per baló o autoexpandible depèn de la localització anatòmica i de les forces mecàniques externes previstes sobre el vas.',
      es: 'La elección entre un stent expandible por balón o autoexpandible depende de la localización anatómica y de las fuerzas mecánicas externas previstas sobre el vaso.',
      en: 'The choice between a balloon-expandable or self-expanding stent depends on the anatomical location and the expected external mechanical forces on the vessel.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/84/Endovascular_stent.jpg',
      license: 'Public Domain',
      attribution: 'National Institutes of Health',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Endovascular_stent.jpg',
    ),
    isNew: true,
  ),
  Instrument(
