      es: 'Se utiliza en la reparación endovascular de aneurismas aórticos (EVAR/TEVAR), excluyendo el saco aneurismático de la circulación sin necesidad de cirugía abierta.',
      en: 'Used in endovascular aortic aneurysm repair (EVAR/TEVAR), excluding the aneurysm sac from circulation without the need for open surgery.',
