      es: 'El dimensionamiento preciso (tamaño y longitud) a partir de una angio-TC previa es crítico para lograr un sellado proximal y distal adecuado.',
      en: 'Precise sizing (diameter and length) from prior CT angiography is critical to achieve adequate proximal and distal sealing.',
