      es: 'Instrumento largo y flexible, con una cabeza olivar o acoplador en el extremo, diseñado para introducirse dentro de la luz de la vena safena y extraerla por tracción.',
      en: 'A long, flexible instrument with an olive-shaped head or acorn tip, designed to be threaded through the lumen of the saphenous vein and extract it by traction.',
    ),
    use: LocalizedText(
