      es: 'Se utiliza en la safenectomía clásica (stripping) para la cirugía de las varices, extrayendo todo el tronco safeno insuficiente a través de una pequeña incisión.',
      en: 'Used in classic saphenous vein stripping for varicose vein surgery, removing the entire incompetent saphenous trunk through a small incision.',
    ),
    tip: LocalizedText(
      ca: 'Les tècniques endovasculars tèrmiques i químiques han anat substituint progressivament l\'stripping clàssic en molts centres per la seva menor morbiditat.',
      es: 'Las técnicas endovasculares térmicas y químicas han ido sustituyendo progresivamente al stripping clásico en muchos centros por su menor morbilidad.',
      en: 'Thermal and chemical endovenous techniques have progressively replaced classic stripping in many centers due to lower morbidity.',
    ),
    isNew: true,
  ),
  Instrument(
