      ca: 'S\'ha de mantenir sempre en un pla anatòmic conegut (subfascial o subcutani) per evitar lesionar estructures neurovasculars adjacents.',
      es: 'Debe mantenerse siempre en un plano anatómico conocido (subfascial o subcutáneo) para evitar lesionar estructuras neurovasculares adyacentes.',
      en: 'It should always be kept within a known anatomical plane (subfascial or subcutaneous) to avoid injuring adjacent neurovascular structures.',
    ),
    isNew: true,
  ),
  Instrument(
