      es: 'Instrumento de mango en anilla con puntas bulbosas, serradas y anguladas, diseñado para separar suavemente las fibras musculares seccionadas del píloro durante una piloromiotomía.',
      en: 'A ring-handled instrument with angled, serrated, bulb-shaped tips designed to gently spread the incised muscle fibers of the pylorus during pyloromyotomy.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per completar la piloromiotomia de Ramstedt-Fredet en l\'estenosi pilòrica hipertròfica infantil, separant les dues meitats del múscul seccionat fins a exposar la submucosa intacta.',
      es: 'Se utiliza para completar la piloromiotomía de Ramstedt-Fredet en la estenosis pilórica hipertrófica infantil, separando las dos mitades del músculo seccionado hasta exponer la submucosa intacta.',
      en: 'Used to complete the Ramstedt-Fredet pyloromyotomy for infantile hypertrophic pyloric stenosis, spreading the two halves of the incised muscle until the intact submucosa bulges freely.',
    ),
    tip: LocalizedText(
