      es: 'Hay que comprobar que las dos mitades del músculo se mueven de forma independiente antes de terminar, para descartar una perforación de la mucosa no detectada.',
      en: 'Surgeons confirm the two muscle halves move independently before finishing, to rule out an undetected mucosal perforation.',
    ),
    isNew: true,
  ),
