    description: LocalizedText(
      ca: 'Dispositiu metàl·lic desmuntable format per una campana que protegeix el gland i una placa amb un mecanisme de cargol que comprimeix el prepuci entre totes dues peces.',
      es: 'Dispositivo metálico desmontable formado por una campana que protege el glande y una placa con un mecanismo de tornillo que comprime el prepucio entre ambas piezas.',
