      es: 'Hay que inspeccionar el montaje antes de cada uso para asegurar que la placa queda plana sobre la campana y que no hay luz entre ambas piezas, ya que un tamaño inadecuado es la causa más frecuente de complicaciones.',
      en: 'The assembled clamp should be inspected before each use to ensure the plate sits flat against the bell with no visible gap, since improper sizing is the most common cause of complications.',
    ),
