      es: 'Se utiliza en la rinoplastia para alisar y refinar irregularidades óseas del dorso nasal tras la osteotomía, logrando un contorno suave.',
      en: 'Used in rhinoplasty to smooth and refine bony irregularities of the nasal dorsum after osteotomy, achieving a smooth contour.',
    ),
    tip: LocalizedText(
      ca: 'S\'utilitza amb un moviment unidireccional per evitar aspror a la superfície òssia i minimitzar el risc de formació de callus irregular.',
      es: 'Se utiliza con un movimiento unidireccional para evitar aspereza en la superficie ósea y minimizar el riesgo de formación de callo irregular.',
      en: 'It is used with a unidirectional motion to avoid roughening the bony surface and minimize the risk of irregular callus formation.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'tijera-joseph',
