  Instrument(
    id: 'mallador-injertos-cutaneos',
    name: LocalizedText(ca: 'Mallador d\'empelts cutanis', es: 'Mallador de injertos cutáneos', en: 'Skin graft mesher'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.plastica,
    aliases: ['Mesh dermatome', 'Mesher de piel'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu mecànic amb un rodet tallant que perfora l\'empelt cutani en un patró uniforme de petites incisions entrecreuades.',
      es: 'Dispositivo mecánico con un rodillo cortante que perfora el injerto cutáneo en un patrón uniforme de pequeñas incisiones entrecruzadas.',
      en: 'A mechanical device with a cutting roller that perforates the skin graft in a uniform pattern of small crisscrossed incisions.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per expandir l\'àrea d\'un empelt cutani de gruix parcial (un patró habitual de 1:1,5 o 1:3), permetent cobrir defectes més grans amb menys pell donant.',
      es: 'Se utiliza para expandir el área de un injerto cutáneo de grosor parcial (un patrón habitual de 1:1,5 o 1:3), permitiendo cubrir defectos más grandes con menos piel donante.',
      en: 'Used to expand the surface area of a split-thickness skin graft (typical ratios of 1:1.5 or 1:3), covering larger defects with less donor skin.',
    ),
    tip: LocalizedText(
      ca: 'La malla resultant també permet el drenatge de l\'exsudat i la sang acumulats sota l\'empelt, millorant-ne la presa.',
      es: 'La malla resultante también permite el drenaje del exudado y la sangre acumulados bajo el injerto, mejorando su prendimiento.',
      en: 'The resulting mesh pattern also allows drainage of exudate and blood accumulated under the graft, improving graft take.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'clamp-microvascular-acland',
    name: LocalizedText(ca: 'Clamp microvascular d\'Acland', es: 'Clamp microvascular de Acland', en: 'Acland microvascular clamp'),
    category: InstrumentCategory.diseccion,
    specialty: Specialty.plastica,
    aliases: ['Acland clamp', 'Microclamp vascular'],
    icon: 'pinch',
    description: LocalizedText(
