      es: 'Clamp miniaturizado, de presión muy baja y constante, diseñado para ocluir temporalmente vasos de calibre submilimétrico sin lesionar su endotelio.',
      en: 'A miniaturized clamp with very low, constant closing pressure, designed to temporarily occlude sub-millimeter vessels without damaging the endothelium.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en microcirurgia reconstructiva i trasplantament de colgalls lliures per ocluir temporalment artèries i venes molt fines durant l\'anastomosi microvascular.',
      es: 'Se utiliza en microcirugía reconstructiva y trasplante de colgajos libres para ocluir temporalmente arterias y venas muy finas durante la anastomosis microvascular.',
