      ca: 'La seva pressió de tancament calibrada evita l\'espasme i la lesió endotelial que provocarien els clamps vasculars convencionals en vasos tan fins.',
      es: 'Su presión de cierre calibrada evita el espasmo y la lesión endotelial que provocarían los clamps vasculares convencionales en vasos tan finos.',
      en: 'Its calibrated closing pressure avoids the spasm and endothelial injury that conventional vascular clamps would cause on such fine vessels.',
    ),
    isNew: true,
  ),
  Instrument(
