      es: 'Permite valorar la simetría y el resultado estético antes de abrir el envase estéril del implante definitivo, evitando un desperdicio innecesario.',
      en: 'Allows assessment of symmetry and aesthetic outcome before opening the sterile package of the definitive implant, avoiding unnecessary waste.',
    ),
    isNew: true,
  ),
  Instrument(
