      es: 'La inyección debe hacerse en pequeños volúmenes y en múltiples planos y pasadas para maximizar la vascularización y la supervivencia del injerto graso.',
      en: 'Injection should be done in small volumes across multiple planes and passes to maximize vascularization and survival of the fat graft.',
    ),
