      es: 'Dispositivo de un solo uso, en forma de cono cómico, de material deslizante, diseñado para introducir el implante mamario a través de una incisión reducida sin que la prótesis entre en contacto con la piel.',
      en: 'A single-use, cone-shaped device made of slippery material, designed to introduce the breast implant through a reduced incision without the prosthesis contacting the skin.',
    ),
    use: LocalizedText(
