      es: 'Se utiliza en el aumento mamario para aplicar la técnica de inserción sin contacto (\'no-touch\'), reduciendo el riesgo de contaminación bacteriana y de contractura capsular.',
      en: 'Used in breast augmentation to apply the \'no-touch\' insertion technique, reducing the risk of bacterial contamination and capsular contracture.',
    ),
    tip: LocalizedText(
      ca: 'També permet inserir l\'implant a través d\'incisions més curtes que les que requeriria la inserció manual directa.',
      es: 'También permite insertar el implante a través de incisiones más cortas que las que requeriría la inserción manual directa.',
      en: 'It also allows the implant to be inserted through shorter incisions than direct manual insertion would require.',
    ),
    isNew: true,
  ),

