      es: 'Se utiliza para realizar biopsias por afeitado de lesiones cutáneas elevadas, seccionando un corte horizontal fino de la capa superior de la piel para su estudio histológico.',
      en: 'Used to perform shave biopsies of raised skin lesions, taking a thin horizontal slice of the superficial skin layer for histologic examination.',
    ),
    tip: LocalizedText(
      ca: 'Corbant la fulla en forma de U es controla millor la profunditat del tall, obtenint una mostra uniforme sense penetrar en la dermis profunda.',
      es: 'Curvando la hoja en forma de U se controla mejor la profundidad del corte, obteniendo una muestra uniforme sin penetrar en la dermis profunda.',
      en: 'Bowing the blade into a U-shape gives better control of cutting depth, yielding a uniform sample without penetrating the deep dermis.',
