  Instrument(
    id: 'laser-yag-oftalmico',
    name: LocalizedText(ca: 'Làser YAG oftàlmic', es: 'Láser YAG oftálmico', en: 'Ophthalmic YAG laser'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.oftalmologia,
    aliases: ['Nd:YAG laser', 'Láser de capsulotomía'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Sistema làser de polsos curts acoblat a una lampada de fenedura, que focalitza energia en un punt molt precís per produir una microdisrupció tissular.',
      es: 'Sistema láser de pulsos cortos acoplado a una lámpara de hendidura, que focaliza energía en un punto muy preciso para producir una microdisrupción tisular.',
      en: 'A short-pulse laser system coupled to a slit lamp, focusing energy at a very precise point to produce tissue microdisruption.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza principalment per practicar la capsulotomia posterior en l\'opacificació de la càpsula posterior (catarata secundària) després de la cirurgia de cataractes.',
      es: 'Se utiliza principalmente para practicar la capsulotomía posterior en la opacificación de la cápsula posterior (catarata secundaria) tras la cirugía de cataratas.',
      en: 'Used primarily to perform posterior capsulotomy for posterior capsule opacification (secondary cataract) after cataract surgery.',
    ),
    tip: LocalizedText(
      ca: 'És un procediment ambulatori, no invasiu, que no requereix incisió ja que l\'energia s\'aplica a través de la còrnia transparent.',
      es: 'Es un procedimiento ambulatorio, no invasivo, que no requiere incisión ya que la energía se aplica a través de la córnea transparente.',
      en: 'It is a noninvasive outpatient procedure that requires no incision, as the energy is delivered through the clear cornea.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'laser-argon-retina',
    name: LocalizedText(ca: 'Làser d\'argó per a retina', es: 'Láser de argón para retina', en: 'Argon retinal laser'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.oftalmologia,
    aliases: ['Argon laser photocoagulator', 'Fotocoagulador de argón'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Sistema làser de longitud d\'ona visible, acoblat a una lampada de fenedura o a un làser indirecte, que produeix cremades tèrmiques controlades a la retina.',
      es: 'Sistema láser de longitud de onda visible, acoplado a una lámpara de hendidura o a un láser indirecto, que produce quemaduras térmicas controladas en la retina.',
      en: 'A visible-wavelength laser system, coupled to a slit lamp or an indirect laser delivery system, producing controlled thermal burns on the retina.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en la panfotocoagulació retiniana per tractar la retinopatia diabètica proliferativa i per segellar estrips o forats retinians.',
      es: 'Se utiliza en la panfotocoagulación retiniana para tratar la retinopatía diabética proliferativa y para sellar desgarros o agujeros retinianos.',
      en: 'Used in panretinal photocoagulation to treat proliferative diabetic retinopathy and to seal retinal tears or holes.',
    ),
    tip: LocalizedText(
      ca: 'La potència i la durada del polsos s\'ajusten fins a obtenir una cremada blanquinosa de to moderat, evitant lesions excessivament intenses.',
      es: 'La potencia y la duración de los pulsos se ajustan hasta obtener una quemadura blanquecina de tono moderado, evitando lesiones excesivamente intensas.',
      en: 'Power and pulse duration are titrated to produce a moderate whitish burn, avoiding excessively intense lesions.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'sonda-criopexia-retinal',
    name: LocalizedText(ca: 'Sonda de criopèxia retinal', es: 'Sonda de criopexia retinal', en: 'Retinal cryopexy probe'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.oftalmologia,
    aliases: ['Cryoprobe', 'Criosonda oftálmica'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Sonda metàl·lica connectada a una unitat de refrigeració (CO2 o òxid nitrós), amb una punta que assoleix temperatures molt baixes de manera controlada.',
      es: 'Sonda metálica conectada a una unidad de refrigeración (CO2 u óxido nitroso), con una punta que alcanza temperaturas muy bajas de forma controlada.',
      en: 'A metal probe connected to a refrigeration unit (CO2 or nitrous oxide), with a tip that reaches very low temperatures in a controlled manner.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en cirurgia de despreniment de retina per crear una adhesió coriorretiniana al voltant d\'estrips retinians mitjançant congelació controlada.',
      es: 'Se utiliza en cirugía de desprendimiento de retina para crear una adhesión coriorretiniana alrededor de desgarros retinianos mediante congelación controlada.',
      en: 'Used in retinal detachment surgery to create a chorioretinal adhesion around retinal tears through controlled freezing.',
    ),
    tip: LocalizedText(
      ca: 'L\'aplicació s\'ha de controlar sota visió oftalmoscòpica indirecta per evitar una criocoagulació excessiva que podria afavorir la proliferació vitreoretiniana.',
      es: 'La aplicación debe controlarse bajo visión oftalmoscópica indirecta para evitar una criocoagulación excesiva que podría favorecer la proliferación vitreorretiniana.',
      en: 'Application should be monitored under indirect ophthalmoscopic view to avoid excessive cryocoagulation, which could favor proliferative vitreoretinopathy.',
    ),
    isNew: true,
  ),
  Instrument(
