      es: 'Se utiliza en la cirugía de estrabismo para aislar el músculo extraocular diana de la esclera y los tejidos circundantes antes de su resección o recesión.',
      en: 'Used in strabismus surgery to isolate the target extraocular muscle from the sclera and surrounding tissue before its recession or resection.',
    ),
