      es: 'Su punta roma permite deslizarse bajo el músculo sin perforar la esclera, un riesgo importante dado su escaso grosor en algunas zonas.',
      en: 'Its blunt tip allows sliding under the muscle without perforating the sclera, an important risk given its thinness in certain areas.',
    ),
