  Instrument(
    id: 'mascarilla-laringea',
    name: LocalizedText(ca: 'Mascareta laríngia (LMA)', es: 'Mascarilla laríngea (LMA)', en: 'Laryngeal mask airway (LMA)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Laryngeal mask airway'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu de via aèria supraglòtica amb baló inflable que segella al voltant de l\'entrada de la laringe.',
      es: 'Dispositivo de vía aérea supraglótica con balón inflable que sella alrededor de la entrada de la laringe.',
      en: 'Supraglottic airway device with an inflatable cuff that seals around the laryngeal inlet.',
    ),
    use: LocalizedText(
      ca: 'Alternativa a la intubació en procediments curts sense necessitat de relaxació muscular completa.',
      es: 'Alternativa a la intubación en procedimientos cortos sin necesidad de relajación muscular completa.',
      en: 'Alternative to intubation for short procedures that do not require full muscle relaxation.',
    ),
    tip: LocalizedText(
      ca: 'No protegeix davant l\'aspiració de contingut gàstric — contraindicada si hi ha risc-elevat d\'aspiració.',
      es: 'No protege frente a la aspiración de contenido gástrico — contraindicada si hay riesgo elevado de aspiración.',
      en: 'Does not protect against gastric content aspiration — contraindicated when aspiration risk is high.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/3/38/Airway.larynxmasker.laryngeal.mask.gelei.JPG',
      license: 'CC BY-SA 3.0',
      attribution: 'Qqq1, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Airway.larynxmasker.laryngeal.mask.gelei.JPG',
    ),
  ),
  Instrument(
    id: 'canula-guedel',
    name: LocalizedText(ca: 'Cànula de Guedel', es: 'Cánula de Guedel', en: 'Guedel cannula'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Oropharyngeal airway'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Cànula corba d\'un sol ús que es col·loca a la boca per mantenir la via aèria oberta.',
      es: 'Cánula curva de un solo uso que se coloca en la boca para mantener la vía aérea abierta.',
      en: 'Curved single-use airway placed in the mouth to keep the airway open.',
    ),
    use: LocalizedText(
      ca: 'Evita l\'obstrucció de la via aèria per caiguda de la llengua en pacients sedats o inconscients.',
      es: 'Evita la obstrucción de la vía aérea por caída de la lengua en pacientes sedados o inconscientes.',
      en: 'Prevents airway obstruction from the tongue falling back in sedated or unconscious patients.',
    ),
    tip: LocalizedText(
      ca: 'La mida es tria mesurant des de la comissura labial fins al lòbul de l\'orella.',
      es: 'La talla se elige midiendo desde la comisura labial hasta el lóbulo de la oreja.',
      en: 'Size is chosen by measuring from the corner of the mouth to the earlobe.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/5/58/One-piece_Guedel_Airways.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Intersurgical Ltd, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:One-piece_Guedel_Airways.jpg',
    ),
  ),
  Instrument(
