    icon: 'tool',
    description: LocalizedText(
      ca: 'Bossa de ventilació manual amb vàlvula unidireccional, no depèn de font de gas per inflar-se.',
      es: 'Bolsa de ventilación manual con válvula unidireccional, no depende de una fuente de gas para inflarse.',
      en: 'Manual ventilation bag with a one-way valve, does not need a gas source to reinflate.',
    ),
    use: LocalizedText(
      ca: 'Ventilació manual d\'urgència en aturada respiratòria o abans de disposar d\'una via aèria definitiva.',
      es: 'Ventilación manual de urgencia en parada respiratoria o antes de disponer de una vía aérea definitiva.',
      en: 'Emergency manual ventilation during respiratory arrest or before a definitive airway is secured.',
