  Instrument(
    id: 'pinza-magill',
    name: LocalizedText(ca: 'Pinces de Magill', es: 'Pinzas de Magill', en: 'Magill forceps'),
    category: InstrumentCategory.diseccion,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Magill forceps'],
    icon: 'pinch',
    description: LocalizedText(
      ca: 'Pinces corbes sense mossegada dentada, dissenyades per encaixar amb la línia de visió del laringoscopi.',
      es: 'Pinzas curvas sin mordida dentada, diseñadas para encajar con la línea de visión del laringoscopio.',
      en: 'Curved, non-toothed forceps designed to fit the laryngoscope\'s line of sight.',
    ),
    use: LocalizedText(
      ca: 'Guien el tub endotraqueal cap a la glotis en intubacions difícils, o retiren cossos estranys de la orofaringe.',
      es: 'Guían el tubo endotraqueal hacia la glotis en intubaciones difíciles, o retiran cuerpos extraños de la orofaringe.',
      en: 'Guide the endotracheal tube toward the glottis in difficult intubations, or remove foreign bodies from the oropharynx.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/e/e9/Magill_forceps_open.jpg',
