  Instrument(
    id: 'fiador-intubacion',
    name: LocalizedText(ca: 'Fiador d\'intubació (bougie/estilet)', es: 'Fiador de intubación (bougie/estilete)', en: 'Intubating stylet (bougie/stylet)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Bougie', 'Intubating stylet'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Guia semirígida i corbable que s\'introdueix dins o al costat del tub endotraqueal per facilitar-ne el pas.',
      es: 'Guía semirrígida y curvable que se introduce dentro o junto al tubo endotraqueal para facilitar su paso.',
      en: 'Semi-rigid, bendable guide inserted inside or alongside the endotracheal tube to ease its passage.',
    ),
    use: LocalizedText(
      ca: 'Intubacions amb visió glòtica limitada, quan el tub sol no es pot dirigir amb prou precisió.',
      es: 'Intubaciones con visión glótica limitada, cuando el tubo solo no puede dirigirse con suficiente precisión.',
      en: 'Intubations with limited glottic view, when the tube alone cannot be aimed precisely enough.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/c/ce/PocketBougie.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'James Heilman, MD, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:PocketBougie.jpg',
