  Instrument(
    id: 'aguja-tuohy',
    name: LocalizedText(ca: 'Agulla de Tuohy', es: 'Aguja de Tuohy', en: 'Tuohy needle'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Epidural needle', 'Huber-point needle', 'Aguja epidural'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Agulla hipodèrmica de calibre gros amb la punta lleugerament corbada i un orifici lateral (punta de Huber), dissenyada per localitzar l\'espai epidural i dirigir-hi un catèter.',
      es: 'Aguja hipodérmica de calibre grueso con la punta ligeramente curvada y un orificio lateral (punta de Huber), diseñada para localizar el espacio epidural y dirigir un catéter hacia él.',
      en: 'A large-bore hypodermic needle with a slightly curved tip and lateral opening (Huber point), designed to locate the epidural space and direct a catheter through it.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per realitzar anestèsia o analgèsia epidural, habitualment amb la tècnica de pèrdua de resistència, i per inserir-hi el catèter epidural per a l\'administració contínua d\'anestèsics locals.',
      es: 'Se utiliza para realizar anestesia o analgesia epidural, habitualmente con la técnica de pérdida de resistencia, y para insertar el catéter epidural que permite la administración continua de anestésicos locales.',
      en: 'Used to perform epidural anesthesia or analgesia, typically with the loss-of-resistance technique, and to thread the epidural catheter for continuous local anesthetic administration.',
    ),
    tip: LocalizedText(
      ca: 'El biaix amb orifici lateral permet dirigir el catèter cefàlicament sense que aquest quedi tallat per la punta de l\'agulla.',
      es: 'El bisel con orificio lateral permite dirigir el catéter en sentido cefálico sin que la punta de la aguja lo seccione.',
      en: 'The lateral-opening bevel allows the catheter to be directed cephalad without the needle tip shearing it.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/89/Tuohy.jpg',
      license: 'Public domain',
      attribution: 'Erich Schulz, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Tuohy.jpg',
    ),
  ),
  Instrument(
    id: 'aguja-espinal',
    name: LocalizedText(ca: 'Agulla espinal (intradural)', es: 'Aguja espinal (intradural)', en: 'Spinal needle'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Aguja intradural', 'Whitacre needle', 'Quincke needle', 'Aguja de raquianestesia', 'Lumbar puncture needle'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Agulla fina de calibre petit, amb bisell tallant (Quincke) o punta de llapis atraumàtica (Whitacre/Sprotte), utilitzada per puncionar l\'espai subaracnoidi.',
      es: 'Aguja fina de calibre pequeño, con bisel cortante (Quincke) o punta de lápiz atraumática (Whitacre/Sprotte), utilizada para puncionar el espacio subaracnoideo.',
      en: 'A thin, small-gauge needle with either a cutting bevel (Quincke) or an atraumatic pencil-point tip (Whitacre/Sprotte), used to puncture the subarachnoid space.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per administrar anestèsia raquídia (intradural) injectant anestèsic local al líquid cefalorraquidi, i també per a puncions lumbars diagnòstiques.',
      es: 'Se utiliza para administrar anestesia raquídea (intradural) inyectando anestésico local en el líquido cefalorraquídeo, y también para punciones lumbares diagnósticas.',
      en: 'Used to administer spinal (intrathecal) anesthesia by injecting local anesthetic into the cerebrospinal fluid, and also for diagnostic lumbar punctures.',
    ),
    tip: LocalizedText(
      ca: 'Les puntes de llapis (Whitacre/Sprotte) redueixen la incidència de cefalea post-punció dural en comparació amb les agulles de bisell tallant Quincke.',
      es: 'Las puntas de lápiz (Whitacre/Sprotte) reducen la incidencia de cefalea post-punción dural en comparación con las agujas de bisel cortante Quincke.',
      en: 'Pencil-point tips (Whitacre/Sprotte) reduce the incidence of post-dural-puncture headache compared with cutting-bevel Quincke needles.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/d/d4/Spinal_needles.jpg',
      license: 'Public Domain',
      attribution: 'Jojo (Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Spinal_needles.jpg',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'videolaringoscopio',
    name: LocalizedText(ca: 'Videolaringoscopi', es: 'Videolaringoscopio', en: 'Video laryngoscope'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['GlideScope', 'McGrath', 'C-MAC', 'Indirect video laryngoscope'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Laringoscopi amb una pala corbada que incorpora una microcàmera que transmet la imatge de la glotis a una pantalla, permetent la visualització indirecta de la via aèria.',
      es: 'Laringoscopio con una pala curvada que incorpora una microcámara que transmite la imagen de la glotis a una pantalla, permitiendo la visualización indirecta de la vía aérea.',
      en: 'A laryngoscope with a curved blade that incorporates a miniature camera transmitting the glottic image to a screen, enabling indirect visualization of the airway.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per facilitar la intubació endotraqueal, especialment en vies aèries difícils, ja que millora la visualització glòtica respecte a la laringoscòpia directa.',
      es: 'Se utiliza para facilitar la intubación endotraqueal, especialmente en vías aéreas difíciles, ya que mejora la visualización glótica respecto a la laringoscopia directa.',
      en: 'Used to facilitate endotracheal intubation, particularly in difficult airways, as it improves glottic visualization compared with direct laryngoscopy.',
    ),
    tip: LocalizedText(
      ca: 'Als algoritmes actuals de via aèria difícil, la videolaringoscòpia es recomana sovint com a primera opció abans de recórrer a tècniques més invasives.',
      es: 'En los algoritmos actuales de vía aérea difícil, la videolaringoscopia se recomienda a menudo como primera opción antes de recurrir a técnicas más invasivas.',
      en: 'Current difficult-airway algorithms often recommend video laryngoscopy as an initial step before moving to more invasive techniques.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/1/16/Glidescope_01.JPG',
      license: 'CC BY 3.0',
      attribution: 'DiverDave, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Glidescope_01.JPG',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'fibrobroncoscopio-intubacion',
    name: LocalizedText(ca: 'Fibrobroncoscopi flexible d\'intubació', es: 'Fibrobroncoscopio flexible de intubación', en: 'Flexible fiberoptic bronchoscope (for intubation)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Flexible fiberscope', 'Fiberoptic intubation scope', 'Awake fiberoptic scope'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Endoscopi flexible prim, amb fibra òptica o sensor digital a la punta i un canal de treball, que permet visualitzar directament la via aèria mentre s\'hi avança el tub endotraqueal a través seu.',
      es: 'Endoscopio flexible delgado, con fibra óptica o sensor digital en la punta y un canal de trabajo, que permite visualizar directamente la vía aérea mientras se avanza a través de él el tubo endotraqueal.',
      en: 'A thin flexible endoscope with a fiberoptic or digital sensor tip and a working channel, allowing direct visualization of the airway while the endotracheal tube is advanced over it.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per a la intubació fibroòptica, desperta o sota sedació, en pacients amb via aèria difícil prevista o coneguda, guiant el tub fins a la tràquea sota visió directa.',
      es: 'Se utiliza para la intubación fibroóptica, despierta o bajo sedación, en pacientes con vía aérea difícil prevista o conocida, guiando el tubo hasta la tráquea bajo visión directa.',
      en: 'Used for fiberoptic intubation, awake or under sedation, in patients with anticipated or known difficult airway, guiding the tube into the trachea under direct vision.',
    ),
    tip: LocalizedText(
      ca: 'La intubació fibroòptica desperta es considera l\'estàndard de referència per assegurar la via aèria en casos de via aèria difícil coneguda.',
      es: 'La intubación fibroóptica despierta se considera el estándar de referencia para asegurar la vía aérea en casos de vía aérea difícil conocida.',
      en: 'Awake fiberoptic intubation is considered the gold-standard technique for securing the airway in cases of known difficult airway.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/1/1c/Bronkoskop.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'HÃ¥kon Olav Leira, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Bronkoskop.jpg',
    ),
  ),
  Instrument(
    id: 'cateter-venoso-central',
    name: LocalizedText(ca: 'Catèter venós central', es: 'Catéter venoso central', en: 'Central venous catheter'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Central line', 'CVC', 'Vía central'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Catèter llarg i flexible, de diversos lúmens, que s\'insereix en una vena de gran calibre (jugular interna, subclàvia o femoral) fins a situar-ne la punta a la vena cava o l\'aurícula dreta.',
      es: 'Catéter largo y flexible, de varios lúmenes, que se inserta en una vena de gran calibre (yugular interna, subclavia o femoral) hasta situar su punta en la vena cava o la aurícula derecha.',
      en: 'A long, flexible, multi-lumen catheter inserted into a large central vein (internal jugular, subclavian, or femoral) with its tip positioned in the vena cava or right atrium.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per obtenir accés vascular fiable en cirurgia major o pacients crítics, administrar fàrmacs vasoactius o irritants i nutrició parenteral, i mesurar la pressió venosa central.',
      es: 'Se utiliza para obtener acceso vascular fiable en cirugía mayor o pacientes críticos, administrar fármacos vasoactivos o irritantes y nutrición parenteral, y medir la presión venosa central.',
      en: 'Used to obtain reliable vascular access in major surgery or critically ill patients, to administer vasoactive or irritant drugs and parenteral nutrition, and to measure central venous pressure.',
    ),
    tip: LocalizedText(
      ca: 'La col·locació guiada per ecografia en temps real ha reduït significativament les complicacions mecàniques respecte a la tècnica basada només en referències anatòmiques.',
      es: 'La colocación guiada por ecografía en tiempo real ha reducido significativamente las complicaciones mecánicas respecto a la técnica basada solo en referencias anatómicas.',
      en: 'Real-time ultrasound-guided placement has significantly reduced mechanical complications compared with landmark-based technique alone.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/a/ac/Central_venous_catheter_set.jpg',
      license: 'CC0 1.0',
      attribution: 'Mikael HÃ¤ggstrÃ¶m, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Central_venous_catheter_set.jpg',
    ),
  ),
  Instrument(
    id: 'cateter-arterial',
    name: LocalizedText(ca: 'Catèter arterial (línia arterial)', es: 'Catéter arterial (línea arterial)', en: 'Arterial catheter (arterial line)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Arterial line', 'A-line', 'Línia arterial'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Catèter curt i rígid que s\'insereix percutàniament en una artèria perifèrica, habitualment la radial, i es connecta a un sistema de transductor de pressió.',
      es: 'Catéter corto y rígido que se inserta percutáneamente en una arteria periférica, habitualmente la radial, y se conecta a un sistema de transductor de presión.',
      en: 'A short, rigid catheter inserted percutaneously into a peripheral artery, most commonly the radial artery, and connected to a pressure transducer system.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per monitoritzar la pressió arterial de manera contínua i en temps real durant cirurgia major o en pacients inestables, i per obtenir mostres repetides de gasometria arterial.',
      es: 'Se utiliza para monitorizar la presión arterial de forma continua y en tiempo real durante cirugía mayor o en pacientes inestables, y para obtener muestras repetidas de gasometría arterial.',
      en: 'Used to monitor blood pressure continuously and in real time during major surgery or in unstable patients, and to obtain repeated arterial blood gas samples.',
    ),
    tip: LocalizedText(
      ca: 'Mai s\'hi han d\'administrar fàrmacs, ja que la injecció intraarterial accidental pot provocar una lesió tissular greu.',
      es: 'Nunca deben administrarse fármacos a través de ella, ya que la inyección intraarterial accidental puede provocar una lesión tisular grave.',
      en: 'Medications should never be administered through it, since accidental intra-arterial injection can cause severe tissue injury.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/e/e0/Arterial_kateter_%28Seldinger%29.jpg',
      license: 'CC BY 3.0 / GFDL 1.2',
      attribution: 'MrArifnajafov, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Arterial_kateter_(Seldinger).jpg',
    ),
  ),
  Instrument(
    id: 'capnografo',
    name: LocalizedText(ca: 'Capnògraf (monitor de CO2 teleespiratori)', es: 'Capnógrafo (monitor de CO2 teleespiratorio)', en: 'Capnograph (end-tidal CO2 monitor)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Capnometer', 'ETCO2 monitor', 'Monitor de capnografia'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu de monitorització que mesura de manera contínua la concentració de diòxid de carboni als gasos respiratoris i en representa el traçat (capnograma) al llarg del temps.',
      es: 'Dispositivo de monitorización que mide de forma continua la concentración de dióxido de carbono en los gases respiratorios y representa su trazado (capnograma) a lo largo del tiempo.',
      en: 'A monitoring device that continuously measures carbon dioxide concentration in respiratory gases and displays it as a waveform (capnogram) over time.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per confirmar la correcta col·locació del tub endotraqueal, monitoritzar l\'adequació de la ventilació durant l\'anestèsia general i detectar precoçment complicacions respiratòries.',
      es: 'Se utiliza para confirmar la correcta colocación del tubo endotraqueal, monitorizar la adecuación de la ventilación durante la anestesia general y detectar precozmente complicaciones respiratorias.',
      en: 'Used to confirm correct endotracheal tube placement, monitor the adequacy of ventilation during general anesthesia, and detect respiratory complications early.',
    ),
    tip: LocalizedText(
      ca: 'La Societat Americana d\'Anestesiologia (ASA) l\'exigeix com a estàndard de monitorització durant l\'anestèsia general i la sedació profunda.',
      es: 'La Sociedad Americana de Anestesiología (ASA) la exige como estándar de monitorización durante la anestesia general y la sedación profunda.',
      en: 'The American Society of Anesthesiologists mandates it as a standard-of-care monitor during general anesthesia and deep sedation.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/9/9c/Capno.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Behzad39, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Capno.jpg',
    ),
  ),
  Instrument(
    id: 'pulsioximetro',
    name: LocalizedText(ca: 'Pulsioxímetre', es: 'Pulsioxímetro', en: 'Pulse oximeter'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Oxímetro de pulso', 'SpO2 monitor', 'Sensor de saturació'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu no invasiu que es col·loca habitualment al dit i que, mitjançant dues longituds d\'ona de llum, estima la saturació d\'oxigen de l\'hemoglobina arterial i la freqüència del pols.',
      es: 'Dispositivo no invasivo que se coloca habitualmente en el dedo y que, mediante dos longitudes de onda de luz, estima la saturación de oxígeno de la hemoglobina arterial y la frecuencia del pulso.',
      en: 'A noninvasive device, typically clipped onto a finger, that uses two wavelengths of light to estimate arterial hemoglobin oxygen saturation and pulse rate.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per monitoritzar de manera contínua l\'oxigenació del pacient durant l\'anestèsia, la sedació i en l\'àmbit de cures crítiques, permetent detectar precoçment la hipoxèmia.',
      es: 'Se utiliza para monitorizar de forma continua la oxigenación del paciente durante la anestesia, la sedación y en el ámbito de cuidados críticos, permitiendo detectar precozmente la hipoxemia.',
      en: 'Used to continuously monitor a patient\'s oxygenation during anesthesia, sedation, and in critical care, enabling early detection of hypoxemia.',
    ),
    tip: LocalizedText(
      ca: 'La introducció de la pulsioximetria es considera un dels avenços que més ha millorat la seguretat perioperatòria des de la seva adopció generalitzada.',
      es: 'La introducción de la pulsioximetría se considera uno de los avances que más ha mejorado la seguridad perioperatoria desde su adopción generalizada.',
      en: 'The introduction of pulse oximetry is considered one of the advances that has most improved perioperative safety since its widespread adoption.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/6/67/Fingerpulsoximeter.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Teutotechnik, Med. Produktions- und Vertriebs-GmbH, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Fingerpulsoximeter.jpg',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'neuroestimulador-periferico',
    name: LocalizedText(ca: 'Neuroestimulador perifèric (monitor de tren de quatre)', es: 'Neuroestimulador periférico (monitor de tren de cuatro)', en: 'Peripheral nerve stimulator (train-of-four monitor)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Train-of-four monitor', 'TOF-Watch', 'Monitor de relajación neuromuscular', 'Neuromuscular monitor'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu que aplica una sèrie d\'estímuls elèctrics (habitualment un tren de quatre) sobre un nervi perifèric mitjançant elèctrodes de superfície, i en registra o observa la resposta muscular.',
      es: 'Dispositivo que aplica una serie de estímulos eléctricos (habitualmente un tren de cuatro) sobre un nervio periférico mediante electrodos de superficie, y registra u observa la respuesta muscular.',
      en: 'A device that delivers a series of electrical stimuli (typically a train-of-four) to a peripheral nerve via surface electrodes and records or observes the resulting muscle response.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per monitoritzar el grau de bloqueig neuromuscular produït pels relaxants musculars durant l\'anestèsia general, i per confirmar-ne la recuperació adequada abans de l\'extubació.',
      es: 'Se utiliza para monitorizar el grado de bloqueo neuromuscular producido por los relajantes musculares durante la anestesia general, y para confirmar la recuperación adecuada antes de la extubación.',
      en: 'Used to monitor the degree of neuromuscular blockade produced by muscle relaxants during general anesthesia, and to confirm adequate recovery before extubation.',
    ),
    tip: LocalizedText(
      ca: 'Una relació de tren de quatre (TOFR) igual o superior a 0,9 indica recuperació completa de la força muscular i es considera el llindar segur per a l\'extubació.',
      es: 'Una relación de tren de cuatro (TOFR) igual o superior a 0,9 indica recuperación completa de la fuerza muscular y se considera el umbral seguro para la extubación.',
      en: 'A train-of-four ratio (TOFR) of 0.9 or greater indicates full recovery of muscle strength and is considered the safe threshold for extubation.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/5/52/TOF_watch_monitor_acceleromyography.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Paul Anthony Stewart, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:TOF_watch_monitor_acceleromyography.jpg',
    ),
  ),
  Instrument(
    id: 'manta-calentamiento-aire-forzado',
    name: LocalizedText(ca: 'Sistema d\'escalfament per aire forçat', es: 'Sistema de calentamiento por aire forzado', en: 'Forced-air warming system'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Bair Hugger', 'Manta térmica de aire forzado', 'Convective warming blanket'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Equip format per una unitat generadora d\'aire calent connectada mitjançant una mànega a una manta d\'un sol ús, perforada, que es col·loca sobre o sota el pacient i distribueix l\'aire calent de manera uniforme per convecció.',
      es: 'Equipo formado por una unidad generadora de aire caliente conectada mediante una manguera a una manta de un solo uso, perforada, que se coloca sobre o bajo el paciente y distribuye el aire caliente de forma uniforme por convección.',
      en: 'A system consisting of a warm-air generating unit connected by a hose to a perforated single-use blanket placed over or under the patient, distributing warm air evenly by convection.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per prevenir i tractar la hipotèrmia perioperatòria durant intervencions quirúrgiques prolongades, reduint el risc de complicacions associades com la infecció de la ferida quirúrgica.',
      es: 'Se utiliza para prevenir y tratar la hipotermia perioperatoria durante intervenciones quirúrgicas prolongadas, reduciendo el riesgo de complicaciones asociadas como la infección de la herida quirúrgica.',
      en: 'Used to prevent and treat perioperative hypothermia during prolonged surgical procedures, reducing the risk of associated complications such as surgical site infection.',
    ),
    tip: LocalizedText(
      ca: 'Les guies clíniques en recomanen l\'ús en procediments de més de 30 minuts de durada per mantenir la normotèrmia del pacient.',
      es: 'Las guías clínicas recomiendan su uso en procedimientos de más de 30 minutos de duración para mantener la normotermia del paciente.',
      en: 'Clinical guidelines recommend its use for procedures lasting longer than 30 minutes to maintain patient normothermia.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/b/be/Bair_Hugger_model_875.jpg',
      license: 'CC BY 4.0',
      attribution: 'Dmadeo, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Bair_Hugger_model_875.jpg',
    ),
  ),
  Instrument(
    id: 'dilatador-cuerpos-cavernosos',
    name: LocalizedText(
      ca: 'Dilatadors de cossos cavernosos',
      es: 'Dilatadores de cuerpos cavernosos',
      en: 'Corpora cavernosa dilators',
    ),
    category: InstrumentCategory.especiales,
    specialty: Specialty.andrologia,
    aliases: ['Hegar dilators', 'Brooks dilators', 'Rigicon HL Dilator'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Joc de tiges metàl·liques de calibre creixent, rectes (Hegar) o de punta corbada (Brooks), que dilaten progressivament els cossos cavernosos.',
      es: 'Juego de varillas metálicas de calibre creciente, rectas (Hegar) o de punta curva (Brooks), que dilatan progresivamente los cuerpos cavernosos.',
      en: 'Set of progressively larger metal rods, straight (Hegar) or curved-tip (Brooks), that gradually dilate the corpora cavernosa.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitzen abans d\'implantar una pròtesi de penis per crear dins de cada cos cavernós l\'espai necessari per als cilindres.',
      es: 'Se usan antes de implantar una prótesis de pene para crear dentro de cada cuerpo cavernoso el espacio necesario para los cilindros.',
      en: 'Used before penile prosthesis implantation to create the space needed for the cylinders inside each corpus cavernosum.',
    ),
    tip: LocalizedText(
      ca: 'En l\'abordatge penoescrotal, la forma plana i recta dels dilatadors de Hegar pot dificultar la dilatació distal cap al gland, per això sovint es prefereixen els de Brooks, de punta corbada, per a aquest pas.',
      es: 'En el abordaje penoescrotal, la forma plana y recta de los dilatadores de Hegar puede dificultar la dilatación distal hacia el glande, por lo que suelen preferirse los de Brooks, de punta curva, para ese paso.',
      en: 'In the penoscrotal approach, the flat, straight shape of Hegar dilators can hinder distal dilation toward the glans, which is why curved-tip Brooks dilators are often preferred for that step.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/87/Dilatatoren-Hegar.jpg',
      license: 'CC BY-SA 3.0 (dual-licensed with GFDL 1.2+)',
      attribution: 'Citizen, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Dilatatoren-Hegar.jpg',
    ),
  ),
  Instrument(
    id: 'introductor-furlow',
    name: LocalizedText(
      ca: 'Introductor de Furlow',
      es: 'Introductor de Furlow',
      en: 'Furlow inserter',
    ),
    category: InstrumentCategory.especiales,
    specialty: Specialty.andrologia,
    aliases: ['Furlow-Fisher cylinder inserter', 'Furlow insertion tool'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Instrument llarg i corbat, amb un canal intern que allotja una agulla de Keith carregada amb sutura.',
      es: 'Instrumento largo y curvo, con un canal interno que aloja una aguja de Keith cargada con sutura.',
      en: 'Long, curved instrument with an internal channel that holds a suture-loaded Keith needle.',
    ),
    use: LocalizedText(
      ca: 'Guia l\'agulla de Keith a través del cos cavernós i el gland per fixar distalment els cilindres d\'una pròtesi de penis.',
      es: 'Guía la aguja de Keith a través del cuerpo cavernoso y el glande para fijar distalmente los cilindros de una prótesis de pene.',
      en: 'Guides the Keith needle through the corpus cavernosum and glans to fix the cylinders of a penile prosthesis distally.',
    ),
    tip: LocalizedText(
      ca: 'La neteja incompleta d\'aquest instrument reutilitzable s\'ha associat a infeccions protèsiques, motiu pel qual cada cop s\'utilitzen més versions d\'un sol ús.',
      es: 'La limpieza incompleta de este instrumento reutilizable se ha asociado a infecciones protésicas, por lo que cada vez se usan más versiones de un solo uso.',
      en: 'Incomplete cleaning of this reusable instrument has been linked to prosthesis infections, which is why single-use versions are increasingly favored.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'retractor-scott',
    name: LocalizedText(
      ca: 'Retractor de Scott',
      es: 'Retractor de Scott',
      en: 'Scott retractor',
    ),
    category: InstrumentCategory.separacion,
    specialty: Specialty.andrologia,
    aliases: ['Wilson retractor', 'SKW deep scrotal retractor'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Retractor en forma d\'anell, amb corretges elàstiques que s\'ancoren als marges de la incisió penoescrotal i el mantenen fix sense necessitat d\'ajudant.',
      es: 'Retractor en forma de anillo, con correas elásticas que se anclan a los márgenes de la incisión penoescrotal y lo mantienen fijo sin necesidad de ayudante.',
      en: 'Ring-shaped retractor with elastic straps that anchor to the edges of the penoscrotal incision and hold it in place without an assistant.',
    ),
    use: LocalizedText(
      ca: 'Manté exposats els cossos cavernosos i l\'escrot durant la implantació d\'una pròtesi de penis per via penoescrotal.',
      es: 'Mantiene expuestos los cuerpos cavernosos y el escroto durante la implantación de una prótesis de pene por vía penoescrotal.',
      en: 'Keeps the corpora cavernosa and scrotum exposed during penoscrotal penile prosthesis implantation.',
    ),
    tip: LocalizedText(
      ca: 'El Dr. F. Brantley Scott el va introduir el 1973 juntament amb la primera pròtesi inflable; se\'n comercialitzen versions d\'un sol ús com el Wilson (Coloplast) i l\'SKW (Boston Scientific).',
      es: 'El Dr. F. Brantley Scott lo introdujo en 1973 junto con la primera prótesis inflable; se comercializan versiones desechables como el Wilson (Coloplast) y el SKW (Boston Scientific).',
      en: 'Dr. F. Brantley Scott introduced it in 1973 alongside the first inflatable prosthesis; disposable versions are sold today as the Wilson (Coloplast) and SKW (Boston Scientific) retractors.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'extensor-punta-posterior',
    name: LocalizedText(
      ca: 'Extensor de punta posterior',
      es: 'Extensor de punta posterior',
      en: 'Rear tip extender',
    ),
    category: InstrumentCategory.especiales,
    specialty: Specialty.andrologia,
    aliases: ['Rear tip extender', 'RTE'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Peça cilíndrica de silicona, disponible en diverses longituds, que encaixa per fricció a l\'extrem posterior d\'un cilindre protèsic.',
      es: 'Pieza cilíndrica de silicona, disponible en varias longitudes, que encaja por fricción en el extremo posterior de un cilindro protésico.',
      en: 'Cylindrical silicone piece, available in several lengths, that friction-fits onto the rear end of a prosthesis cylinder.',
    ),
    use: LocalizedText(
      ca: 'Ajusta la longitud final dels cilindres d\'una pròtesi de penis a l\'anatomia de cada pacient.',
      es: 'Ajusta la longitud final de los cilindros de una prótesis de pene a la anatomía de cada paciente.',
      en: 'Adjusts the final length of penile prosthesis cylinders to each patient\'s anatomy.',
    ),
    tip: LocalizedText(
      ca: 'Com que s\'uneix només per fricció, en una cirurgia de recanvi cal traccionar-lo amb cura perquè no es despengi dins del cos cavernós.',
      es: 'Como se une solo por fricción, en una cirugía de recambio hay que traccionarlo con cuidado para que no se desprenda dentro del cuerpo cavernoso.',
      en: 'Because it attaches only by friction, it must be pulled carefully during revision surgery so it does not detach inside the corpus cavernosum.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'protesis-peniana-inflable',
    name: LocalizedText(
      ca: 'Pròtesi de penis inflable',
      es: 'Prótesis de pene inflable',
      en: 'Inflatable penile prosthesis',
    ),
    category: InstrumentCategory.especiales,
    specialty: Specialty.andrologia,
    aliases: ['AMS 700', 'Coloplast Titan', 'Titan OTR', 'AMS Ambicor'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu implantable amb dos cilindres intracavernosos, una bomba escrotal i un reservori de sèrum, units per tubs de silicona.',
      es: 'Dispositivo implantable con dos cilindros intracavernosos, una bomba escrotal y un reservorio de suero, unidos por tubos de silicona.',
      en: 'Implantable device with two intracavernosal cylinders, a scrotal pump and a saline reservoir, joined by silicone tubing.',
    ),
    use: LocalizedText(
      ca: 'Tracta la disfunció erèctil: en prémer la bomba, trasllada líquid del reservori als cilindres i produeix una erecció a demanda.',
      es: 'Trata la disfunción eréctil: al presionar la bomba, traslada líquido del reservorio a los cilindros y produce una erección a demanda.',
      en: 'Treats erectile dysfunction: squeezing the pump moves fluid from the reservoir into the cylinders, producing an on-demand erection.',
    ),
    tip: LocalizedText(
      ca: 'El model Titan de Coloplast incorpora una vàlvula de bloqueig que evita la inflació espontània si la bomba es prem accidentalment durant l\'activitat diària.',
      es: 'El modelo Titan de Coloplast incorpora una válvula de bloqueo que evita la inflación espontánea si la bomba se aprieta accidentalmente durante la actividad diaria.',
      en: 'Coloplast\'s Titan model includes a lock-out valve that prevents spontaneous inflation if the pump is accidentally squeezed during daily activity.',
    ),
    isNew: true,
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/e/ee/Penile_prosthesis.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Angelatomato, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Penile_prosthesis.jpg',
    ),
  ),
  Instrument(
    id: 'protesis-peniana-maleable',
    name: LocalizedText(
      ca: 'Pròtesi de penis mal·leable',
      es: 'Prótesis de pene maleable',
      en: 'Malleable penile prosthesis',
    ),
    category: InstrumentCategory.especiales,
    specialty: Specialty.andrologia,
    aliases: ['Coloplast Genesis', 'Boston Scientific Tactra', 'AMS Spectra'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Parell de cilindres semirígids amb nucli metàl·lic flexible (filferro espiral o nitinol) recobert de silicona.',
      es: 'Par de cilindros semirrígidos con núcleo metálico flexible (alambre espiral o nitinol) recubierto de silicona.',
      en: 'Pair of semi-rigid cylinders with a bendable metal core (coiled wire or nitinol) covered in silicone.',
    ),
    use: LocalizedText(
      ca: 'S\'implanta a cada cos cavernós per donar una rigidesa permanent que permeti la penetració, sense mecanisme d\'inflació.',
      es: 'Se implanta en cada cuerpo cavernoso para dar una rigidez permanente que permita la penetración, sin mecanismo de inflado.',
      en: 'Implanted in each corpus cavernosum to provide permanent rigidity for penetration, with no inflation mechanism.',
    ),
    tip: LocalizedText(
      ca: 'En no tenir parts mòbils té una taxa de fallada mecànica molt baixa, tot i que el penis queda sempre semirígid.',
      es: 'Al no tener partes móviles tiene una tasa de fallo mecánico muy baja, aunque el pene queda siempre semirrígido.',
      en: 'Having no moving parts gives it a very low mechanical failure rate, though the penis remains permanently semi-rigid.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'protesis-testicular',
    name: LocalizedText(
