      es: 'Prótesis testicular',
      en: 'Testicular prosthesis',
    ),
    category: InstrumentCategory.especiales,
    specialty: Specialty.andrologia,
    aliases: ['Coloplast Torosa', 'testicular implant'],
    icon: 'tool',
    description: LocalizedText(
