      es: 'Implante de elastómero de silicona sólida, relleno de suero fisiológico, con forma y tamaño anatómicos de testículo.',
      en: 'Solid silicone elastomer implant filled with saline, shaped and sized like a natural testicle.',
    ),
    use: LocalizedText(
