      es: 'Se coloca en el escroto con finalidad estética tras una orquiectomía o en casos de agenesia testicular.',
      en: 'Placed in the scrotum for cosmetic restoration after orchiectomy or in cases of testicular agenesis.',
    ),
    tip: LocalizedText(
