      es: 'Existe una guía de medición de un solo uso con cuatro tallas (de 7 a 20 cc) para elegir el implante antes de la incisión definitiva.',
      en: 'A single-use sizing guide with four sizes (7 to 20 cc) is available to select the implant before the definitive incision.',
