      es: 'Lámina biológica acelular, reabsorbible, derivada de submucosa intestinal de cerdo.',
      en: 'Acellular, resorbable biologic sheet derived from porcine intestinal submucosa.',
    ),
    use: LocalizedText(
      ca: 'Cobreix el defecte de l\'albugínia després de la incisió o l\'excisió de la placa en la cirurgia de la malaltia de Peyronie.',
      es: 'Cubre el defecto de la albugínea tras la incisión o la excisión de la placa en la cirugía de la enfermedad de Peyronie.',
