      es: 'Al ser un material no autólogo, evita la morbilidad de una zona donante propia del paciente, a diferencia de los injertos de fascia o dermis.',
      en: 'Being a non-autologous material, it avoids donor-site morbidity on the patient, unlike fascia or dermal grafts.',
