  Instrument(
    id: 'medidor-cuerpos-cavernosos',
    name: LocalizedText(
      ca: 'Mesurador de cossos cavernosos',
      es: 'Medidor de cuerpos cavernosos',
      en: 'Corpora cavernosa sizer',
    ),
    category: InstrumentCategory.especiales,
    specialty: Specialty.andrologia,
    aliases: ['AMS Sizer', 'Furlow-Fisher sizer'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tija calibrada amb marques mètriques que s\'introdueix dins de cada cos cavernós per mesurar-ne la longitud interna.',
      es: 'Varilla calibrada con marcas métricas que se introduce dentro de cada cuerpo cavernoso para medir su longitud interna.',
