      es: 'Pinza de anillo estrecho (3,5 mm) que agarra el conducto deferente a través de la piel intacta sin perforarla.',
      en: 'Narrow-ring clamp (3.5 mm) that grasps the vas deferens through intact skin without piercing it.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en la vasectomia sense bisturí per immobilitzar i exterioritzar el conducte deferent abans de la punció cutània.',
      es: 'Se emplea en la vasectomía sin bisturí para inmovilizar y exteriorizar el conducto deferente antes de la punción cutánea.',
      en: 'Used in no-scalpel vasectomy to immobilize and deliver the vas deferens before the skin puncture.',
    ),
