  Instrument(
    id: 'cauterio-termico-vasectomia',
    name: LocalizedText(
      ca: 'Cauteri tèrmic per al conducte deferent',
      es: 'Cauterio térmico para el conducto deferente',
      en: 'Vas deferens thermal cautery unit',
    ),
    category: InstrumentCategory.corte,
    specialty: Specialty.andrologia,
    aliases: ['Vas cautery', 'Vasectomy needle electrode', 'Sturgeon vas cautery'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Unitat de cauterització tèrmica, amb elèctrode fi intercanviable, que crema la mucosa de la llum del conducte deferent.',
      es: 'Unidad de cauterización térmica, con electrodo fino intercambiable, que quema la mucosa de la luz del conducto deferente.',
      en: 'Thermal cautery unit with a fine interchangeable electrode that burns the mucosal lining inside the vas lumen.',
    ),
    use: LocalizedText(
      ca: 'S\'introdueix a la llum de cada extrem seccionat del conducte deferent durant la vasectomia per obturar-lo; combinat amb interposició fascial, és el mètode d\'oclusió amb menor taxa de fracàs.',
      es: 'Se introduce en la luz de cada extremo seccionado del conducto deferente durante la vasectomía para ocluirlo; combinado con interposición fascial, es el método de oclusión con menor tasa de fracaso.',
      en: 'Inserted into the lumen of each cut vas end during vasectomy to occlude it; combined with fascial interposition, it is the occlusion method with the lowest failure rate.',
    ),
    tip: LocalizedText(
      ca: 'A diferència de l\'electrocoagulació externa, actua només dins la llum i redueix el risc de lesionar l\'artèria testicular adjacent.',
      es: 'A diferencia de la electrocoagulación externa, actúa solo dentro de la luz y reduce el riesgo de lesionar la arteria testicular adyacente.',
      en: 'Unlike external electrocoagulation, it acts only inside the lumen, lowering the risk of injuring the adjacent testicular artery.',
    ),
    isNew: true,
  ),
  Instrument(
    id: 'pinza-aproximadora-vasovasostomia',
    name: LocalizedText(
