      es: 'Pinza de doble o triple rama con microespículas de acero que sujetan únicamente la adventicia de los dos extremos del conducto deferente.',
      en: 'Double- or triple-armed clamp with fine steel microspikes that grip only the adventitia of the two vas deferens ends.',
    ),
    use: LocalizedText(
      ca: 'Manté alineats i immòbils els dos caps del conducte deferent (o l\'epidídim) durant la sutura microquirúrgica en la vasovasostomia i la vasoepididimostomia.',
      es: 'Mantiene alineados e inmóviles los dos cabos del conducto deferente (o el epidídimo) durante la sutura microquirúrgica en la vasovasostomía y la vasoepididimostomía.',
      en: 'Holds both vas deferens ends (or the epididymis) aligned and motionless during microsurgical suturing in vasovasostomy and vasoepididymostomy.',
    ),
    tip: LocalizedText(
      ca: 'Les microespícules només s\'enganxen a l\'adventícia, sense comprimir la mucosa, cosa que evita el lliscament sense necessitat de gran força de tancament.',
      es: 'Las microespículas solo se enganchan en la adventicia, sin comprimir la mucosa, lo que evita el deslizamiento sin necesidad de gran fuerza de cierre.',
      en: 'The microspikes engage only the adventitia without compressing the mucosa, preventing slippage without needing strong clamping force.',
    ),
    isNew: true,
  ),
