      es: 'Identifica y preserva la arteria testicular, distinguiéndola de las venas, durante la varicocelectomía microquirúrgica subinguinal y la reversión de la vasectomía (vasovasostomía).',
      en: 'Identifies and helps preserve the testicular artery, distinguishing it from veins, during subinguinal microsurgical varicocelectomy and vasectomy reversal (vasovasostomy).',
